B.bak=new A.dk("\u0623\u062f\u0639\u064a\u0629 \u0627\u0644\u0645\u0633\u0627\u0621","\u0627\u0644\u0644\u0651\u064e\u0647\u0645 \u0628\u0643\u064e \u0623\u0645\u0633\u064e\u064a\u0646\u0627 \u0648\u0628\u0643\u064e \u0623\u0635\u0628\u064e\u062d\u0646\u0627\u060c \u0648\u0628\u0643\u064e \u0646\u064e\u062d\u064a\u0627 \u0648\u0628\u0643\u064e \u0646\u0645\u0648\u062a\u064f \u060c \u0648\u0625\u0644\u064a\u0643\u064e \u0627\u0644\u0645\u0635\u064a\u0631\u064f",1,B.yh)
B.aEq=s(["\u0645\u0646 \u0642\u0627\u0644: \u0631\u064e\u0636\u064a\u062a\u064f \u0628\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0631\u0628\u0651\u064b\u0627\u060c \u0648\u0628\u0627\u0644\u0625\u0633\u0644\u0627\u0645\u0650 \u062f\u064a\u0646\u064b\u0627\u060c \u0648\u0628\u0645\u064f\u062d\u0645\u0651\u064e\u062f\u064d \u0631\u0633\u0648\u0644\u064b\u0627\u060c \u0648\u062c\u064e\u0628\u062a \u0644\u064e\u0647\u064f \u0627\u0644\u062c\u0646\u0651\u064e\u0629\u064f.","\u0627\u0644\u0631\u0627\u0648\u064a :\u0623\u0628\u0648 \u0633\u0639\u064a\u062f \u0627\u0644\u062e\u062f\u0631\u064a\u060c \u0627\u0644\u0645\u062d\u062f\u062b: \u0627\u0644\u0623\u0644\u0628\u0627\u0646\u064a\u060c \u0627\u0644\u0645\u0635\u062f\u0631 :\u0635\u062d\u064a\u062d \u0623\u0628\u064a \u062f\u0627\u0648\u062f ",'\u0627\u0644\u062f\u0639\u0627\u0621 \u0647\u0648 \u0627\u0644\u0639\u0628\u0627\u062f\u0629 \u0648\u064a\u062e\u0628\u0631 \u0627\u0644\u0646\u0628\u064a \ufdfa \u0639\u0646 \u062f\u0639\u0627\u0621 \u0645\u0646 \u0627\u0644\u0623\u062f\u0639\u064a\u0629 \u0644\u0647 \u0641\u0636\u0644 \u0643\u0628\u064a\u0631\u060c \u062d\u064a\u062b \u064a\u0642\u0648\u0644: \u0645\u0646 \u0642\u0627\u0644: \u0631\u0636\u064a\u062a \u0628\u0627\u0644\u0644\u0647 \u0631\u0628\u0627\u060c \u0623\u064a: \u0642\u0646\u0639\u062a \u0628\u0623\u0646 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0647\u0648 \u0627\u0644\u062e\u0627\u0644\u0642 \u0648\u0627\u0644\u0633\u064a\u062f \u0648\u0627\u0644\u0645\u0627\u0644\u0643 \u0648\u0627\u0644\u0645\u0635\u0644\u062d \u0648\u0627\u0644\u0645\u0631\u0628\u064a \u0644\u062e\u0644\u0642\u0647 \u0648\u0627\u0644\u0645\u062f\u0628\u0631 \u0623\u0645\u0648\u0631\u0647\u0645\u060c \u0648\u0644\u0633\u062a \u0628\u0645\u0643\u0631\u0647 \u0639\u0644\u0649 \u0630\u0644\u0643 \u0628\u0644 \u0623\u0646\u0627 \u0631\u0627\u0636 \u0628\u0647\u060c \u0648\u0628\u0627\u0644\u0625\u0633\u0644\u0627\u0645 \u062f\u064a\u0646\u0627\u060c \u0623\u064a: \u0648\u0643\u0630\u0644\u0643 \u0631\u0636\u064a\u062a \u0623\u0646 \u0623\u062f\u064a\u0646 \u0628\u062f\u064a\u0646 \u0627\u0644\u0625\u0633\u0644\u0627\u0645 \u0639\u0645\u0627 \u0633\u0648\u0627\u0647 \u0645\u0646 \u0627\u0644\u0623\u062f\u064a\u0627\u0646\u060c \u0648\u0628\u0645\u062d\u0645\u062f \u0631\u0633\u0648\u0644\u0627\u060c \u0623\u064a \u0648\u0643\u0630\u0644\u0643 \u0631\u0636\u064a\u062a \u0628\u0645\u062d\u0645\u062f \ufdfa \u0631\u0633\u0648\u0644\u0627 \u0645\u0646 \u0627\u0644\u0644\u0647 \u0645\u062e\u0627\u0644\u0641\u0627 \u0645\u0646 \u0639\u0627\u0646\u062f \u0648\u0643\u0641\u0631 \u0628\u0647\u061b "\u0648\u062c\u0628\u062a \u0644\u0647 \u0627\u0644\u062c\u0646\u0629"\u060c \u0623\u064a: \u0625\u0646 \u0645\u0646 \u064a\u0642\u0648\u0644 \u0647\u0630\u0627 \u0627\u0644\u062f\u0639\u0627\u0621\u060c \u0643\u0627\u0646 \u062d\u0642\u0627 \u0639\u0644\u0649 \u0627\u0644\u0644\u0647 \u0623\u0646 \u064a\u062f\u062e\u0644\u0647 \u0627\u0644\u062c\u0646\u0629.'],t.s)
B.bas=new A.dk("\u0623\u062f\u0639\u064a\u0629 \u0646\u0628\u0648\u064a\u0629","\u0631\u064e\u0636\u064a\u0640\u062a\u064f \u0628\u0627\u0644\u0644\u0647 \u0631\u0628\u0640\u0627\u064b \u0648\u0628\u0627\u0644\u0625\u0633\u0644\u0627\u0645\u0650 \u062f\u064a\u0640\u0646\u0627\u064b \u0648\u0628\u0650\u0645\u062d\u064e\u0640\u0645\u062f\u064d \u0635\u0644\u0650\u0651\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645 \u0646\u064e\u0628\u0650\u064a\u0640\u0627\u064b \u0648\u0631\u064e\u0633\u064f\u0648\u0644\u064b\u0627",1,B.aEq)
B.aJh=s(["\u062e\u0631\u062c \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0645\u0646 \u0639\u0646\u062f \u062c\u0648\u064a\u0631\u064a\u0629 \u0648\u0643\u0627\u0646 \u0627\u0633\u0645\u0647\u0627 -\u0628\u064e\u0631\u0651\u064e\u0629\u064e- \u0641\u062d\u0648\u0644 \u0627\u0633\u0645\u0647\u0627\u060c \u0641\u062e\u0631\u062c \u0648\u0647\u064a \u0641\u064a \u0645\u064f\u0635\u064e\u0644\u0651\u064e\u0627\u0647\u0627\u060c \u0648\u0631\u062c\u0639 \u0648\u0647\u064a \u0641\u064a \u0645\u064f\u0635\u064e\u0644\u0651\u064e\u0627\u0647\u0627\u060c \u0641\u0642\u0627\u0644: \u0644\u0645 \u062a\u0632\u0627\u0644\u064a \u0641\u064a \u0645\u0635\u0644\u0627\u0643 \u0647\u0630\u0627\u061f! \u0642\u0627\u0644\u062a: \u0646\u0639\u0645. \u0642\u0627\u0644: \u0642\u062f \u0642\u0644\u062a \u0628\u0639\u062f\u0643 \u0623\u0631\u0628\u0639 \u0643\u0644\u0645\u0627\u062a \u062b\u0644\u0627\u062b \u0645\u0631\u0627\u062a \u0644\u0648 \u0648\u0632\u0646\u062a \u0628\u0645\u0627 \u0642\u0644\u062a \u0644\u0648\u0632\u0646\u062a\u0647\u0646: \u0633\u0628\u062d\u0627\u0646 \u0627\u0644\u0644\u0647 \u0648\u0628\u062d\u0645\u062f\u0647 \u0639\u062f\u062f \u062e\u0644\u0642\u0647\u060c \u0648\u0631\u0636\u0627 \u0646\u0641\u0633\u0647\u060c \u0648\u0632\u0646\u0629 \u0639\u0631\u0634\u0647\u060c \u0648\u0645\u062f\u0627\u062f \u0643\u0644\u0645\u0627\u062a\u0647.","\u0627\u0644\u0631\u0627\u0648\u064a :\u0639\u0628\u062f\u0627\u0644\u0644\u0647 \u0628\u0646 \u0639\u0628\u0627\u0633 \u060c \u0627\u0644\u0645\u0635\u062f\u0631: \u0633\u0646\u0646 \u0623\u0628\u064a \u062f\u0627\u0648\u062f ","\u0630\u0643\u0631 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0645\u0646 \u0623\u0641\u0636\u0644 \u0627\u0644\u0623\u0639\u0645\u0627\u0644 \u0648\u0623\u062c\u0644\u0647\u0627\u060c \u0648\u0647\u0648 \u064a\u0631\u0641\u0639 \u0627\u0644\u0625\u0646\u0633\u0627\u0646 \u062f\u0631\u062c\u0627\u062a\u060c \u0648\u0628\u0647 \u064a\u0646\u0627\u0644 \u0627\u0644\u062e\u064a\u0631 \u0648\u0627\u0644\u0628\u0631\u0643\u0627\u062a.","\u0623\u0646 \u062a\u0633\u0628\u064a\u062d \u0627\u0644\u0644\u0647 \u0639\u0632 \u0648\u062c\u0644 \u0648\u062a\u062d\u0645\u064a\u062f\u0647 \u0628\u0639\u062f\u062f \u062c\u0645\u064a\u0639 \u0645\u062e\u0644\u0648\u0642\u0627\u062a\u0647\u060c \u0648\u0645\u062e\u0644\u0648\u0642\u0627\u062a \u0627\u0644\u0644\u0647 \u0639\u0632 \u0648\u062c\u0644 \u0644\u0627 \u064a\u062d\u0635\u064a\u0647\u0627 \u0625\u0644\u0627 \u0627\u0644\u0644\u0647\u060c \u0648\u0628\u0645\u0642\u062f\u0627\u0631 \u0631\u0636\u0627 \u0630\u0627\u062a\u0647 \u0627\u0644\u0634\u0631\u064a\u0641\u0629\u060c \u0648\u0628\u0645\u0642\u062f\u0627\u0631 \u0632\u0646\u0629 \u0639\u0631\u0634\u0647 \u0627\u0644\u0630\u064a \u0644\u0627 \u064a\u0639\u0644\u0645 \u062b\u0642\u0644\u0647 \u0625\u0644\u0627 \u0627\u0644\u0644\u0647 \u0633\u0628\u062d\u0627\u0646\u0647 \u0648\u062a\u0639\u0627\u0644\u0649.","\u0648\u0627\u0644\u0645\u0650\u062f\u0627\u062f\u064f \u0645\u0627 \u064a\u0643\u062a\u0628 \u0628\u0647 \u0627\u0644\u0634\u064a\u0621\u060c \u0648\u0643\u0644\u0645\u0627\u062a \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0644\u0627 \u064a\u0642\u0627\u0631\u0646 \u0628\u0647\u0627 \u0634\u064a\u0621\u060c \u0648\u0644\u0627 \u064a\u0646\u0641\u062f \u0645\u062f\u0627\u062f\u0647\u0627\u060c \u0648\u0643\u0648\u0646 \u0627\u0644\u062b\u0648\u0627\u0628 \u0628\u0639\u062f\u062f \u0630\u0644\u0643 \u0645\u0645\u0627 \u0644\u0627 \u064a\u0639\u0644\u0645\u0647 \u0625\u0644\u0627 \u0627\u0644\u0644\u0647\u060c \u0648\u0644\u0627 \u064a\u0646\u0641\u062f \u064a\u062f\u0644 \u0639\u0644\u0649 \u0639\u0638\u0645\u062a\u0647\u060c \u0648\u0647\u0630\u0627 \u0645\u0646 \u0627\u0644\u062a\u0639\u0644\u064a\u0645 \u0627\u0644\u0646\u0628\u0648\u064a \u0648\u0625\u0631\u0634\u0627\u062f\u0647 \u0625\u0644\u0649 \u062c\u0648\u0627\u0645\u0639 \u0627\u0644\u0643\u0644\u0645 \u0627\u0644\u062a\u064a \u062a\u062d\u0645\u0644 \u0627\u0644\u0642\u0644\u064a\u0644 \u0645\u0646 \u0627\u0644\u0623\u0644\u0641\u0627\u0638\u060c \u0648\u064a\u0639\u0637\u064a \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647\u0627 \u0639\u0638\u064a\u0645 \u0627\u0644\u0641\u0636\u0644 \u0648\u0627\u0644\u062b\u0648\u0627\u0628."],t.s)
B.baf=new A.dk("\u0627\u0644\u062a\u0633\u0628\u064a\u062d","\u0633\u064f\u0628\u062d\u0640\u0627\u0646\u064e \u0627\u0644\u0644\u0647 \u0648\u0628\u0650\u062d\u0645\u0640\u062f\u0650\u0647 \u0639\u062f\u062f\u064e \u062e\u0644\u0640\u0642\u0650\u0647 \u0648\u0631\u0636\u0640\u0627 \u0646\u0641\u0633\u0650\u0640\u0647 \u0648\u0632\u0650\u0646\u064e\u0640\u0629 \u0639\u064e\u0640\u0631\u0634\u0650\u0640\u0647 \u0648\u0645\u0650\u0640\u062f\u0627\u062f\u064e \u0643\u0644\u0650\u0645\u0640\u0627\u062a\u0640\u0647",3,B.aJh)
B.aRs=s(["\u0633\u064a\u062f \u0627\u0644\u0627\u0633\u062a\u063a\u0641\u0627\u0631 \u0623\u0646 \u062a\u0642\u0648\u0644: \u0627\u0644\u0644\u0647\u0645 \u0623\u0646\u062a \u0631\u0628\u064a \u0644\u0627 \u0625\u0644\u0647 \u0625\u0644\u0627 \u0623\u0646\u062a\u060c \u062e\u0644\u0642\u062a\u0646\u064a \u0648\u0623\u0646\u0627 \u0639\u0628\u062f\u0643\u060c \u0648\u0623\u0646\u0627 \u0639\u0644\u0649 \u0639\u0647\u062f\u0643 \u0648\u0648\u0639\u062f\u0643 \u0645\u0627 \u0627\u0633\u062a\u0637\u0639\u062a\u060c \u0623\u0639\u0648\u0630 \u0628\u0643 \u0645\u0646 \u0634\u0631 \u0645\u0627 \u0635\u0646\u0639\u062a\u060c \u0623\u0628\u0648\u0621 \u0644\u0643 \u0628\u0646\u0639\u0645\u062a\u0643 \u0639\u0644\u064a\u060c \u0648\u0623\u0628\u0648\u0621 \u0644\u0643 \u0628\u0630\u0646\u0628\u064a \u0641\u0627\u063a\u0641\u0631 \u0644\u064a\u061b \u0641\u0625\u0646\u0647 \u0644\u0627 \u064a\u063a\u0641\u0631 \u0627\u0644\u0630\u0646\u0648\u0628 \u0625\u0644\u0627 \u0623\u0646\u062a. \u0642\u0627\u0644: \u0648\u0645\u0646 \u0642\u0627\u0644\u0647\u0627 \u0645\u0646 \u0627\u0644\u0646\u0647\u0627\u0631 \u0645\u0648\u0642\u0646\u0627 \u0628\u0647\u0627\u060c \u0641\u0645\u0627\u062a \u0645\u0646 \u064a\u0648\u0645\u0647 \u0642\u0628\u0644 \u0623\u0646 \u064a\u0645\u0633\u064a\u060c \u0641\u0647\u0648 \u0645\u0646 \u0623\u0647\u0644 \u0627\u0644\u062c\u0646\u0629\u060c \u0648\u0645\u0646 \u0642\u0627\u0644\u0647\u0627 \u0645\u0646 \u0627\u0644\u0644\u064a\u0644 \u0648\u0647\u0648 \u0645\u0648\u0642\u0646 \u0628\u0647\u0627\u060c \u0641\u0645\u0627\u062a \u0642\u0628\u0644 \u0623\u0646 \u064a\u0635\u0628\u062d\u060c \u0641\u0647\u0648 \u0645\u0646 \u0623\u0647\u0644 \u0627\u0644\u062c\u0646\u0629.","\u0627\u0644\u0631\u0627\u0648\u064a : \u0634\u062f\u0627\u062f \u0628\u0646 \u0623\u0648\u0633 \u060c \u0627\u0644\u0645\u062d\u062f\u062b : \u0627\u0644\u0628\u062e\u0627\u0631\u064a","\u0648\u0641\u064a \u0647\u0630\u0627 \u0627\u0644\u062d\u062f\u064a\u062b \u0628\u064a\u0627\u0646 \u0645\u0646 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0644\u0623\u0641\u0636\u0644 \u0635\u064a\u063a \u0627\u0644\u0627\u0633\u062a\u063a\u0641\u0627\u0631 \u0648\u0623\u062d\u0628\u0647\u0627 \u0625\u0644\u0649 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649\u060c \u0648\u0623\u0643\u062b\u0631\u0647\u0627 \u062b\u0648\u0627\u0628\u0627\u060c \u0648\u0623\u0631\u062c\u0627\u0647\u0627 \u0641\u064a \u0627\u0644\u0642\u0628\u0648\u0644\u061b \u0641\u0623\u062e\u0628\u0631 \ufdfa \u0623\u0646 \u0633\u064a\u062f \u0627\u0644\u0627\u0633\u062a\u063a\u0641\u0627\u0631\u060c \u0623\u064a: \u0623\u0641\u0636\u0644 \u0635\u064a\u063a \u0627\u0644\u0627\u0633\u062a\u063a\u0641\u0627\u0631 \u0648\u0623\u0643\u062b\u0631\u0647\u0627 \u062b\u0648\u0627\u0628\u0627\u060c \u0648\u0633\u0645\u064a \u0633\u064a\u062f\u0627 \u0644\u0623\u0646\u0647 \u062c\u0627\u0645\u0639 \u0644\u0645\u0639\u0627\u0646\u064a \u0627\u0644\u062a\u0648\u0628\u0629 \u0643\u0644\u0647\u0627.","\u0648\u0647\u0648 \u0642\u0648\u0644 \u0627\u0644\u0645\u0633\u0644\u0645: \u0627\u0644\u0644\u0647\u0645 \u0623\u0646\u062a \u0631\u0628\u064a\u060c \u0644\u0627 \u0625\u0644\u0647 \u0625\u0644\u0627 \u0623\u0646\u062a\u060c \u062e\u0644\u0642\u062a\u0646\u064a\u060c \u0641\u0647\u0630\u0627 \u0625\u0642\u0631\u0627\u0631 \u0628\u062a\u0641\u0631\u062f \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0628\u0627\u0644\u0631\u0628\u0648\u0628\u064a\u0629 \u0648\u0627\u0644\u0623\u0644\u0648\u0647\u064a\u0629 \u0648\u0628\u0627\u0644\u062e\u0644\u0642\u060c \u062b\u0645 \u0623\u0642\u0631 \u0628\u062e\u0636\u0648\u0639\u0647 \u0648\u0639\u0628\u0648\u062f\u064a\u062a\u0647 \u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0641\u0642\u0627\u0644: \u0648\u0623\u0646\u0627 \u0639\u0628\u062f\u0643\u060c \u0648\u0645\u0646 \u062a\u0645\u0627\u0645 \u0627\u0644\u0639\u0628\u0648\u062f\u064a\u0629: \u0627\u0644\u0627\u0644\u062a\u0632\u0627\u0645 \u0628\u0627\u0644\u0639\u0647\u062f \u0627\u0644\u0630\u064a \u0623\u062e\u0630 \u0639\u0644\u064a\u0647 \u0628\u0627\u0644\u0627\u0644\u062a\u0632\u0627\u0645 \u0628\u0627\u0644\u062a\u0648\u062d\u064a\u062f \u0648\u0627\u0644\u0634\u0631\u0639 \u0623\u0645\u0631\u0627 \u0648\u0646\u0647\u064a\u0627\u060c \u0641\u0642\u0627\u0644: \u0648\u0623\u0646\u0627 \u0639\u0644\u0649 \u0639\u0647\u062f\u0643 \u0648\u0648\u0639\u062f\u0643\u060c \u0648\u0645\u0639\u0646\u0627\u0647: \u0648\u0623\u0646\u0627 \u0639\u0644\u0649 \u0645\u0627 \u0639\u0627\u0647\u062f\u062a\u0643 \u0639\u0644\u064a\u0647\u060c \u0648\u0648\u0627\u0639\u062f\u062a\u0643 \u0645\u0646 \u0627\u0644\u0625\u064a\u0645\u0627\u0646 \u0628\u0643\u060c \u0648\u0625\u062e\u0644\u0627\u0635 \u0627\u0644\u0637\u0627\u0639\u0629 \u0644\u0643.","\u0648\u0627\u0644\u0648\u0639\u062f \u0645\u0627 \u062c\u0627\u0621 \u0641\u064a \u0627\u0644\u0635\u062d\u064a\u062d\u064a\u0646 \u0639\u0644\u0649 \u0644\u0633\u0627\u0646 \u0627\u0644\u0646\u0628\u064a \ufdfa: \u0645\u0646 \u0645\u0627\u062a \u0644\u0627 \u064a\u0634\u0631\u0643 \u0628\u0627\u0644\u0644\u0647 \u0634\u064a\u0626\u0627 \u062f\u062e\u0644 \u0627\u0644\u062c\u0646\u0629\u060c \u0641\u0623\u062e\u0628\u0631 \u0628\u0623\u0646\u0647 \u0645\u0635\u062f\u0642 \u0645\u0624\u0645\u0646 \u0628\u0648\u0639\u062f \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0628\u0627\u0644\u062b\u0648\u0627\u0628 \u0639\u0644\u0649 \u0639\u0645\u0644\u0647\u060c \u0648\u0642\u0627\u0626\u0645 \u0628\u0643\u0644 \u0645\u0627 \u0643\u0644\u0641\u0647 \u0627\u0644\u0644\u0647 \u0628\u0647\u060c \u0648\u0628\u0643\u0644 \u0645\u0627 \u0648\u0639\u062f\u0647\u060c \u062b\u0645 \u0642\u064a\u062f \u0647\u0630\u0627 \u0628\u0627\u0644\u0642\u062f\u0631\u0629\u060c \u0641\u0642\u0627\u0644: \u0645\u0627 \u0627\u0633\u062a\u0637\u0639\u062a\u060c \u0641\u0627\u0644\u062a\u0632\u0627\u0645\u0647 \u0628\u0643\u0644 \u0647\u0630\u0627 \u0628\u062d\u0633\u0628 \u0627\u0644\u0642\u062f\u0631\u0629 \u0648\u0627\u0644\u0627\u0633\u062a\u0637\u0627\u0639\u0629\u060c \u0648\u0641\u064a \u0647\u0630\u0627 \u0625\u0642\u0631\u0627\u0631 \u0645\u0646\u0647 \u0628\u0636\u0639\u0641\u0647 \u0648\u062d\u0627\u062c\u062a\u0647 \u0644\u062a\u0648\u0641\u064a\u0642 \u0645\u0648\u0644\u0627\u0647\u061b \u0648\u0644\u0647\u0630\u0627 \u0642\u0627\u0644: \u0623\u0639\u0648\u0630 \u0628\u0643\u060c \u0623\u064a: \u0623\u062d\u062a\u0645\u064a \u0648\u0623\u0644\u062c\u0623 \u0625\u0644\u064a\u0643\u060c \u0645\u0646 \u0634\u0631 \u0645\u0627 \u0635\u0646\u0639\u062a\u060c \u0648\u0627\u0644\u0645\u0631\u0627\u062f \u0628\u0647 \u0627\u0644\u0639\u0630\u0627\u0628 \u0627\u0644\u0645\u062a\u0631\u062a\u0628 \u0639\u0644\u0649 \u0627\u0644\u0630\u0646\u0648\u0628 \u0648\u0627\u0644\u0645\u0639\u0627\u0635\u064a \u0627\u0644\u062a\u064a \u062a\u0624\u062f\u064a \u0628\u0627\u0644\u0625\u0646\u0633\u0627\u0646 \u0625\u0644\u0649 \u0627\u0644\u0647\u0644\u0643\u0629 \u0641\u064a \u0627\u0644\u0622\u062e\u0631\u0629.","\u0648\u0623\u0628\u0648\u0621 \u0623\u064a: \u0623\u0639\u062a\u0631\u0641 \u0644\u0643 \u0628\u0646\u0639\u0645\u062a\u0643 \u0639\u0644\u064a\u060c \u0648\u0623\u0628\u0648\u0621\u060c \u0623\u064a: \u0623\u0639\u062a\u0631\u0641 \u0644\u0643 \u0628\u0630\u0646\u0628\u064a\u060c \u0641\u0627\u063a\u0641\u0631 \u0644\u064a\u061b \u0641\u0625\u0646\u0647 \u0644\u0627 \u064a\u063a\u0641\u0631 \u0627\u0644\u0630\u0646\u0648\u0628 \u0625\u0644\u0627 \u0623\u0646\u062a\u060c \u0648\u0641\u064a \u0647\u0630\u0627 \u0625\u0642\u0631\u0627\u0631 \u0628\u0627\u0644\u0630\u0646\u0628\u060c \u0648\u0623\u0646\u0647 \u0645\u0646 \u0635\u0646\u0639 \u0627\u0644\u0645\u0631\u0621 \u0646\u0641\u0633\u0647\u060c \u0648\u0642\u062f \u0623\u0642\u0631 \u0648\u0627\u0639\u062a\u0631\u0641 \u0628\u0623\u0646\u0647 \u0644\u0627 \u064a\u063a\u0641\u0631 \u0627\u0644\u0630\u0646\u0648\u0628 \u0625\u0644\u0627 \u0627\u0644\u0644\u0647\u061b \u0644\u0643\u0645\u0627\u0644 \u0645\u0644\u0643\u0647\u060c \u0648\u0644\u0630\u0627 \u0627\u0633\u062a\u0639\u0627\u0630 \u0628\u0647 \u0645\u0646 \u0634\u0631 \u0635\u0646\u064a\u0639\u0647\u060c \u0648\u0628\u064a\u0646 \u0628\u0642\u0648\u0644\u0647: \u0623\u0628\u0648\u0621 \u0644\u0643 \u0628\u0646\u0639\u0645\u062a\u0643 \u0639\u0644\u064a \u0623\u0646 \u0639\u0635\u064a\u0627\u0646\u0647 \u0644\u0645 \u064a\u0643\u0646 \u062c\u062d\u0648\u062f\u0627 \u0644\u0646\u0639\u0645 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647\u060c \u0628\u0644 \u0647\u0648 \u0645\u0642\u0631 \u0628\u0647\u0627\u060c \u0648\u0623\u0646 \u0645\u0639\u0635\u064a\u062a\u0647 \u0643\u0627\u0646\u062a \u0639\u0646 \u0647\u0648\u0649 \u0648\u062c\u0647\u0644.","\u062b\u0645 \u0628\u064a\u0646 \ufdfa \u0623\u062c\u0631 \u0647\u0630\u0627 \u0627\u0644\u0630\u0643\u0631\u060c \u0641\u0642\u0627\u0644: \u0648\u0645\u0646 \u0642\u0627\u0644\u0647\u0627 \u0645\u0646 \u0627\u0644\u0646\u0647\u0627\u0631 \u0645\u0648\u0642\u0646\u0627 \u0628\u0647\u0627 \u0623\u064a: \u0628\u0643\u0644 \u0645\u0627 \u062a\u0636\u0645\u0646\u062a\u0647 \u0645\u0646 \u0645\u0639\u0627\u0646 \u0648\u0628\u062b\u0648\u0627\u0628\u0647\u0627\u060c \u0641\u0645\u0627\u062a \u0645\u0646 \u064a\u0648\u0645\u0647 \u0642\u0628\u0644 \u0623\u0646 \u064a\u0645\u0633\u064a\u060c \u0641\u0647\u0648 \u0645\u0646 \u0623\u0647\u0644 \u0627\u0644\u062c\u0646\u0629\u060c \u0648\u0645\u0646 \u0642\u0627\u0644\u0647\u0627 \u0645\u0646 \u0627\u0644\u0644\u064a\u0644 \u0648\u0647\u0648 \u0645\u0648\u0642\u0646 \u0628\u0647\u0627\u060c \u0641\u0645\u0627\u062a \u0642\u0628\u0644 \u0623\u0646 \u064a\u0635\u0628\u062d\u060c \u0641\u0647\u0648 \u0645\u0646 \u0623\u0647\u0644 \u0627\u0644\u062c\u0646\u0629 \u0627\u0644\u062f\u0627\u062e\u0644\u064a\u0646 \u0625\u0644\u064a\u0647\u0627 \u0645\u0639 \u0627\u0644\u0633\u0627\u0628\u0642\u064a\u0646\u060c \u0623\u0648 \u0645\u0646 \u063a\u064a\u0631 \u0633\u0627\u0628\u0642\u0629 \u0639\u0630\u0627\u0628.","\u0648\u0641\u064a \u0647\u0630\u0627 \u062d\u062b \u0648\u062a\u0631\u063a\u064a\u0628 \u0648\u062a\u0623\u0643\u064a\u062f \u0639\u0644\u0649 \u0642\u0648\u0644 \u0647\u0630\u0627 \u0627\u0644\u0630\u0643\u0631 \u064a\u0648\u0645\u064a\u0627 \u0646\u0647\u0627\u0631\u0627 \u0648\u0644\u064a\u0644\u0627."],t.s)
B.bae=new A.dk("\u062f\u0639\u0627\u0621 \u0633\u064a\u062f \u0627\u0644\u0623\u0633\u062a\u063a\u0641\u0627\u0631","\u0627\u0644\u0644\u0651\u0647\u0640\u0645 \u0623\u0646\u062a\u064e \u0631\u064e\u0628\u0650\u0640\u064a \u0644\u0627 \u0625\u0644\u0647\u064e \u0625\u0644\u0627 \u0623\u0646\u062a\u064e \u062e\u064e\u0644\u0642\u062a\u0646\u0640\u064a \u0648\u0623\u0646\u0627 \u0639\u064e\u0628\u0640\u062f\u064f\u0643\u060c \u0648\u0623\u0646\u0627 \u0639\u0644\u0640\u0649 \u0639\u064e\u0647\u0640\u062f\u0650\u0643\u064e \u0648\u064e\u0648\u0639\u0640\u062f\u0650\u0643 \u0645\u0627 \u0627\u0633\u062a\u0640\u0637\u0639\u0640\u062a\u060c \u0623\u0639\u0640\u0648\u0630\u064f \u0628\u0650\u0643\u064e \u0645\u0650\u0646 \u0634\u0640\u0631\u0650 \u0645\u0627 \u0635\u064e\u0646\u0640\u0639\u062a\u060c \u0623\u0628\u0640\u0648\u0621\u064f \u0644\u0640\u0643 \u0628\u0650\u0646\u0650\u0639\u0640\u0645\u064e\u062a\u0650\u0640\u0643 \u0639\u0644\u0640\u064a\u0651\u064e \u0648\u0623\u0628\u0640\u0648\u0621\u064f \u0628\u0630\u0646\u0640\u0628\u064a \u0641\u0627\u063a\u0641\u0640\u0650\u0631 \u0644\u064a \u0641\u0625\u0650\u0646\u0640\u0647\u064f \u0644\u0627 \u064a\u064e\u063a\u0640\u0641\u0650\u0631\u064f \u0627\u0644\u0630\u0646\u0640\u0648\u0628\u064e \u0625\u0650\u0644\u0627 \u0623\u0646\u062a",1,B.aRs)
B.aBU=s(["\u0644\u0645 \u064a\u0643\u0646 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u064a\u062f\u0639 \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u062f\u0639\u0648\u0627\u062a \u062d\u064a\u0646 \u064a\u0645\u0633\u064a\u060c \u0648\u062d\u064a\u0646 \u064a\u0635\u0628\u062d :\u0627\u0644\u0644\u0647\u0645 \u0625\u0646\u064a \u0623\u0633\u0623\u0644\u0643 \u0627\u0644\u0639\u0627\u0641\u064a\u0629 \u0641\u064a \u0627\u0644\u062f\u0646\u064a\u0627 \u0648\u0627\u0644\u0622\u062e\u0631\u0629 \u060c \u0627\u0644\u0644\u0647\u0645 \u0625\u0646\u064a \u0623\u0633\u0623\u0644\u0643 \u0627\u0644\u0639\u0641\u0648 \u0648\u0627\u0644\u0639\u0627\u0641\u064a\u0629 \u0641\u064a \u062f\u064a\u0646\u064a \u0648\u062f\u0646\u064a\u0627\u064a \u0648\u0623\u0647\u0644\u064a \u0648\u0645\u0627\u0644\u064a \u060c \u0627\u0644\u0644\u0647\u0645 \u0627\u0633\u062a\u0631 \u0639\u0648\u0631\u062a\u064a \u0648\u0622\u0645\u0646 \u0631\u0648\u0639\u0627\u062a\u064a \u060c \u0627\u0644\u0644\u0647\u0645 \u0627\u062d\u0641\u0638\u0646\u064a \u0645\u0646 \u0628\u064a\u0646 \u064a\u062f\u064a \u0648\u0645\u0646 \u062e\u0644\u0641\u064a \u0648\u0639\u0646 \u064a\u0645\u064a\u0646\u064a \u0648\u0639\u0646 \u0634\u0645\u0627\u0644\u064a \u0648\u0645\u0646 \u0641\u0648\u0642\u064a \u060c \u0648\u0623\u0639\u0648\u0630 \u0628\u0639\u0638\u0645\u062a\u0643 \u0623\u0646 \u0623\u063a\u062a\u0627\u0644 \u0645\u0646 \u062a\u062d\u062a\u064a.","\u0627\u0644\u0631\u0627\u0648\u064a : \u0639\u0628\u062f\u0627\u0644\u0644\u0647 \u0628\u0646 \u0639\u0645\u0631 \u060c \u0627\u0644\u0645\u062d\u062f\u062b : \u0627\u0644\u0623\u0644\u0628\u0627\u0646\u064a \u060c \u0627\u0644\u0645\u0635\u062f\u0631 : \u0635\u062d\u064a\u062d \u0623\u0628\u064a \u062f\u0627\u0648\u062f","\u0643\u0627\u0646 \u0627\u0644\u0646\u0628\u064a \ufdfa \u0643\u062b\u064a\u0631 \u0627\u0644\u062f\u0639\u0627\u0621 \u0644\u0631\u0628\u0647 \u0639\u0632 \u0648\u062c\u0644\u060c \u0643\u062b\u064a\u0631 \u0627\u0644\u062a\u0636\u0631\u0639 \u0625\u0644\u064a\u0647 \u0633\u0628\u062d\u0627\u0646\u0647 \u0648\u062a\u0639\u0627\u0644\u0649\u060c \u0648\u0641\u064a \u0647\u0630\u0627 \u0627\u0644\u062d\u062f\u064a\u062b \u064a\u062e\u0628\u0631 \u0627\u0644\u0635\u062d\u0627\u0628\u064a \u0627\u0644\u062c\u0644\u064a\u0644 \u0639\u0628\u062f \u0627\u0644\u0644\u0647 \u0628\u0646 \u0639\u0645\u0631 \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647\u0645\u0627 \u0623\u0646 \u0627\u0644\u0646\u0628\u064a \ufdfa \u0643\u0627\u0646 \u0644\u0647 \u062f\u0639\u0648\u0627\u062a \u0644\u0627 \u064a\u062a\u0631\u0643\u0647\u0646 \u0623\u0628\u062f\u0627\u060c \u0641\u064a\u0642\u0648\u0644: \u0644\u0645 \u064a\u0643\u0646 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u064a\u062f\u0639\u060c \u0623\u064a: \u064a\u062a\u0631\u0643\u060c \u062d\u064a\u0646 \u064a\u0645\u0633\u064a\u060c \u0623\u064a: \u0625\u0630\u0627 \u062f\u062e\u0644 \u0648\u0642\u062a \u0627\u0644\u0645\u0633\u0627\u0621\u060c \u0648\u062d\u064a\u0646 \u064a\u0635\u0628\u062d\u060c \u0623\u064a: \u0625\u0630\u0627 \u0623\u0642\u0628\u0644 \u0648\u0642\u062a \u0627\u0644\u0635\u0628\u0627\u062d.","\u0648\u064a\u0639\u0646\u064a: \u0644\u0627 \u064a\u062a\u0631\u0643 \u0627\u0644\u062f\u0639\u0627\u0621 \u0628\u0647\u0630\u0647 \u0627\u0644\u062f\u0639\u0648\u0627\u062a\u060c \u0648\u0647\u064a: \u0627\u0644\u0644\u0647\u0645 \u0625\u0646\u064a \u0623\u0633\u0623\u0644\u0643 \u0627\u0644\u0639\u0627\u0641\u064a\u0629\u060c \u0623\u064a: \u0627\u0644\u0633\u0644\u0627\u0645\u0629 \u0648\u0627\u0644\u0646\u062c\u0627\u0629\u060c \u0627\u0644\u0644\u0647\u0645 \u0625\u0646\u064a \u0623\u0633\u0623\u0644\u0643 \u0627\u0644\u0639\u0641\u0648\u060c \u0623\u064a: \u0627\u0644\u0645\u063a\u0641\u0631\u0629 \u0648\u0627\u0644\u0645\u0633\u0627\u0645\u062d\u0629\u060c \u0641\u064a \u062f\u064a\u0646\u064a \u0648\u062f\u0646\u064a\u0627\u064a\u060c \u0623\u064a: \u0641\u064a \u0627\u0644\u062f\u0646\u064a\u0627 \u0648\u0627\u0644\u0622\u062e\u0631\u0629\u060c \u0648\u0623\u0647\u0644\u064a\u060c \u0623\u064a: \u0632\u0648\u062c\u0627\u062a\u064a \u0648\u0623\u0648\u0644\u0627\u062f\u064a \u0648\u0642\u0631\u0627\u0628\u062a\u064a\u060c \u0648\u0645\u0627\u0644\u064a\u060c \u0623\u064a: \u0623\u0645\u0648\u0627\u0644\u064a \u0648\u0639\u0645\u0644\u064a\u060c \u0648\u0645\u0627 \u0641\u064a \u0645\u0639\u0646\u0649 \u0630\u0644\u0643 \u0645\u0646 \u0627\u0644\u062a\u062c\u0627\u0631\u0629 \u0648\u0627\u0644\u0628\u064a\u0639\u060c \u0648\u063a\u064a\u0631 \u0630\u0644\u0643.","\u0627\u0644\u0644\u0647\u0645 \u0627\u0633\u062a\u0631\u060c \u0623\u064a: \u0627\u062d\u0641\u0638\u060c \u0639\u0648\u0631\u062a\u064a\u060c \u0623\u064a: \u0643\u0644 \u0645\u0627 \u064a\u0633\u0648\u0624\u0646\u064a \u0646\u0634\u0631\u0647\u061b \u0645\u0646 \u0627\u0644\u0645\u0639\u0627\u064a\u0628\u060c \u0648\u0622\u0645\u0646 \u0631\u0648\u0639\u0627\u062a\u064a\u060c \u0623\u064a: \u0648\u0637\u0645\u0626\u0646\u064a \u0648\u0623\u0645\u0646\u064a \u0645\u0646 \u0643\u0644 \u0645\u0627 \u064a\u062e\u064a\u0641\u0646\u064a \u0648\u064a\u0633\u0628\u0628 \u0644\u064a \u0627\u0644\u0641\u0632\u0639\u060c \u0627\u0644\u0644\u0647\u0645 \u0627\u062d\u0641\u0638\u0646\u064a \u0645\u0646 \u0628\u064a\u0646 \u064a\u062f\u064a \u0648\u0645\u0646 \u062e\u0644\u0641\u064a\u060c \u0648\u0639\u0646 \u064a\u0645\u064a\u0646\u064a \u0648\u0639\u0646 \u0634\u0645\u0627\u0644\u064a\u060c \u0648\u0645\u0646 \u0641\u0648\u0642\u064a\u060c \u0623\u064a: \u0627\u062d\u0641\u0638\u0646\u064a \u0645\u0646 \u0643\u0644 \u062c\u0647\u0629 \u064a\u0645\u0643\u0646 \u0623\u0646 \u064a\u0635\u064a\u0628\u0646\u064a \u0645\u0646\u0647\u0627 \u0645\u0643\u0631\u0648\u0647\u060c \u0648\u0623\u0639\u0648\u0630 \u0628\u0639\u0638\u0645\u062a\u0643\u060c \u0623\u064a: \u0623\u0644\u062c\u0623 \u0648\u0623\u062d\u062a\u0645\u064a \u0628\u0639\u0638\u0645\u062a\u0643\u060c \u0648\u0642\u0648\u062a\u0643 \u0648\u0642\u062f\u0631\u062a\u0643 \u0623\u0646 \u0623\u063a\u062a\u0627\u0644\u060c \u0623\u064a: \u0623\u0646 \u064a\u062e\u0633\u0641 \u0628\u064a \u0623\u0648 \u0623\u0647\u0644\u0643\u060c \u0645\u0646 \u062a\u062d\u062a\u064a\u060c \u0648\u0625\u0646\u0645\u0627 \u0628\u0627\u0644\u063a \u0641\u064a \u062a\u062d\u062f\u064a\u062f \u0627\u0644\u062e\u0633\u0641 \u0648\u0627\u0644\u0647\u0644\u0627\u0643 \u0645\u0646 \u0627\u0644\u062c\u0647\u0629 \u0627\u0644\u062a\u062d\u062a\u064a\u0629\u061b \u0644\u0634\u062f\u0629 \u0627\u0644\u0628\u0644\u0627\u0621 \u0648\u0627\u0644\u0634\u0631 \u0628\u0647."],t.s)
B.bap=new A.dk("\u0623\u062f\u0639\u064a\u0629 \u0646\u0628\u0648\u064a\u0629","\u0627\u0644\u0644\u0647\u064f\u0640\u0645 \u0625\u0650\u0646\u0650\u0640\u064a \u0623\u0633\u0640\u0623\u0644\u0640\u0643\u064e \u0627\u0644\u0639\u0640\u0641\u0648\u064e \u0648\u0627\u0644\u0639\u0640\u0627\u0641\u0650\u0640\u064a\u0629 \u0641\u064a \u0627\u0644\u062f\u0646\u0640\u064a\u0627 \u0648\u064e\u0627\u0644\u0622\u062e\u0650\u0640\u0631\u064e\u0629\u060c \u0627\u0644\u0644\u0647\u064f\u0640\u0645 \u0625\u0650\u0646\u0650\u0651\u0640\u064a \u0623\u0633\u0640\u0623\u0644\u0640\u0643 \u0627\u0644\u0639\u0640\u0641\u0648\u064e \u0648\u064e\u0627\u0644\u0639\u0640\u0627\u0641\u0650\u0640\u064a\u0629 \u0641\u064a \u062f\u064a\u0646\u064a \u0648\u062f\u0646\u0640\u064a\u0627\u064a\u064e \u0648\u0623\u0647\u0640\u0644\u064a \u0648\u0645\u0627\u0644\u0640\u064a\u060c \u0627\u0644\u0644\u0647\u064f\u0640\u0645 \u0627\u0633\u062a\u064f\u0640\u0631 \u0639\u0640\u0648\u0631\u0627\u062a\u064a \u0648\u0622\u0645\u0650\u0640\u0646 \u0631\u064e\u0648\u0639\u0627\u062a\u0640\u064a\u060c \u0627\u0644\u0644\u0647\u064f\u0640\u0645 \u0627\u062d\u0641\u0638\u0640\u0646\u064a \u0645\u0646 \u0628\u0640\u064a\u0646\u0650 \u064a\u062f\u064a \u0648\u0645\u0650\u0646 \u062e\u0644\u0641\u0640\u064a \u0648\u0639\u0646 \u064a\u0645\u0640\u064a\u0646\u064a \u0648\u0639\u0646 \u0634\u0650\u0645\u0640\u0627\u0644\u064a \u0648\u0645\u0646 \u0641\u0648\u0642\u0640\u064a\u060c \u0648\u0623\u0639\u0640\u0648\u0630 \u0628\u0650\u0639\u064e\u0638\u0645\u0640\u062a\u0650\u0643 \u0623\u0646 \u0623\u064f\u063a\u0640\u062a\u0627\u0644\u064e \u0645\u0646 \u062a\u062d\u062a\u0640\u064a",1,B.aBU)
B.aC7=s(["\u0623\u0646 \u0623\u0628\u0627 \u0628\u0643\u0631 \u0627\u0644\u0635\u062f\u064a\u0642 \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647 \u0642\u0627\u0644 \u064a\u0627 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \u0645\u0631\u0646\u064a \u0628\u0643\u0644\u0645\u0627\u062a \u0623\u0642\u0648\u0644\u0647\u0646 \u0625\u0630\u0627 \u0623\u0635\u0628\u062d\u062a\u064f \u0648\u0625\u0630\u0627 \u0623\u0645\u0633\u064a\u062a\u064f \u0642\u0627\u0644 \u0642\u0644: \u0627\u0644\u0644\u0651\u064e\u0647\u0645 \u0641\u0627\u0637\u0650\u0631 \u0627\u0644\u0633\u0645\u0648\u0627\u062a\u0650 \u0648\u0627\u0644\u0623\u0631\u0636\u0650\u060c \u0639\u0627\u0644\u0650\u0645\u064e \u0627\u0644\u063a\u064a\u0628\u0650 \u0648\u0627\u0644\u0634\u0647\u0627\u062f\u0629\u0650\u060c \u0631\u064e\u0628\u0651\u064e \u0643\u064f\u0644\u0651\u0650 \u0634\u064a\u0621\u064d \u0648\u0645\u064e\u0644\u064a\u0643\u0647\u060c \u0623\u0634\u0647\u064e\u062f\u064f \u0623\u0646 \u0644\u0627 \u0625\u0644\u0647\u064e \u0625\u0644\u0627 \u0623\u0646\u062a\u064e\u060c \u0623\u0639\u0648\u0630 \u0628\u0643 \u0645\u0650\u0646 \u0634\u0631 \u0646\u0641\u0633\u064a \u0648\u0645\u0650\u0646 \u0634\u0631 \u0627\u0644\u0634\u064a\u0637\u0627\u0646\u0650 \u0648\u0634\u0650\u0631\u0643\u0650\u0647. \u0642\u0627\u0644: \u0642\u0644\u0647\u0627 \u0625\u0630\u0627 \u0623\u0635\u0628\u062d\u062a \u0648\u0625\u0630\u0627 \u0623\u0645\u0633\u064a\u062a\u060c \u0648\u0625\u0630\u0627 \u0623\u062e\u0630\u062a\u064e \u0645\u0636\u062c\u0639\u064e\u0643.","\u0627\u0644\u0631\u0627\u0648\u064a: \u0623\u0628\u0648 \u0647\u0631\u064a\u0631\u0629 \u060c \u0627\u0644\u0645\u062d\u062f\u062b: \u0627\u0644\u0623\u0644\u0628\u0627\u0646\u064a \u060c \u0627\u0644\u0645\u0635\u062f\u0631: \u0635\u062d\u064a\u062d \u0623\u0628\u064a \u062f\u0627\u0648\u062f","\u0648\u0641\u064a \u0627\u0644\u062d\u062f\u064a\u062b: \u0641\u0636\u0644 \u0623\u0628\u064a \u0628\u0643\u0631 \u0627\u0644\u0635\u062f\u064a\u0642 \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647\u060c \u0648\u0628\u064a\u0627\u0646 \u062d\u0631\u0635\u0647 \u0639\u0644\u0649 \u0633\u0624\u0627\u0644 \u0627\u0644\u0646\u0628\u064a \ufdfa \u0639\u0646 \u0627\u0644\u062e\u064a\u0631 \u0648\u0645\u0627 \u0641\u064a\u0647 \u0627\u0644\u062b\u0648\u0627\u0628 \u0648\u0627\u0644\u0623\u062c\u0631\u060c \u0648\u0641\u064a\u0647 \u0627\u0644\u062d\u0631\u0635 \u0639\u0644\u0649 \u0623\u0630\u0643\u0627\u0631 \u0627\u0644\u0635\u0628\u0627\u062d \u0648\u0627\u0644\u0645\u0633\u0627\u0621.","\u0623\u0646 \u0630\u0643\u0631 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0645\u0646 \u0623\u062c\u0644 \u0627\u0644\u0639\u0628\u0627\u062f\u0627\u062a \u0627\u0644\u062a\u064a \u064a\u0646\u0628\u063a\u064a \u0639\u0644\u0649 \u0627\u0644\u0625\u0646\u0633\u0627\u0646 \u0623\u0646 \u064a\u062d\u0631\u0635 \u0639\u0644\u064a\u0647\u0627\u061b \u0644\u0630\u0644\u0643 \u0643\u0627\u0646 \u0627\u0644\u0635\u062d\u0627\u0628\u0629 \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647\u0645 \u064a\u062d\u0631\u0635\u0648\u0646 \u0639\u0644\u0649 \u0627\u0644\u0630\u0643\u0631 \u0641\u064a \u062c\u0645\u064a\u0639 \u0623\u0648\u0642\u0627\u062a\u0647\u0645 \u0645\u0646 \u0627\u0644\u0644\u064a\u0644 \u0648\u0627\u0644\u0646\u0647\u0627\u0631\u060c \u0648\u064a\u0633\u0623\u0644\u0648\u0646 \u0627\u0644\u0646\u0628\u064a \ufdfa \u0623\u0646 \u064a\u0639\u0644\u0645\u0647\u0645 \u0630\u0644\u0643."],t.s)
B.bat=new A.dk("\u0623\u062f\u0639\u064a\u0629 \u0646\u0628\u0648\u064a\u0629","\u0627\u0644\u0644\u0651\u064e\u0647\u0645 \u0641\u0627\u0637\u0650\u0631 \u0627\u0644\u0633\u0645\u0648\u0627\u062a\u0650 \u0648\u0627\u0644\u0623\u0631\u0636\u0650\u060c \u0639\u0627\u0644\u0650\u0645\u064e \u0627\u0644\u063a\u064a\u0628\u0650 \u0648\u0627\u0644\u0634\u0647\u0627\u062f\u0629\u0650\u060c \u0631\u064e\u0628\u0651\u064e \u0643\u064f\u0644\u0651\u0650 \u0634\u064a\u0621\u064d \u0648\u0645\u064e\u0644\u064a\u0643\u0647\u060c \u0623\u0634\u0647\u064e\u062f\u064f \u0623\u0646 \u0644\u0627 \u0625\u0644\u0647\u064e \u0625\u0644\u0627 \u0623\u0646\u062a\u064e\u060c \u0623\u0639\u0648\u0630 \u0628\u0643 \u0645\u0650\u0646 \u0634\u0631 \u0646\u0641\u0633\u064a \u0648\u0645\u0650\u0646 \u0634\u0631 \u0627\u0644\u0634\u064a\u0637\u0627\u0646\u0650 \u0648\u0634\u0650\u0631\u0643\u0650\u0647.",1,B.aC7)
B.aIl=s(["\u0645\u0646 \u0642\u0627\u0644: \u0628\u0633\u0645\u0650 \u0627\u0644\u0644\u0647 \u0627\u0644\u0630\u064a \u0644\u0627 \u064a\u064e\u0636\u0631\u064f \u0645\u0639 \u0627\u0633\u0645\u0650\u0647\u0650 \u0634\u064a\u0621 \u0641\u064a \u0627\u0644\u0623\u0631\u0636 \u0648\u0644\u0627 \u0641\u064a \u0627\u0644\u0633\u0645\u0627\u0621 \u0648\u0647\u0648 \u0627\u0644\u0633\u0645\u064a\u0639\u064f \u0627\u0644\u0639\u0644\u064a\u0645\u0650 . \u062b\u0644\u0627\u062b \u0645\u0631\u0627\u062a \u060c \u0644\u0645 \u062a\u0635\u0628\u0647 \u0641\u062c\u0623\u0629 \u0628\u0644\u0627\u0621\u064d \u062d\u062a\u0649 \u064a\u064f\u0635\u0628\u062d\u064e \u060c \u0648\u0645\u0646 \u0642\u0627\u0644\u0647\u0627 \u062d\u064a\u0646 \u064a\u0635\u0628\u062d \u062b\u0644\u0627\u062b \u0645\u0631\u0627\u062a \u0644\u0645 \u062a\u0635\u0628\u0647 \u0641\u062c\u0623\u0629 \u0628\u0644\u0627\u0621\u064d \u062d\u062a\u0649 \u064a\u064f\u0645\u0633\u064a.","\u0627\u0644\u0631\u0627\u0648\u064a: \u0639\u062b\u0645\u0627\u0646 \u0628\u0646 \u0639\u0641\u0627\u0646 \u060c \u0627\u0644\u0645\u062d\u062f\u062b: \u0627\u0644\u0623\u0644\u0628\u0627\u0646\u064a \u060c \u0627\u0644\u0645\u0635\u062f\u0631: \u0635\u062d\u064a\u062d \u0623\u0628\u064a \u062f\u0627\u0648\u062f","\u0623\u0646 \u0630\u0643\u0631 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0644\u0647 \u0641\u0636\u0644 \u0639\u0638\u064a\u0645\u060c \u0648\u0647\u0648 \u064a\u0642\u0631\u0628 \u0627\u0644\u0639\u0628\u062f \u0645\u0646 \u0631\u0628\u0647\u060c \u0648\u064a\u062d\u0641\u0638\u0647 \u0645\u0646 \u0627\u0644\u0634\u064a\u0637\u0627\u0646 \u0648\u0627\u0644\u0628\u0644\u0627\u0621.","\u0648\u0641\u064a \u0647\u0630\u0627 \u0627\u0644\u062d\u062f\u064a\u062b \u064a\u062e\u0628\u0631 \u0627\u0644\u0631\u0633\u0648\u0644 \ufdfa \u0623\u0646: \u0645\u0646 \u0642\u0627\u0644: \u0628\u0633\u0645 \u0627\u0644\u0644\u0647\u060c \u0623\u064a: \u0623\u0644\u062a\u062c\u0626 \u0648\u0623\u0639\u062a\u0635\u0645 \u0628\u0627\u0644\u0644\u0647\u060c \u0627\u0644\u0630\u064a \u0644\u0627 \u064a\u0636\u0631 \u0645\u0639 \u0627\u0633\u0645\u0647\u060c \u0623\u064a: \u0645\u0639 \u0630\u0643\u0631 \u0627\u0633\u0645\u0647 \u0627\u0644\u0639\u0638\u064a\u0645\u060c \u0627\u0639\u062a\u0642\u0627\u062f\u0627 \u0648\u0625\u064a\u0645\u0627\u0646\u0627 \u0628\u0630\u0644\u0643\u060c \u0634\u064a\u0621 \u0641\u064a \u0627\u0644\u0623\u0631\u0636 \u0645\u0646 \u0627\u0644\u0645\u0643\u0631\u0648\u0647\u0627\u062a \u0648\u0627\u0644\u0645\u0624\u0630\u064a\u0627\u062a\u060c \u0648\u0644\u0627 \u0641\u064a \u0627\u0644\u0633\u0645\u0627\u0621 \u0645\u0646 \u0627\u0644\u0628\u0644\u0627\u064a\u0627 \u0627\u0644\u0646\u0627\u0632\u0644\u0627\u062a\u060c \u0648\u0647\u0648 \u0627\u0644\u0633\u0645\u064a\u0639 \u0627\u0644\u0639\u0644\u064a\u0645\u060c \u0633\u0645\u064a\u0639 \u0644\u0643\u0644 \u0634\u064a\u0621 \u0648\u0639\u0644\u064a\u0645 \u0628\u0643\u0644 \u0634\u064a\u0621\u060c \u062b\u0644\u0627\u062b \u0645\u0631\u0627\u062a.","\u0623\u064a: \u064a\u0642\u0648\u0644 \u0647\u0630\u0627 \u0627\u0644\u062f\u0639\u0627\u0621 \u062b\u0644\u0627\u062b \u0645\u0631\u0627\u062a \u0644\u0645 \u062a\u0635\u0628\u0647 \u0641\u062c\u0623\u0629 \u0628\u0644\u0627\u0621\u060c \u0623\u064a: \u0628\u0644\u0627\u0621 \u064a\u0623\u062a\u064a \u0628\u063a\u062a\u0629 \u0628\u0644\u0627 \u0633\u0628\u0628\u060c \u062d\u062a\u0649 \u064a\u0635\u0628\u062d \u0648\u0630\u0644\u0643 \u0625\u0630\u0627 \u0642\u0627\u0644\u0647\u0627 \u0628\u0627\u0644\u0644\u064a\u0644\u060c \u0648\u0645\u0646 \u0642\u0627\u0644\u0647\u0627 \u062d\u064a\u0646 \u064a\u0635\u0628\u062d\u060c \u0623\u064a: \u0641\u064a \u0627\u0644\u0635\u0628\u0627\u062d \u0628\u0639\u062f \u0637\u0644\u0648\u0639 \u0627\u0644\u0641\u062c\u0631\u060c \u062b\u0644\u0627\u062b \u0645\u0631\u0627\u062a \u0644\u0645 \u062a\u0635\u0628\u0647 \u0641\u062c\u0623\u0629 \u0628\u0644\u0627\u0621 \u062d\u062a\u0649 \u064a\u0645\u0633\u064a\u060c \u0623\u064a: \u0625\u0644\u0649 \u0627\u0644\u0645\u0633\u0627\u0621 \u0628\u0639\u062f \u063a\u0631\u0648\u0628 \u0627\u0644\u0634\u0645\u0633."],t.s)
B.baq=new A.dk("\u062f\u0639\u0627\u0621 \u0627\u0644\u062d\u0641\u0638 \u0645\u0646 \u0627\u0644\u0634\u064a\u0637\u0627\u0646 \u0648\u0627\u0644\u0628\u0644\u0627\u064a\u0627","\u0628\u0633\u0645\u0650 \u0627\u0644\u0644\u0647 \u0627\u0644\u0630\u064a \u0644\u0627 \u064a\u064e\u0636\u0631\u064f \u0645\u0639 \u0627\u0633\u0645\u0650\u0647\u0650 \u0634\u064a\u0621 \u0641\u064a \u0627\u0644\u0623\u0631\u0636 \u0648\u0644\u0627 \u0641\u064a \u0627\u0644\u0633\u0645\u0627\u0621 \u0648\u0647\u0648 \u0627\u0644\u0633\u0645\u064a\u0639\u064f \u0627\u0644\u0639\u0644\u064a\u0645\u0650",3,B.aIl)
B.aOi=s(["\u0645\u0646 \u0642\u0627\u0644 \u062d\u064a\u0646 \u064a\u0645\u0633\u064a \u062b\u0644\u0627\u062b \u0645\u0631\u0627\u062a : \u0623\u0639\u0648\u0630 \u0628\u0643\u0644\u0645\u0627\u062a \u0627\u0644\u0644\u0647 \u0627\u0644\u062a\u0627\u0645\u0627\u062a \u0645\u0646 \u0634\u0631 \u0645\u0627 \u062e\u0644\u0642 \u060c \u0644\u0645 \u064a\u0636\u0631\u0647 \u0644\u062f\u063a\u0629 \u062d\u064a\u0629 \u0641\u064a \u062a\u0644\u0643 \u0627\u0644\u0644\u064a\u0644\u0629.","\u0627\u0644\u0631\u0627\u0648\u064a: \u0623\u0628\u0648 \u0647\u0631\u064a\u0631\u0629 \u060c \u0627\u0644\u0645\u062d\u062f\u062b: \u0627\u0644\u0623\u0644\u0628\u0627\u0646\u064a \u060c \u0627\u0644\u0645\u0635\u062f\u0631: \u0635\u062d\u064a\u062d \u0627\u0644\u062c\u0627\u0645\u0639","\u0627\u0644\u0644\u0647 \u0648\u062d\u062f\u0647 \u0647\u0648 \u0627\u0644\u0630\u064a \u064a\u0639\u0635\u0645 \u0645\u0646 \u0643\u0644 \u0634\u0631\u060c \u0648\u0643\u0644 \u0645\u0646 \u0633\u0648\u0649 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0644\u0627 \u064a\u0645\u0644\u0643 \u0644\u0646\u0641\u0633\u0647 \u0648\u0644\u0627 \u0644\u063a\u064a\u0631\u0647 \u0646\u0641\u0639\u0627 \u0648\u0644\u0627 \u0636\u0631\u0627.","\u0648\u0641\u064a \u0647\u0630\u0627 \u0627\u0644\u062d\u062f\u064a\u062b \u064a\u0628\u064a\u0646 \u0627\u0644\u0646\u0628\u064a \ufdfa \u0645\u0627 \u064a\u0642\u0648\u0644\u0647 \u0627\u0644\u0645\u0633\u0644\u0645 \u0645\u0646 \u0627\u0644\u0630\u0643\u0631 \u0625\u0630\u0627 \u0643\u0627\u0646 \u0645\u0633\u0627\u0641\u0631\u0627 \u0648\u0646\u0632\u0644 \u0645\u0643\u0627\u0646\u0627 \u0644\u0644\u0631\u0627\u062d\u0629 \u0648\u0646\u062d\u0648\u0647\u0627\u060c \u0641\u064a\u062f\u0639\u0648 \u0627\u0644\u0644\u0647 \u0628\u0647\u0630\u0627 \u0627\u0644\u062f\u0639\u0627\u0621: \u0623\u0639\u0648\u0630 \u0628\u0643\u0644\u0645\u0627\u062a \u0627\u0644\u0644\u0647 \u0627\u0644\u062a\u0627\u0645\u0627\u062a\u060c \u0623\u064a: \u0623\u0639\u062a\u0635\u0645 \u0628\u0643\u0644\u0645\u0627\u062a \u0627\u0644\u0644\u0647 \u0627\u0644\u0643\u0627\u0645\u0644\u0629 \u0641\u064a \u0641\u0636\u0644\u0647\u0627 \u0648\u0628\u0631\u0643\u062a\u0647\u0627 \u0648\u0646\u0641\u0639\u0647\u0627 \u0627\u0644\u062a\u064a \u0644\u0627 \u064a\u062f\u062e\u0644\u0647\u0627 \u0646\u0642\u0635 \u0648\u0644\u0627 \u0639\u064a\u0628 \u0643\u0645\u0627 \u064a\u062f\u062e\u0644 \u0643\u0644\u0627\u0645 \u0627\u0644\u0628\u0634\u0631\u060c \u0641\u0647\u064a \u0627\u0644\u0646\u0627\u0641\u0639\u0627\u062a \u0627\u0644\u0634\u0627\u0641\u064a\u0627\u062a \u0628\u0625\u0630\u0646 \u0627\u0644\u0644\u0647.","\u0648\u0642\u062f \u0642\u064a\u0644: \u0643\u0644\u0645\u0627\u062a \u0627\u0644\u0644\u0647 \u0647\u064a \u0623\u0633\u0645\u0627\u0624\u0647 \u0648\u0635\u0641\u0627\u062a\u0647\u060c \u0648\u0642\u064a\u0644: \u0647\u064a \u0627\u0644\u0642\u0631\u0622\u0646. \u0648\u0642\u064a\u0644: \u0647\u064a \u062c\u0645\u064a\u0639 \u0645\u0627 \u0623\u0646\u0632\u0644\u0647 \u0639\u0644\u0649 \u0623\u0646\u0628\u064a\u0627\u0626\u0647\u060c \u0645\u0646 \u0634\u0631 \u0645\u0627 \u062e\u0644\u0642 \u0623\u064a: \u0645\u0646 \u0627\u0644\u062f\u0648\u0627\u0628 \u0648\u0627\u0644\u062d\u064a\u0648\u0627\u0646\u0627\u062a \u0627\u0644\u062a\u064a \u064a\u0642\u0639 \u0645\u0646\u0647\u0627 \u0627\u0644\u0623\u0630\u0649 \u0648\u0627\u0644\u0636\u0631\u0631\u060c \u0648\u0623\u062e\u0628\u0631 \ufdfa \u0623\u0646 \u0647\u0630\u0627 \u0627\u0644\u062f\u0639\u0627\u0621 \u064a\u062d\u0641\u0638 \u0635\u0627\u062d\u0628\u0647 \u062d\u062a\u0649 \u0625\u0646\u0647 \u0644\u0627 \u064a\u0636\u0631\u0647 \u0634\u064a\u0621 \u0645\u0646 \u0627\u0644\u0645\u062e\u0644\u0648\u0642\u0627\u062a \u062d\u062a\u0649 \u064a\u0631\u062a\u062d\u0644 \u0648\u064a\u0646\u062a\u0642\u0644 \u0645\u0646 \u0645\u0646\u0632\u0644\u0647 \u0630\u0644\u0643\u060c \u0641\u062a\u0639\u0648\u0630\u0647 \u064a\u062a\u0646\u0627\u0648\u0644 \u0645\u062f\u0629 \u0645\u0642\u0627\u0645\u0647 \u0641\u064a\u0647.","\u0648\u0641\u064a \u0627\u0644\u062d\u062f\u064a\u062b: \u0627\u0644\u062d\u062b \u0639\u0644\u0649 \u0627\u0644\u0623\u0630\u0643\u0627\u0631 \u0641\u064a \u0643\u0644 \u0648\u0642\u062a \u0648\u0645\u0643\u0627\u0646 \u0648\u0623\u0646\u0647\u0627 \u0645\u0646 \u0623\u0633\u0628\u0627\u0628 \u062d\u0641\u0638 \u0627\u0644\u0639\u0628\u062f \u0627\u0644\u0645\u0624\u0645\u0646\u060c \u0648\u0625\u0628\u0637\u0627\u0644 \u0648\u0631\u062f \u0644\u0645\u0627 \u0643\u0627\u0646 \u064a\u0641\u0639\u0644\u0647 \u0623\u0647\u0644 \u0627\u0644\u062c\u0627\u0647\u0644\u064a\u0629\u061b \u062d\u064a\u062b \u0643\u0627\u0646\u0648\u0627 \u0625\u0630\u0627 \u0646\u0632\u0644\u0648\u0627 \u0645\u0646\u0632\u0644\u0627 \u0642\u0627\u0644\u0648\u0627: \u0646\u0639\u0648\u0630 \u0628\u0633\u064a\u062f \u0647\u0630\u0627 \u0627\u0644\u0648\u0627\u062f\u064a\u060c \u064a\u0642\u0635\u062f\u0648\u0646 \u0628\u0647: \u0643\u0628\u064a\u0631 \u0627\u0644\u062c\u0646\u060c \u0648\u0641\u064a\u0647 \u0625\u064a\u0636\u0627 \u0628\u064a\u0627\u0646 \u0644\u062d\u0631\u0635 \u0627\u0644\u0646\u0628\u064a \ufdfa \u0639\u0644\u0649 \u062a\u0639\u0644\u064a\u0645 \u0623\u0645\u062a\u0647 \u0627\u0644\u0623\u0630\u0643\u0627\u0631 \u0627\u0644\u0645\u0646\u062c\u064a\u0629 \u0645\u0646 \u0643\u0644 \u0633\u0648\u0621."],t.s)
B.bai=new A.dk("\u0627\u0644\u062a\u0639\u0648\u0630 \u0645\u0646 \u0627\u0644\u0634\u0631\u0648\u0631 \u0627\u0644\u0638\u0627\u0647\u0631\u0629 \u0648\u0627\u0644\u0628\u0627\u0637\u0646\u0629","\u0623\u0639\u0648\u0630\u064f \u0628\u0643\u0644\u0645\u0627\u062a\u0650 \u0627\u0644\u0644\u0647\u0650 \u0627\u0644\u062a\u0627\u0645\u0627\u062a\u0650 \u0645\u0646 \u0634\u0631\u0651\u0650 \u0645\u0627 \u062e\u0644\u0642\u064e",3,B.aOi)
B.aJa=s(["\u0623\u0644\u0627 \u0623\u0639\u0644\u0645\u064f\u0643 \u0643\u0644\u0627\u0645\u064b\u0627 \u0625\u0630\u0627 \u0642\u0644\u062a\u064e\u0647 \u0623\u0630\u0647\u064e\u0628 \u0627\u0644\u0644\u0647\u064f \u062a\u0639\u0627\u0644\u0649 \u0647\u0645\u0651\u064e\u0643\u064e \u0648\u0642\u0636\u0649 \u0639\u0646\u0643\u064e \u062f\u064e\u064a\u0646\u0643\u061f \u0642\u064f\u0644 \u0625\u0630\u0627 \u0623\u0635\u0628\u064e\u062d\u062a \u0648\u0625\u0630\u0627 \u0623\u0645\u0633\u064e\u064a\u062a \u060c \u0627\u0644\u0644\u0647\u0645 \u0625\u0646\u064a \u0623\u0639\u0648\u0630\u064f \u0628\u0643\u064e \u0645\u0646\u064e \u0627\u0644\u0647\u0645\u0651\u0650 \u0648\u0627\u0644\u062d\u0632\u0646\u0650\u060c \u0648\u0623\u0639\u0648\u0630\u064f \u0628\u0643 \u0645\u0646 \u0627\u0644\u0639\u062c\u0632\u0650 \u0648\u0627\u0644\u0643\u0633\u0644\u0650\u060c \u0648\u0623\u0639\u0648\u0630\u064f \u0628\u0643\u064e \u0645\u0646\u064e \u0627\u0644\u062c\u064f\u0628\u0646\u0650 \u0648\u0627\u0644\u0628\u062e\u0644\u0650 \u060c \u0648\u0623\u0639\u0648\u0630\u064f \u0628\u0643 \u0645\u0650\u0646 \u063a\u0644\u0628\u0629\u0650 \u0627\u0644\u062f\u0651\u064e\u064a\u0646\u0650 \u0648\u0642\u0647\u0631\u0650 \u0627\u0644\u0631\u062c\u0627\u0644\u0650.","\u0627\u0644\u0631\u0627\u0648\u064a: \u0623\u0628\u0648 \u0633\u0639\u064a\u062f \u0627\u0644\u062e\u062f\u0631\u064a \u060c \u0627\u0644\u0645\u062d\u062f\u062b: \u0627\u0644\u0633\u064a\u0648\u0637\u064a \u060c \u0627\u0644\u0645\u0635\u062f\u0631: \u0627\u0644\u062c\u0627\u0645\u0639 \u0627\u0644\u0635\u063a\u064a\u0631 ","\u062c\u0645\u0639 \u0627\u0644\u0646\u0628\u064a \ufdfa \u0641\u064a \u0647\u0630\u0627 \u0627\u0644\u062f\u0639\u0627\u0621 \u0627\u0644\u062a\u0639\u0648\u0630 \u0645\u0646 \u0623\u0635\u0648\u0644 \u0627\u0644\u062e\u0635\u0627\u0644 \u0627\u0644\u0645\u062b\u0628\u0637\u0629 \u0639\u0646 \u0627\u0644\u0639\u0645\u0644\u060c \u0641\u0627\u0633\u062a\u0639\u0627\u0630 \ufdfa \u0645\u0646 \u0627\u0644\u0647\u0645\u060c \u0648\u0647\u0648 \u0623\u0644\u0645 \u0627\u0644\u0646\u0641\u0633 \u064a\u0646\u0634\u0623 \u0639\u0646 \u0627\u0644\u0641\u0643\u0631 \u0641\u064a\u0645\u0627 \u064a\u062a\u0648\u0642\u0639 \u062d\u0635\u0648\u0644\u0647 \u0645\u0645\u0627 \u064a\u062a\u0623\u0630\u0649 \u0628\u0647\u060c \u0648\u0627\u0644\u062d\u0632\u0646 \u0623\u0644\u0645 \u0628\u0627\u0644\u0646\u0641\u0633 \u0646\u062a\u064a\u062c\u0629 \u0634\u064a\u0621 \u0648\u0642\u0639\u060c \u0648\u0642\u064a\u0644: \u0647\u0645\u0627 \u0628\u0645\u0639\u0646\u0649 \u0648\u0627\u062d\u062f. \u0648\u0627\u0633\u062a\u0639\u0627\u0630 \ufdfa \u0645\u0646 \u0627\u0644\u0639\u062c\u0632 \u0648\u0627\u0644\u0643\u0633\u0644\u060c \u0648\u0627\u0644\u0641\u0631\u0642 \u0628\u064a\u0646\u0647\u0645\u0627: \u0623\u0646 \u0627\u0644\u0643\u0633\u0644 \u062a\u0631\u0643 \u0627\u0644\u0634\u064a\u0621 \u0645\u0639 \u0627\u0644\u0642\u062f\u0631\u0629 \u0639\u0644\u0649 \u0641\u0639\u0644\u0647\u060c \u0648\u0627\u0644\u0639\u062c\u0632 \u0639\u062f\u0645 \u0627\u0644\u0642\u062f\u0631\u0629.","\u0648\u0627\u0633\u062a\u0639\u0627\u0630 \ufdfa \u0645\u0646 \u0627\u0644\u062c\u0628\u0646 \u0648\u0627\u0644\u0628\u062e\u0644 \u0644\u0645\u0627 \u0641\u064a\u0647\u0645\u0627 \u0645\u0646 \u0627\u0644\u062a\u0642\u0635\u064a\u0631 \u0639\u0646 \u0623\u062f\u0627\u0621 \u0627\u0644\u0648\u0627\u062c\u0628\u0627\u062a\u060c \u0648\u0627\u0644\u0642\u064a\u0627\u0645 \u0628\u062d\u0642\u0648\u0642 \u0627\u0644\u0644\u0647 \u0633\u0628\u062d\u0627\u0646\u0647 \u0648\u062a\u0639\u0627\u0644\u0649\u060c \u0648\u0625\u0632\u0627\u0644\u0629 \u0627\u0644\u0645\u0646\u0643\u0631\u061b \u0648\u0644\u0623\u0646\u0647 \u0628\u0634\u062c\u0627\u0639\u0629 \u0627\u0644\u0646\u0641\u0633 \u0648\u0642\u0648\u062a\u0647\u0627 \u0627\u0644\u0645\u0639\u062a\u062f\u0644\u0629 \u062a\u062a\u0645 \u0627\u0644\u0639\u0628\u0627\u062f\u0627\u062a\u060c \u0648\u064a\u0642\u0648\u0645 \u0628\u0646\u0635\u0631 \u0627\u0644\u0645\u0638\u0644\u0648\u0645\u060c \u0648\u0628\u0627\u0644\u0633\u0644\u0627\u0645\u0629 \u0645\u0646 \u0627\u0644\u0628\u062e\u0644 \u064a\u0642\u0648\u0645 \u0628\u062d\u0642\u0648\u0642 \u0627\u0644\u0645\u0627\u0644\u060c \u0648\u064a\u0646\u0628\u0639\u062b \u0644\u0644\u0625\u0646\u0641\u0627\u0642 \u0648\u0627\u0644\u062c\u0648\u062f \u0648\u0644\u0645\u0643\u0627\u0631\u0645 \u0627\u0644\u0623\u062e\u0644\u0627\u0642\u060c \u0648\u064a\u0645\u062a\u0646\u0639 \u0645\u0646 \u0627\u0644\u0637\u0645\u0639 \u0641\u064a\u0645\u0627 \u0644\u064a\u0633 \u0644\u0647\u060c \u0648\u0627\u0633\u062a\u0639\u0627\u0630 \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645 \u0645\u0646 \u0636\u0644\u0639 \u0627\u0644\u062f\u064a\u0646\u060c \u0623\u064a: \u062b\u0642\u0644\u0647\u060c \u0648\u0630\u0644\u0643 \u062d\u064a\u0646 \u0644\u0627 \u064a\u062c\u062f \u0645\u0646 \u0639\u0644\u064a\u0647 \u0627\u0644\u062f\u064a\u0646 \u0648\u0641\u0627\u0621\u060c \u0648\u0644\u0627 \u0633\u064a\u0645\u0627 \u0645\u0639 \u0627\u0644\u0645\u0637\u0627\u0644\u0628\u0629\u060c \u0648\u0645\u0646 \u063a\u0644\u0628\u0629 \u0627\u0644\u0631\u062c\u0627\u0644\u060c \u0623\u064a: \u0642\u0647\u0631\u0647\u0645 \u0648\u0634\u062f\u0629 \u062a\u0633\u0644\u0637\u0647\u0645 \u0639\u0644\u064a\u0647\u060c \u0648\u0627\u0644\u0645\u0631\u0627\u062f \u0628\u0627\u0644\u0631\u062c\u0627\u0644 \u0627\u0644\u0638\u0644\u0645\u0629 \u0623\u0648 \u0627\u0644\u062f\u0627\u0626\u0646\u0648\u0646."],t.s)
B.bah=new A.dk("\u0627\u0644\u062a\u0639\u0648\u0630 \u0645\u0646 \u0627\u0644\u062e\u0635\u0627\u0644 \u0627\u0644\u0645\u062b\u0628\u0637\u0629 \u0639\u0646 \u0627\u0644\u0639\u0645\u0644","\u0627\u0644\u0644\u0647\u064f\u0640\u0645 \u0625\u0646\u064a \u0623\u0639\u064f\u0648\u0630 \u0628\u0643 \u0645\u0650\u0646 \u0627\u0644\u0647\u0645 \u0648\u0627\u0644\u062d\u064e\u0632\u0646\u0650\u060c \u0648\u0623\u0639\u064f\u0648\u0630 \u0628\u0643 \u0645\u0646 \u0627\u0644\u0639\u064e\u062c\u0632\u0650 \u0648\u0627\u0644\u0643\u0633\u064e\u0644\u0650\u060c \u0648\u0623\u0639\u064f\u0648\u0630 \u0628\u0643 \u0645\u0646 \u0627\u0644\u062c\u064f\u0628\u0646 \u0648\u0627\u0644\u0628\u064f\u062e\u0644\u060c \u0648\u0623\u0639\u064f\u0648\u0630 \u0628\u0643 \u0645\u0650\u0646 \u063a\u0644\u0628\u0629\u0650 \u0627\u0644\u062f\u064a\u0646\u0650 \u0648\u0642\u0647\u0631 \u0627\u0644\u0631\u062c\u0627\u0644\u0650",1,B.aJa)
B.aJI=s(["\u0627\u0644\u0634\u0631\u0643\u064f \u0641\u064a\u0643\u0645 \u0623\u062e\u0641\u0649 \u0645\u0646 \u062f\u0628\u064a\u0628\u0650 \u0627\u0644\u0646\u0645\u0644\u0650 \u060c \u0648 \u0633\u0623\u062f\u0644\u064f\u0643 \u0639\u0644\u0649 \u0634\u064a\u0621\u064d \u0625\u0630\u0627 \u0641\u0639\u0644\u062a\u0647 \u0623\u0630\u0647\u0628\u064e \u0639\u0646\u0643 \u0635\u064e\u063a\u0627\u0631\u064f \u0627\u0644\u0634\u0631\u0643\u0650 \u0648 \u0643\u0628\u0627\u0631\u064f\u0647 \u060c \u062a\u0642\u0648\u0644\u064f : \u0627\u0644\u0644\u0647\u0645\u0651\u064e \u0625\u0646\u064a \u0623\u0639\u0648\u0630\u064f \u0628\u0643 \u0623\u0646 \u0623\u0634\u0631\u0650\u0643 \u0628\u0643 \u0648 \u0623\u0646\u0627 \u0623\u0639\u0644\u0645 \u060c \u0648 \u0623\u0633\u062a\u063a\u0641\u0631\u064f\u0643 \u0644\u0645\u0627 \u0644\u0627 \u0623\u0639\u0644\u0645\u064f ","\u0627\u0644\u0631\u0627\u0648\u064a : \u0623\u0628\u0648 \u0628\u0643\u0631 \u0627\u0644\u0635\u062f\u064a\u0642 \u060c \u0627\u0644\u0645\u062d\u062f\u062b : \u0627\u0644\u0623\u0644\u0628\u0627\u0646\u064a \u060c \u0627\u0644\u0645\u0635\u062f\u0631 : \u0635\u062d\u064a\u062d \u0627\u0644\u062c\u0627\u0645\u0639","\u0648\u0641\u064a \u0627\u0644\u062d\u062f\u064a\u062b \u062a\u062d\u0630\u064a\u0631 \u0627\u0644\u0646\u0628\u064a \ufdfa \u0623\u0645\u062a\u0647 \u0645\u0646 \u0627\u0644\u0634\u0631\u0643\u060c \u0648\u0627\u0644\u0631\u064a\u0627\u0621 \u0641\u064a \u0627\u0644\u0623\u0639\u0645\u0627\u0644 \u0641\u0625\u0646\u0647 \u064a\u062d\u0628\u0637 \u0627\u0644\u0639\u0645\u0644.","\u0641\u0642\u062f \u0642\u0627\u0644 \u0627\u0644\u0646\u0628\u064a \ufdfa \u0642\u0627\u0644 \u0644\u0623\u0628\u064a \u0628\u0643\u0631: \u064a\u0627 \u0623\u0628\u0627 \u0628\u0643\u0631\u060c \u0644\u0644\u0634\u0631\u0643 \u0641\u064a\u0643\u0645 \u0623\u062e\u0641\u0649 \u0645\u0646 \u062f\u0628\u064a\u0628 \u0627\u0644\u0646\u0645\u0644\u060c \u0648\u0647\u0630\u0627 \u064a\u062f\u0644 \u0639\u0644\u0649 \u0623\u0646 \u0627\u0644\u0625\u0646\u0633\u0627\u0646 \u0642\u062f \u064a\u062e\u0631\u062c \u0645\u0646 \u0627\u0644\u0625\u064a\u0645\u0627\u0646 \u0625\u0644\u0649 \u0627\u0644\u0643\u0641\u0631 \u0623\u0648 \u0627\u0644\u0634\u0631\u0643 \u0648\u0647\u0648 \u0644\u0627 \u064a\u0634\u0639\u0631\u060c \u0648\u0627\u0644\u0630\u064a \u0646\u0641\u0633\u064a \u0628\u064a\u062f\u0647\u060c \u0648\u0647\u0630\u0627 \u0642\u0633\u0645 \u0645\u0646 \u0627\u0644\u0646\u0628\u064a \ufdfa \u0628\u0627\u0644\u0644\u0647 \u0627\u0644\u0630\u064a \u064a\u0645\u0644\u0643 \u0646\u0641\u0633\u0647 \u0648\u0642\u0628\u0636 \u0631\u0648\u062d\u0647\u060c \u0623\u0642\u0633\u0645 \u0628\u0647 \u0645\u0624\u0643\u062f\u0627 \u0644\u0644\u0623\u0645\u0631.","\u062b\u0645 \u0623\u0639\u0627\u062f\u0647 \u0641\u0642\u0627\u0644: \u0644\u0644\u0634\u0631\u0643 \u0623\u062e\u0641\u0649 \u0645\u0646 \u062f\u0628\u064a\u0628 \u0627\u0644\u0646\u0645\u0644\u060c \u0648\u0647\u0630\u0627 \u0645\u0646 \u0627\u0644\u062a\u062d\u0630\u064a\u0631\u061b \u0644\u064a\u062a\u062d\u0631\u0649 \u0627\u0644\u0633\u0627\u0645\u0639 \u0627\u0644\u0628\u0639\u062f \u0639\u0646 \u0647\u0630\u0627 \u0627\u0644\u0634\u0631\u0643 \u0627\u0644\u062e\u0641\u064a \u0627\u0644\u0630\u064a \u0647\u0648 \u0627\u0644\u0631\u064a\u0627\u0621 \u0641\u064a \u0627\u0644\u0639\u0645\u0644\u060c \u0627\u0644\u0630\u064a \u064a\u0646\u0627\u0641\u064a \u0627\u0644\u0625\u062e\u0644\u0627\u0635 \u0627\u0644\u0645\u0623\u0645\u0648\u0631 \u0628\u0647\u060c \u0648\u0647\u0630\u0627 \u0627\u0644\u0631\u064a\u0627\u0621 \u064a\u062d\u0628\u0637 \u0627\u0644\u0639\u0645\u0644\u060c \u0648\u0633\u0645\u064a \u0634\u0631\u0643\u0627 \u062e\u0641\u064a\u0627\u061b \u0644\u0623\u0646\u0647 \u064a\u0643\u0648\u0646 \u063a\u064a\u0631 \u0638\u0627\u0647\u0631\u060c \u0628\u0644 \u064a\u0643\u0648\u0646 \u0641\u064a \u062e\u0641\u0627\u064a\u0627 \u0627\u0644\u0646\u0641\u0633 \u0627\u0644\u0628\u0634\u0631\u064a\u0629\u060c \u0648\u0644\u0627 \u064a\u0639\u0644\u0645\u0647 \u0625\u0644\u0627 \u0627\u0644\u0644\u0647 \u0633\u0628\u062d\u0627\u0646\u0647 \u0648\u062a\u0639\u0627\u0644\u0649\u060c \u0648\u0644\u0627 \u064a\u0638\u0647\u0631\u0647 \u0627\u0644\u0639\u0628\u062f \u0644\u0644\u0646\u0627\u0633\u061b \u0628\u0644 \u064a\u0636\u0645\u0631\u0647 \u0641\u064a \u0642\u0644\u0628\u0647\u060c \u0648\u064a\u0641\u0631\u062d \u0628\u0646\u0638\u0631 \u0627\u0644\u0646\u0627\u0633 \u0625\u0644\u0649 \u0639\u0645\u0644\u0647 \u062f\u0648\u0646 \u0645\u0631\u0627\u0639\u0627\u0629 \u0644\u0646\u0638\u0631 \u0627\u0644\u0644\u0647\u060c \u0648\u062f\u0648\u0646 \u0642\u0635\u062f \u0648\u062c\u0647 \u0627\u0644\u0644\u0647 \u0628\u0627\u0644\u0623\u0639\u0645\u0627\u0644\u060c \u0648\u0634\u0648\u0627\u0626\u0628 \u0627\u0644\u0631\u064a\u0627\u0621 \u0627\u0644\u062e\u0641\u064a \u0643\u062b\u064a\u0631\u0629 \u0644\u0627 \u062a\u0646\u062d\u0635\u0631\u061b \u0641\u0645\u062a\u0649 \u0623\u062f\u0631\u0643 \u0627\u0644\u0625\u0646\u0633\u0627\u0646 \u0645\u0646 \u0646\u0641\u0633\u0647 \u062a\u0641\u0631\u0642\u0629 \u0628\u064a\u0646 \u0623\u0646 \u064a\u0637\u0644\u0639 \u0639\u0644\u0649 \u0639\u0628\u0627\u062f\u062a\u0647 \u0623\u0648 \u0644\u0627 \u064a\u0637\u0644\u0639 \u0639\u0644\u064a\u0647\u0627\u060c \u0641\u0641\u064a\u0647 \u0634\u0639\u0628\u0629 \u0645\u0646 \u0627\u0644\u0631\u064a\u0627\u0621.","\u0623\u0644\u0627 \u0623\u062f\u0644\u0643 \u0639\u0644\u0649 \u0634\u064a\u0621 \u0625\u0630\u0627 \u0641\u0639\u0644\u062a\u0647 \u0630\u0647\u0628 \u0639\u0646\u0643 \u0642\u0644\u064a\u0644\u0647 \u0648\u0643\u062b\u064a\u0631\u0647\u061f\u060c \u0628\u0645\u0639\u0646\u0649: \u0623\u0631\u0634\u062f\u0643 \u0625\u0644\u0649 \u0645\u0627 \u064a\u0633\u0627\u0639\u062f \u0648\u064a\u0646\u062c\u064a \u0645\u0646 \u0647\u0630\u0647 \u0627\u0644\u0634\u0631\u0643\u064a\u0627\u062a \u0627\u0644\u062a\u064a \u0642\u062f \u062a\u062f\u062e\u0644 \u0639\u0644\u0649 \u0627\u0644\u0625\u0646\u0633\u0627\u0646 \u0641\u062a\u0641\u0633\u062f \u0644\u0647 \u0639\u0645\u0644\u0647\u060c \u0642\u0644: \u0627\u0644\u0644\u0647\u0645 \u0625\u0646\u064a \u0623\u0639\u0648\u0630 \u0628\u0643\u061b \u0641\u0623\u062d\u062a\u0645\u064a \u0628\u0643\u060c \u0648\u0623\u0644\u062c\u0623 \u0625\u0644\u064a\u0643 \u0623\u0646 \u0623\u0634\u0631\u0643 \u0628\u0643 \u0648\u0623\u0646\u0627 \u0623\u0639\u0644\u0645\u060c \u0623\u0646 \u0641\u064a \u0639\u0645\u0644\u064a \u0631\u064a\u0627\u0621\u060c \u0623\u0648 \u0639\u062f\u0645 \u0625\u062e\u0644\u0627\u0635 \u0623\u0642\u0635\u062f\u0647 \u0641\u064a \u0630\u0644\u0643 \u0627\u0644\u0639\u0645\u0644\u060c \u0648\u0623\u0633\u062a\u063a\u0641\u0631\u0643 \u0644\u0645\u0627 \u0644\u0627 \u0623\u0639\u0644\u0645\u060c \u0648\u0627\u063a\u0641\u0631 \u0644\u064a \u0645\u0627 \u0644\u0627 \u0623\u0642\u0635\u062f\u0647 \u0645\u0645\u0627 \u064a\u0641\u0633\u062f \u0639\u0645\u0644\u064a \u0648\u0625\u062e\u0644\u0627\u0635\u0647 \u0644\u0643\u060c \u0641\u0628\u064a\u0646 \u0627\u0644\u0646\u0628\u064a \ufdfa \u0623\u0646 \u0627\u0644\u0646\u062c\u0627\u0629 \u062a\u0643\u0648\u0646 \u0628\u0625\u062e\u0644\u0627\u0635 \u0627\u0644\u062f\u0639\u0627\u0621 \u0644\u0647\u060c \u0628\u0623\u0646 \u064a\u0646\u062c\u064a\u0647 \u0645\u0646 \u0647\u0630\u0627 \u0627\u0644\u0631\u064a\u0627\u0621\u061b \u0644\u0623\u0646\u0647 \u0644\u0627 \u064a\u062f\u0641\u0639 \u0639\u0646 \u0627\u0644\u0625\u0646\u0633\u0627\u0646 \u0625\u0644\u0627 \u0631\u0628\u0647\u060c \u0627\u0644\u0630\u064a \u0648\u0644\u064a \u062e\u0644\u0642\u0647\u060c \u0641\u0625\u0630\u0627 \u062a\u0639\u0648\u0630 \u0628\u0647 \u0623\u0639\u0627\u0630\u0647\u061b \u0644\u0623\u0646\u0647 \u0644\u0627 \u064a\u062e\u064a\u0628 \u0645\u0646 \u0627\u0644\u062a\u062c\u0623 \u0625\u0644\u064a\u0647\u060c \u0648\u0642\u0635\u0631 \u0646\u0638\u0631 \u0642\u0644\u0628\u0647 \u0639\u0644\u064a\u0647.","\u0648\u0642\u064a\u0644: \u0625\u0646\u0645\u0627 \u0623\u0631\u0634\u062f \u0627\u0644\u0646\u0628\u064a \ufdfa \u0625\u0644\u0649 \u0647\u0630\u0627 \u0627\u0644\u062a\u0639\u0648\u0630\u061b \u0644\u0626\u0644\u0627 \u064a\u062a\u0633\u0627\u0647\u0644 \u0627\u0644\u0625\u0646\u0633\u0627\u0646 \u0641\u064a \u0627\u0644\u0631\u0643\u0648\u0646 \u0625\u0644\u0649 \u0627\u0644\u0623\u0633\u0628\u0627\u0628\u060c \u0648\u064a\u0631\u062a\u0628\u0643 \u0641\u064a\u0647\u0627\u060c \u0641\u0644\u0627 \u064a\u0632\u0627\u0644 \u064a\u0636\u064a\u0639 \u0627\u0644\u0623\u0645\u0631 \u0648\u064a\u0647\u0645\u0644\u0647 \u062d\u062a\u0649 \u062a\u062d\u0644 \u0645\u0646\u0647 \u0639\u0642\u062f\u0629 \u0627\u0644\u0625\u064a\u0645\u0627\u0646 \u0641\u064a\u0634\u0631\u0643 \u0648\u0647\u0648 \u0644\u0627 \u064a\u0634\u0639\u0631.","\u0648\u0644\u0643\u0646 \u0644\u064a\u0633 \u0643\u0644 \u0634\u0627\u0626\u0628\u0629 \u0645\u062d\u0628\u0637\u0629 \u0644\u0644\u0623\u062c\u0631\u060c \u0648\u0645\u0641\u0633\u062f\u0629 \u0644\u0644\u0639\u0645\u0644\u060c \u0648\u0644\u064a\u0633 \u0643\u0644 \u0633\u0631\u0648\u0631 \u0628\u0631\u0624\u064a\u0629 \u0627\u0644\u0646\u0627\u0633 \u0644\u0644\u0639\u0645\u0644 \u0645\u062d\u0628\u0637\u0627 \u0644\u0644\u0623\u062c\u0631\u061b \u0644\u0623\u0646 \u0627\u0644\u0633\u0631\u0648\u0631 \u064a\u0646\u0642\u0633\u0645 \u0625\u0644\u0649 \u0645\u062d\u0645\u0648\u062f\u060c \u0648\u0645\u0630\u0645\u0648\u0645\u061b \u0641\u0627\u0644\u0645\u062d\u0645\u0648\u062f \u0623\u0646 \u064a\u0643\u0648\u0646 \u0642\u0635\u062f \u0627\u0644\u0625\u0646\u0633\u0627\u0646 \u0641\u064a\u0647 \u0625\u062e\u0641\u0627\u0621 \u0627\u0644\u0637\u0627\u0639\u0629\u060c \u0645\u0639 \u0627\u0644\u0625\u062e\u0644\u0627\u0635 \u0644\u0644\u0647\u060c \u0648\u0644\u0643\u0646 \u0644\u0645\u0627 \u0627\u0637\u0644\u0639 \u0639\u0644\u064a\u0647 \u0627\u0644\u062e\u0644\u0642\u060c \u0639\u0644\u0645 \u0623\u0646 \u0627\u0644\u0644\u0647 \u0623\u0637\u0644\u0639\u0647\u0645\u060c \u0648\u0623\u0638\u0647\u0631 \u0627\u0644\u062c\u0645\u064a\u0644 \u0645\u0646 \u0623\u062d\u0648\u0627\u0644\u0647\u060c \u0641\u064a\u0633\u0631 \u0628\u062d\u0633\u0646 \u0635\u0646\u0639 \u0627\u0644\u0644\u0647\u060c \u0648\u0644\u0637\u0641\u0647 \u0628\u0647\u061b \u0641\u064a\u0643\u0648\u0646 \u0641\u0631\u062d\u0647 \u0628\u0630\u0644\u0643\u060c \u0644\u0627 \u0628\u062d\u0645\u062f \u0627\u0644\u0646\u0627\u0633\u060c \u0648\u0642\u064a\u0627\u0645 \u0627\u0644\u0645\u0646\u0632\u0644\u0629 \u0641\u064a \u0642\u0644\u0648\u0628\u0647\u0645\u060c \u0648\u0623\u0645\u0627 \u0625\u0646 \u0643\u0627\u0646 \u0641\u0631\u062d\u0647 \u0628\u0627\u0637\u0644\u0627\u0639 \u0627\u0644\u0646\u0627\u0633 \u0639\u0644\u064a\u0647 \u0644\u0642\u064a\u0627\u0645 \u0645\u0646\u0632\u0644\u062a\u0647 \u0639\u0646\u062f\u0647\u0645 \u062d\u062a\u0649 \u064a\u0645\u062f\u062d\u0648\u0647\u060c \u0648\u064a\u0639\u0638\u0645\u0648\u0647\u060c \u0641\u0647\u0630\u0627 \u0645\u0630\u0645\u0648\u0645.","\u0648\u0641\u064a \u0635\u062d\u064a\u062d \u0645\u0633\u0644\u0645 \u0639\u0646 \u0623\u0628\u064a \u0630\u0631 \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647: \u0642\u064a\u0644: \u064a\u0627 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647\u060c \u0623\u0631\u0623\u064a\u062a \u0627\u0644\u0631\u062c\u0644 \u064a\u0639\u0645\u0644 \u0627\u0644\u0639\u0645\u0644 \u0645\u0646 \u0627\u0644\u062e\u064a\u0631 \u0648\u064a\u062d\u0645\u062f\u0647 \u0627\u0644\u0646\u0627\u0633 \u0639\u0644\u064a\u0647\u061f \u0641\u0642\u0627\u0644: \u062a\u0644\u0643 \u0639\u0627\u062c\u0644 \u0628\u0634\u0631\u0649 \u0627\u0644\u0645\u0624\u0645\u0646\u060c \u0641\u0623\u0645\u0627 \u0625\u0630\u0627 \u0623\u0639\u062c\u0628\u0647 \u0644\u064a\u0639\u0644\u0645 \u0627\u0644\u0646\u0627\u0633 \u0641\u064a\u0647 \u0627\u0644\u062e\u064a\u0631 \u0648\u064a\u0643\u0631\u0645\u0648\u0647 \u0639\u0644\u064a\u0647\u061b \u0641\u0647\u0630\u0627 \u0647\u0648 \u0627\u0644\u0631\u064a\u0627\u0621 \u0627\u0644\u0645\u0646\u0647\u064a \u0639\u0646\u0647."],t.s)
B.bac=new A.dk("\u0627\u0644\u062a\u0639\u0648\u0630 \u0645\u0646 \u0627\u0644\u0634\u0631\u0643\u060c \u0648\u0627\u0644\u0631\u064a\u0627\u0621 \u0641\u064a \u0627\u0644\u0623\u0639\u0645\u0627\u0644","\u0627\u0644\u0644\u0647\u0645\u0651\u064e \u0625\u0646\u064a \u0623\u0639\u0648\u0630\u064f \u0628\u0643 \u0623\u0646 \u0623\u0634\u0631\u0650\u0643 \u0628\u0643 \u0648 \u0623\u0646\u0627 \u0623\u0639\u0644\u0645 \u060c \u0648 \u0623\u0633\u062a\u063a\u0641\u0631\u064f\u0643 \u0644\u0645\u0627 \u0644\u0627 \u0623\u0639\u0644\u0645\u064f",1,B.aJI)
B.aTg=s(["\u0625\u0650\u0646 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0645\u064e\u0644\u0627\u0626\u0650\u0643\u062a\u0647\u064f \u064a\u064f\u0635\u064e\u0644\u0648\u0646 \u0639\u064e\u0644\u0649 \u0627\u0644\u0646\u0628\u064a\u0651\u0650 \u064a\u064e\u0627 \u0623\u064a\u0647\u064e\u0627 \u0627\u0644\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0635\u064e\u0644\u0648\u0627 \u0639\u064e\u0644\u064a\u0647\u0650 \u0648\u064e\u0633\u064e\u0644\u0645\u0648\u0627 \u062a\u064e\u0633\u0644\u0650\u064a\u0645\u064b\u0627 - \u0633\u0648\u0631\u0629 \u0627\u0644\u0623\u062d\u0632\u0627\u0628","\u0623\u0646 \u0627\u0644\u0644\u0647 \u0633\u064f\u0628\u062d\u0627\u0646\u0647 \u0623\u062e\u0628\u0631\u064e \u0639\u0628\u0627\u062f\u0647\u064f \u0628\u0645\u064e\u0646\u0632\u0650\u0644\u0629\u0650 \u0639\u0628\u062f\u0647\u0650 \u0648\u0646\u0628\u064a\u0647\u0650 \u0639\u0650\u0646\u062f\u0647\u064f \u0641\u0650\u064a \u0627\u0644\u0645\u064e\u0644\u0623\u0650 \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u0628\u0623\u0646\u0647\u064f \u064a\u064f\u062b\u0646\u0650\u064a \u0639\u064e\u0644\u064a\u0647\u0650 \u0639\u0650\u0646\u062f\u064e \u0627\u0644\u0645\u0644\u0627\u0626\u0643\u0629\u0650 \u0627\u0644\u0645\u064f\u0642\u0631\u0628\u064a\u0646\u060c \u0648\u0623\u0646 \u0627\u0644\u0645\u0644\u0627\u0626\u0643\u0629 \u062a\u064f\u0635\u0644\u064a \u0639\u064e\u0644\u064a\u0647\u0650. \u062b\u0645 \u0623\u0645\u0631\u064e \u062a\u0639\u0627\u0644\u0649 \u0623\u064e\u0647\u0644\u064e \u0627\u0644\u0639\u0627\u0644\u064e\u0645\u0650 \u0627\u0644\u0633\u0641\u0644\u0650\u064a \u0628\u0627\u0644\u0635\u0644\u0627\u0629\u0650 \u0648\u064e\u0627\u0644\u062a\u0633\u0644\u064a\u0645\u0650 \u0639\u064e\u0644\u064a\u0647\u0650\u060c \u0644\u0650\u064a\u062c\u062a\u0645\u0650\u0639 \u0627\u0644\u062b\u0646\u0627\u0621\u064e \u0639\u064e\u0644\u064a\u0647\u0650 \u0645\u0650\u0646 \u0623\u0647\u0644\u0650 \u0627\u0644\u0639\u064e\u0627\u0644\u0645\u0650\u064a\u0646\u064e \u0627\u0644\u0639\u064f\u0644\u0648\u0650\u064a \u0648\u064e\u0627\u0644\u0633\u0641\u0644\u064a \u062c\u064e\u0645\u0650\u064a\u0639\u064b\u0627 - \u062a\u0641\u0633\u064a\u0631 \u0627\u0628\u0646 \u0643\u062b\u064a\u0631","\u0648\u0639\u0646 \u0623\u0628\u064a \u0628\u0646 \u0643\u0639\u0628 \u0631\u0636\u0649 \u0627\u0644\u0644\u0647 \u0639\u0646\u0647: \u0642\u0644\u062a \u064a\u0627 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \u060c \u0625\u0646\u064a \u0623\u0643\u062b\u0631 \u0627\u0644\u0635\u0644\u0627\u0629 \u0639\u0644\u064a\u0643\u060c \u0641\u0643\u0645 \u0623\u062c\u0639\u0644 \u0644\u0643 \u0645\u0646 \u0635\u0644\u0627\u062a\u064a\u061f \u0641\u0642\u0627\u0644: \u0645\u0627 \u0634\u0626\u062a\u060c \u0642\u0644\u062a: \u0627\u0644\u0631\u0628\u0639\u061f \u0642\u0627\u0644: \u0645\u0627 \u0634\u0626\u062a\u064e\u060c \u0641\u0625\u0646 \u0632\u062f\u062a \u0641\u0647\u0648 \u062e\u064a\u0631 \u0644\u0643\u060c \u0642\u0644\u062a: \u0627\u0644\u0646\u0635\u0641\u061f \u0642\u0627\u0644: \u0645\u0627 \u0634\u0626\u062a\u064e\u060c \u0641\u0625\u0646 \u0632\u062f\u062a \u0641\u0647\u0648 \u062e\u064a\u0631 \u0644\u0643\u060c \u0642\u0644\u062a: \u0641\u0627\u0644\u062b\u0644\u062b\u064a\u0646\u061f \u0642\u0627\u0644: \u0645\u0627 \u0634\u0626\u062a\u064e\u060c \u0641\u0625\u0646 \u0632\u062f\u062a \u0641\u0647\u0648 \u062e\u064a\u0631 \u0644\u0643\u060c \u0642\u0644\u062a : \u0623\u062c\u0639\u0644 \u0644\u0643 \u0635\u0644\u0627\u062a\u064a \u0643\u0644\u0647\u0627\u061f \u0642\u0627\u0644: \u0625\u0630\u0627 \u062a\u064f\u0643\u0641\u064e\u0649 \u0647\u0645\u0651\u064e\u0643\u060c \u0648\u064a\u064f\u0643\u064e\u0641\u0651\u064e\u0631\u064f \u0644\u0643 \u0630\u0646\u0628\u064e\u0643.","\u0648\u0645\u0639\u0646\u0649 \u0623\u062c\u0639\u0644 \u0644\u0643 \u0635\u0644\u0627\u062a\u064a \u0643\u0644\u0647\u0627\u060c \u0623\u0649 \u0643\u0644\u0645\u0627 \u062f\u0639\u0648\u062a \u0644\u0646\u0641\u0633\u064a \u0635\u0644\u064a\u062a \u0639\u0644\u064a\u0643.","\u0648\u0639\u0646 \u0639\u0645\u0631\u064e \u0628\u0646\u0650 \u0627\u0644\u062e\u0637\u0627\u0628\u0650 \u0642\u0627\u0644: \u0625\u0646 \u0627\u0644\u062f\u0639\u0627\u0621\u064e \u0645\u0648\u0642\u0648\u0641\u064c \u0628\u064a\u0646\u064e \u0627\u0644\u0633\u0645\u0627\u0621\u0650 \u0648\u0627\u0644\u0623\u0631\u0636\u0650\u060c \u0644\u0627 \u064a\u064e\u0635\u0652\u0639\u064e\u062f\u064f \u0645\u0646\u0647 \u0634\u064a\u0621\u064c \u062d\u062a\u0649 \u062a\u064f\u0635\u064e\u0644\u0651\u0650\u064a\u064e \u0639\u0644\u0649 \u0646\u0628\u064a\u0651\u0650\u0643 \ufdfa -  \u0635\u062d\u064a\u062d \u0627\u0644\u062a\u0631\u0645\u0630\u064a","\u0648\u0642\u0627\u0644 \u0623\u0628\u0648 \u0633\u0644\u064a\u0645\u0627\u0646 \u0627\u0644\u062f\u0627\u0631\u064e\u0627\u0646\u0650\u064a: \u0645\u064e\u0646 \u0623\u0631\u0627\u062f \u0623\u0646 \u064a\u064e\u0633\u0623\u0644 \u0627\u0644\u0644\u0647 \u062d\u0627\u062c\u0629\u064b \u0641\u0644\u064a\u0628\u062f\u0623 \u0628\u0627\u0644\u0635\u0644\u0627\u0629\u0650 \u0639\u0644\u0649 \u0627\u0644\u0646\u0628\u064a \ufdfa \u060c \u062b\u0645 \u064a\u064e\u0633\u0623\u0644 \u0627\u0644\u0644\u0647 \u062d\u064e\u0627\u062c\u062a\u0647\u064f\u060c \u062b\u0645 \u064a\u064e\u062e\u062a\u0650\u0645\u064f \u0628\u0627\u0644\u0635\u0644\u0627\u0629\u0650 \u0639\u0644\u0649 \u0627\u0644\u0646\u0628\u064a \ufdfa \u0641\u0625\u0646 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u064a\u064e\u0642\u0628\u0644\u064f \u0627\u0644\u0635\u0644\u0627\u062a\u064a\u0646\u0650 \u0648\u064e\u0647\u0648 \u0623\u0643\u0631\u064e\u0645 \u0645\u0650\u0646 \u0623\u064e\u0646 \u064a\u0631\u064f\u062f \u0645\u064e\u0627 \u0628\u064a\u0646\u0647\u0645\u064e\u0627.","\u0634\u0631\u062d \u0645\u0639\u0646\u0649 \u0627\u0644\u0635\u0644\u0627\u0629 \u0627\u0644\u0623\u0628\u0631\u0627\u0647\u064a\u0645\u064a\u0629:","\u0643\u0627\u0646 \u0627\u0644\u0635\u062d\u0627\u0628\u0629 \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647\u0645 \u064a\u062d\u0628\u0648\u0646 \u0623\u0646 \u064a\u0633\u0623\u0644\u0648\u0627 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0639\u0645\u0627 \u064a\u0628\u064a\u0646 \u0645\u0643\u0627\u0646\u062a\u0647 \u062a\u0644\u0643\u061b \u0644\u064a\u062a\u0639\u0644\u0645\u0648\u0627 \u0643\u064a\u0641 \u064a\u0635\u0644\u0648\u0646 \u0639\u0644\u064a\u0647.","\u0648\u0641\u0649 \u0627\u0644\u062d\u062f\u064a\u062b: \u0644\u0642\u064a\u0646\u064a \u0643\u0639\u0628 \u0628\u0646 \u0639\u062c\u0631\u0629\u060c \u0641\u0642\u0627\u0644: \u0623\u0644\u0627 \u0623\u0647\u062f\u064a \u0644\u0643 \u0647\u062f\u064a\u0629 \u0633\u0645\u0639\u062a\u0647\u0627 \u0645\u0646 \u0627\u0644\u0646\u0628\u064a \ufdfa\u061f \u0641\u0642\u0644\u062a: \u0628\u0644\u0649\u060c \u0641\u0623\u0647\u062f\u0647\u0627 \u0644\u064a\u060c \u0641\u0642\u0627\u0644: \u0633\u0623\u0644\u0646\u0627 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0641\u0642\u0644\u0646\u0627: \u064a\u0627 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647\u060c \u0643\u064a\u0641 \u0627\u0644\u0635\u0644\u0627\u0629 \u0639\u0644\u064a\u0643\u0645 \u0623\u0647\u0644 \u0627\u0644\u0628\u064a\u062a\u061b \u0641\u0625\u0646 \u0627\u0644\u0644\u0647 \u0642\u062f \u0639\u0644\u0645\u0646\u0627 \u0643\u064a\u0641 \u0646\u0633\u0644\u0645 \u0639\u0644\u064a\u0643\u0645\u061f \u0642\u0627\u0644: \u0642\u0648\u0644\u0648\u0627: \u0627\u0644\u0644\u0647\u064f\u0645 \u0635\u064e\u0644\u0651\u0650 \u0639\u0644\u0649 \u0645\u064f\u062d\u0645\u062f\u064d \u0648\u0639\u0644\u064e\u0649 \u0622\u0644\u0650 \u0645\u064f\u062d\u0645\u062f\u064d\u060c \u0643\u0645\u0627 \u0635\u064e\u0644\u064a\u062a\u064e \u0639\u0644\u064e\u0649 \u0625\u0628\u0631\u0627\u0647\u0650\u064a\u0645 \u0648\u0639\u0644\u064e\u0649 \u0622\u0644\u0650 \u0625\u0628\u0631\u0627\u0647\u0650\u064a\u0645 \u0625\u0646\u0651\u064e\u0643\u064e \u062d\u064e\u0645\u0650\u064a\u062f\u064c \u0645\u064e\u062c\u064a\u062f\u064c\u060c \u0627\u0644\u0644\u0647\u064f\u0645 \u0628\u064e\u0627\u0631\u0650\u0643 \u0639\u0644\u0649 \u0645\u064f\u062d\u0645\u062f\u064d \u0648\u0639\u0644\u064e\u0649 \u0622\u0644\u0650 \u0645\u064f\u062d\u0645\u062f\u064d \u060c \u0643\u0645\u0627 \u0628\u064e\u0627\u0631\u0643\u062a\u064e \u0639\u0644\u064e\u0649 \u0625\u0628\u0631\u0627\u0647\u0650\u064a\u0645 \u0648\u0639\u0644\u064e\u0649 \u0622\u0644\u0650 \u0625\u0628\u0631\u0627\u0647\u0650\u064a\u0645  \u0625\u0646\u0651\u064e\u0643\u064e \u062d\u064e\u0645\u0650\u064a\u062f\u064c \u0645\u064e\u062c\u064a\u062f\u064c.","\u0627\u0644\u0631\u0627\u0648\u064a: \u0643\u0639\u0628 \u0628\u0646 \u0639\u062c\u0631\u0629 \u060c \u0627\u0644\u0645\u062d\u062f\u062b :\u0627\u0644\u0628\u062e\u0627\u0631\u064a \u060c \u0627\u0644\u0645\u0635\u062f\u0631: \u0635\u062d\u064a\u062d \u0627\u0644\u0628\u062e\u0627\u0631\u064a","\u0648\u0641\u064a \u0647\u0630\u0627 \u0627\u0644\u062d\u062f\u064a\u062b \u064a\u062d\u0643\u064a \u0627\u0644\u062a\u0627\u0628\u0639\u064a \u0639\u0628\u062f \u0627\u0644\u0631\u062d\u0645\u0646 \u0628\u0646 \u0623\u0628\u064a \u0644\u064a\u0644\u0649 \u0623\u0646 \u0643\u0639\u0628 \u0628\u0646 \u0639\u062c\u0631\u0629 \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647 \u0644\u0642\u064a\u0647\u060c \u0641\u0642\u0627\u0644 \u0644\u0647: \u0623\u0644\u0627 \u0623\u0647\u062f\u064a\u0643 \u0647\u062f\u064a\u0629 \u0633\u0645\u0639\u062a\u0647\u0627 \u0645\u0646 \u0627\u0644\u0646\u0628\u064a \ufdfa\u061f \u0648\u0647\u0630\u0627 \u0645\u0646 \u0627\u0644\u062a\u0648\u062f\u062f \u0625\u0644\u064a\u0647 \u0645\u0639 \u0625\u0643\u0631\u0627\u0645\u0647 \u0648\u062a\u0634\u0648\u064a\u0642\u0647 \u0644\u0645\u0627 \u0633\u064a\u0642\u0648\u0644\u0647\u060c \u0645\u0639 \u0645\u0627 \u0641\u064a \u0630\u0644\u0643 \u0645\u0646 \u062f\u0644\u0627\u0644\u0629 \u0639\u0644\u0649 \u0634\u062f\u0629 \u062d\u0628\u0647\u0645 \u0644\u0644\u0646\u0628\u064a \ufdfa \u060c \u0648\u0627\u0639\u062a\u0628\u0627\u0631 \u0645\u0627 \u0633\u064a\u0631\u0648\u064a\u0647 \u0647\u062f\u064a\u0629 \u0644\u0643\u0644 \u0645\u0633\u0644\u0645\u061b \u0644\u0645\u0627 \u0641\u064a\u0647 \u0645\u0646 \u0627\u0644\u062e\u064a\u0631 \u0648\u0627\u0644\u0623\u062c\u0631 \u0644\u0645\u0646 \u0623\u062f\u0627\u0647.","\u0641\u0642\u0627\u0644 \u0644\u0647 \u0639\u0628\u062f \u0627\u0644\u0631\u062d\u0645\u0646: \u0628\u0644\u0649\u060c \u0623\u0639\u0637\u0646\u064a \u0647\u0630\u0647 \u0627\u0644\u0647\u062f\u064a\u0629\u060c \u0641\u0642\u0627\u0644 \u0643\u0639\u0628 \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647: \u0633\u0623\u0644\u0646\u0627 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa: \u0643\u064a\u0641 \u0646\u0635\u0644\u064a \u0639\u0644\u064a\u0643\u0645 \u064a\u0627 \u0623\u0647\u0644 \u0628\u064a\u062a \u0627\u0644\u0646\u0628\u0648\u0629 \u0641\u064a \u0627\u0644\u062a\u0634\u0647\u062f \u0641\u064a \u0627\u0644\u0635\u0644\u0627\u0629\u061b \u0641\u0625\u0646 \u0627\u0644\u0644\u0647 \u0633\u0628\u062d\u0627\u0646\u0647 \u0642\u062f \u0639\u0644\u0645\u0646\u0627 \u0643\u064a\u0641 \u0646\u0633\u0644\u0645 \u0639\u0644\u064a\u0643\u0645\u061f \u0623\u064a: \u0625\u0646 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0623\u0645\u0631\u0646\u0627 \u0628\u0627\u0644\u0635\u0644\u0627\u0629 \u0648\u0627\u0644\u0633\u0644\u0627\u0645 \u0639\u0644\u064a\u0643 \u0641\u064a \u0642\u0648\u0644\u0647: \u0625\u0646 \u0627\u0644\u0644\u0647 \u0648\u0645\u0644\u0627\u0626\u0643\u062a\u0647 \u064a\u0635\u0644\u0648\u0646 \u0639\u0644\u0649 \u0627\u0644\u0646\u0628\u064a \u064a\u0627 \u0623\u064a\u0647\u0627 \u0627\u0644\u0630\u064a\u0646 \u0622\u0645\u0646\u0648\u0627 \u0635\u0644\u0648\u0627 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645\u0648\u0627 \u062a\u0633\u0644\u064a\u0645\u0627 \u2013 \u0627\u0644\u0623\u062d\u0632\u0627\u0628 \u060c \u0648\u0642\u062f \u0639\u0631\u0641\u0646\u0627 \u0643\u064a\u0641\u064a\u0629 \u0627\u0644\u0633\u0644\u0627\u0645 \u0639\u0644\u064a\u0643 \u0628\u0645\u0627 \u0639\u0644\u0645\u062a\u0646\u0627 \u0641\u064a \u0627\u0644\u062a\u062d\u064a\u0627\u062a \u0623\u0646 \u0646\u0642\u0648\u0644: \u0627\u0644\u0633\u0644\u0627\u0645 \u0639\u0644\u064a\u0643 \u0623\u064a\u0647\u0627 \u0627\u0644\u0646\u0628\u064a \u0648\u0631\u062d\u0645\u0629 \u0627\u0644\u0644\u0647 \u0648\u0628\u0631\u0643\u0627\u062a\u0647\u060c \u0641\u0639\u0644\u0645\u0646\u0627 \u0627\u0644\u0644\u0641\u0638 \u0627\u0644\u0630\u064a \u0628\u0647 \u0646\u0635\u0644\u064a \u0628\u0647 \u0639\u0644\u064a\u0643 \u0643\u0645\u0627 \u0639\u0644\u0645\u062a\u0646\u0627 \u0627\u0644\u0633\u0644\u0627\u0645\u060c \u0641\u0627\u0644\u0645\u0631\u0627\u062f \u0628\u0639\u062f\u0645 \u0639\u0644\u0645\u0647\u0645 \u0627\u0644\u0635\u0644\u0627\u0629 \u0639\u062f\u0645 \u0645\u0639\u0631\u0641\u0629 \u062a\u0623\u062f\u064a\u062a\u0647\u0627 \u0628\u0644\u0641\u0638 \u0644\u0627\u0626\u0642 \u0628\u0647 \ufdfa \u061b \u0648\u0644\u0630\u0627 \u0648\u0642\u0639 \u0628\u0644\u0641\u0638 \u0643\u064a\u0641 \u0623\u0649 \u0627\u0644\u062a\u064a \u064a\u0633\u0623\u0644 \u0628\u0647\u0627 \u0639\u0646 \u0627\u0644\u0635\u0641\u0629.","\u0641\u0642\u0627\u0644 \u0627\u0644\u0646\u0628\u064a \ufdfa: \u0642\u0648\u0644\u0648\u0627: \u0627\u0644\u0644\u0647\u0645 \u0635\u064e\u0644\u0651\u0650 \u0639\u0644\u0649 \u0645\u062d\u0645\u062f\u060c \u0623\u064a: \u0639\u0638\u0645\u0647 \u0641\u064a \u0627\u0644\u062f\u0646\u064a\u0627 \u0628\u0625\u0639\u0644\u0627\u0621 \u0630\u0643\u0631\u0647\u060c \u0648\u0625\u0638\u0647\u0627\u0631 \u062f\u064a\u0646\u0647 \u0648\u0625\u0628\u0642\u0627\u0621 \u0634\u0631\u064a\u0639\u062a\u0647\u060c \u0648\u0641\u064a \u0627\u0644\u0622\u062e\u0631\u0629 \u0628\u0625\u062c\u0632\u0627\u0644 \u0645\u062b\u0648\u0628\u062a\u0647 \u0648\u062a\u0634\u0641\u064a\u0639\u0647 \u0641\u064a \u0623\u0645\u062a\u0647\u060c \u0648\u0625\u0628\u062f\u0627\u0621 \u0641\u0636\u064a\u0644\u062a\u0647 \u0628\u0627\u0644\u0645\u0642\u0627\u0645 \u0627\u0644\u0645\u062d\u0645\u0648\u062f\u060c \u0648\u0644\u0645\u0627 \u0643\u0627\u0646 \u0627\u0644\u0628\u0634\u0631 \u0639\u0627\u062c\u0632\u064a\u0646 \u0639\u0646 \u0623\u0646 \u064a\u0628\u0644\u063a\u0648\u0627 \u0627\u0644\u0642\u062f\u0631 \u0627\u0644\u0648\u0627\u062c\u0628 \u0644\u0647 \u0645\u0646 \u0630\u0644\u0643\u060c \u0634\u0631\u0639 \u0644\u0646\u0627 \u0623\u0646 \u0646\u062d\u064a\u0644 \u0623\u0645\u0631 \u0630\u0644\u0643 \u0625\u0644\u0649 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0628\u0623\u0646 \u0646\u0642\u0648\u0644: \u0627\u0644\u0644\u0647\u0645 \u0635\u064e\u0644\u0651\u0650 \u0639\u0644\u0649 \u0645\u062d\u0645\u062f\u060c \u0623\u064a: \u0644\u0623\u0646\u0643 \u0623\u0646\u062a \u0627\u0644\u0639\u0644\u064a\u0645 \u0628\u0645\u0627 \u064a\u0644\u064a\u0642 \u0628\u0647 \u0645\u0646 \u0630\u0644\u0643. \u0648\u0639\u0644\u0649 \u0622\u0644 \u0645\u062d\u0645\u062f \u0648\u0627\u0644\u0645\u0631\u0627\u062f: \u0627\u0644\u0623\u0632\u0648\u0627\u062c \u0648\u0645\u0646 \u062d\u064e\u0631\u064f\u0645\u064e\u062a \u0639\u0644\u064a\u0647\u0645 \u0627\u0644\u0635\u062f\u0642\u0629\u060c \u0648\u062a\u062f\u062e\u0644 \u0641\u064a\u0647\u0645 \u0627\u0644\u0630\u0631\u064a\u0629\u060c \u0648\u0642\u064a\u0644: \u064a\u0634\u0645\u0644 \u0623\u062a\u0628\u0627\u0639\u0647 \u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646.","\u0643\u0645\u0627 \u0635\u0644\u064a\u062a \u0639\u0644\u0649 \u0625\u0628\u0631\u0627\u0647\u064a\u0645 \u0648\u0639\u0644\u0649 \u0622\u0644 \u0625\u0628\u0631\u0627\u0647\u064a\u0645\u060c \u0623\u064a: \u0645\u062b\u0644 \u0635\u0644\u0627\u062a\u0643 \u0639\u0644\u0649 \u0625\u0628\u0631\u0627\u0647\u064a\u0645 \u0639\u0644\u064a\u0647 \u0627\u0644\u0633\u0644\u0627\u0645 \u0648\u0622\u0644\u0647\u060c \u0648\u0647\u0645 \u0625\u0633\u0645\u0627\u0639\u064a\u0644 \u0648\u0625\u0633\u062d\u0627\u0642 \u0648\u0630\u0631\u064a\u062a\u0647\u0645\u0627 \u0627\u0644\u0645\u0624\u0645\u0646\u0629\u061b \u0625\u0646\u0643 \u062d\u0645\u064a\u062f\u060c \u0645\u062d\u0645\u0648\u062f \u0641\u064a \u0630\u0627\u062a\u0647 \u0648\u0635\u0641\u0627\u062a\u0647 \u0648\u0623\u0641\u0639\u0627\u0644\u0647 \u0628\u0623\u0644\u0633\u0646\u0629 \u062e\u0644\u0642\u0647\u060c \u0645\u062c\u064a\u062f \u0623\u0649 \u0639\u0638\u064a\u0645 \u0643\u0631\u064a\u0645\u060c \u0648\u0627\u0644\u0645\u062c\u064a\u062f \u0635\u0641\u0629 \u0645\u0646 \u0643\u0645\u0644 \u0641\u064a \u0627\u0644\u0634\u0631\u0641.","\u0627\u0644\u0644\u0647\u0645 \u0628\u0627\u0631\u0643 \u0639\u0644\u0649 \u0645\u062d\u0645\u062f \u0648\u0639\u0644\u0649 \u0622\u0644 \u0645\u062d\u0645\u062f \u0643\u0645\u0627 \u0628\u0627\u0631\u0643\u062a \u0639\u0644\u0649 \u0625\u0628\u0631\u0627\u0647\u064a\u0645 \u0648\u0639\u0644\u0649 \u0622\u0644 \u0625\u0628\u0631\u0627\u0647\u064a\u0645\u060c \u0623\u064a: \u0623\u062b\u0628\u062a \u0648\u0623\u062f\u0645 \u0644\u0647 \u0645\u0627 \u0623\u0639\u0637\u064a\u062a\u0647 \u0645\u0646 \u0627\u0644\u062a\u0634\u0631\u064a\u0641 \u0648\u0627\u0644\u0643\u0631\u0627\u0645\u0629 \u0648\u0632\u062f\u0647 \u0645\u0646 \u0627\u0644\u0643\u0645\u0627\u0644\u0627\u062a \u0645\u0627 \u064a\u0644\u064a\u0642 \u0628\u0643 \u0648\u0628\u0647\u060c \u0648\u0642\u064a\u0644: \u0627\u0644\u0645\u0631\u0627\u062f \u0628\u0627\u0644\u0628\u0631\u0643\u0629 \u0647\u0646\u0627 \u0627\u0644\u0632\u064a\u0627\u062f\u0629 \u0645\u0646 \u0627\u0644\u062e\u064a\u0631 \u0648\u0627\u0644\u0643\u0631\u0627\u0645\u0629\u060c \u0648\u0642\u064a\u0644: \u0627\u0644\u0645\u0631\u0627\u062f \u0627\u0644\u062a\u0637\u0647\u064a\u0631 \u0645\u0646 \u0627\u0644\u0630\u0646\u0648\u0628 \u0648\u0627\u0644\u062a\u0632\u0643\u064a\u0629\u060c \u0648\u0627\u0644\u062d\u0627\u0635\u0644 \u0623\u0646 \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0623\u0646 \u064a\u0639\u0637\u0649 \u0645\u0646 \u0627\u0644\u062e\u064a\u0631 \u0623\u0648\u0641\u0627\u0647\u060c \u0648\u0623\u0646 \u064a\u062b\u0628\u062a \u0630\u0644\u0643 \u0648\u064a\u0633\u062a\u0645\u0631 \u062f\u0627\u0626\u0645\u0627.","\u0625\u0646\u0643 \u062d\u0645\u064a\u062f \u0645\u062c\u064a\u062f\u060c \u0647\u0630\u0627 \u062a\u064e\u0630\u064a\u064a\u0644 \u0644\u0644\u0643\u0644\u0627\u0645 \u0627\u0644\u0633\u0627\u0628\u0642 \u0648\u062a\u0642\u0631\u064a\u0631 \u0644\u0647 \u0639\u0644\u0649 \u0633\u0628\u064a\u0644 \u0627\u0644\u0639\u0645\u0648\u0645\u060c \u0623\u064a: \u0625\u0646\u0643 \u062d\u0645\u064a\u062f \u0641\u0627\u0639\u0644 \u0645\u0627 \u062a\u0633\u062a\u0648\u062c\u0628 \u0628\u0647 \u0627\u0644\u062d\u0645\u062f\u061b \u0645\u0646 \u0627\u0644\u0646\u0639\u0645 \u0627\u0644\u0645\u062a\u0643\u0627\u062b\u0631\u0629 \u0648\u0627\u0644\u0622\u0644\u0627\u0621 \u0627\u0644\u0645\u062a\u0639\u0627\u0642\u0628\u0629 \u0627\u0644\u0645\u062a\u0648\u0627\u0644\u064a\u0629\u060c \u0645\u062c\u064a\u062f \u0643\u0631\u064a\u0645 \u0627\u0644\u0625\u062d\u0633\u0627\u0646 \u0625\u0644\u0649 \u062c\u0645\u064a\u0639 \u0639\u0628\u0627\u062f\u0643 \u0627\u0644\u0635\u0627\u0644\u062d\u064a\u0646\u060c \u0648\u0645\u0646 \u0645\u062d\u0627\u0645\u062f\u0643 \u0648\u0625\u062d\u0633\u0627\u0646\u0643 \u0623\u0646 \u062a\u0648\u062c\u0647 \u0635\u0644\u0648\u0627\u062a\u0643 \u0648\u0628\u0631\u0643\u0627\u062a\u0643 \u0648\u062a\u0631\u062d\u0645\u0643 \u0639\u0644\u0649 \u062d\u0628\u064a\u0628\u0643 \u0646\u0628\u064a \u0627\u0644\u0631\u062d\u0645\u0629 \u0648\u0622\u0644\u0647."],t.s)
