B.aE_=s(["\u062a\u0642\u0648\u0644 \u0623\u0645 \u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646 \u0631\u0636\u064a\u064e \u0627\u0644\u0644\u0647 \u0639\u0646\u0647\u0627: \u0644\u0645\u0627 \u0642\u062f\u0650\u0645\u062a\u064f \u0625\u0644\u0649 \u0627\u0644\u0645\u062f\u064a\u0646\u0629 \u0623\u0635\u0627\u0628\u064e\u0646\u064a \u0627\u0644\u0645\u0631\u0636 \u0634\u0647\u0631\u064b\u0627\u060c \u0648\u0644\u0627 \u0623\u0639\u0644\u0645\u064f \u0634\u064a\u0626\u064b\u0627 \u0645\u0645\u0627 \u064a\u0642\u0648\u0644\u0647\u064f \u0627\u0644\u0646\u0627\u0633\u060c \u062d\u062a\u0649 \u062e\u0631\u062c\u062a \u0625\u0644\u0649 \u0627\u0644\u0645\u0646\u0627\u0635\u0639 \u0644\u0642\u0636\u0627\u0621 \u0627\u0644\u062d\u0627\u062c\u0629\u060c \u0645\u0639 \u0623\u0645 \u0645\u0633\u0637\u062d \u0648\u0647\u064a \u0628\u0646\u062a \u062e\u0627\u0644\u0629 \u0623\u0628\u064a \u0628\u0643\u0631\u064d \u0631\u0636\u064a\u064e \u0627\u0644\u0644\u0647 \u0639\u0646\u0647\u060c \u0641\u0639\u062b\u0631\u062a \u0623\u0645 \u0645\u0633\u0637\u062d \u0641\u064a \u0645\u0631\u0637\u0650\u0647\u0627\u060c \u0641\u0642\u0627\u0644\u062a: \u062a\u0639\u0650\u0633\u064e \u0645\u0633\u0637\u062d.","\u0641\u0642\u0644\u062a\u064f: \u0628\u0626\u0633 \u0645\u0627 \u0642\u0644\u062a\u0650! \u0623\u062a\u0633\u0628\u0651\u0650\u064a\u0646\u064e \u0631\u062c\u0644\u064b\u0627 \u0634\u0647\u062f \u0628\u062f\u0631\u064b\u0627\u061f \u0641\u0642\u0627\u0644\u062a: \u0623\u0648\u064e \u0645\u0627 \u0633\u0645\u0639\u062a\u0650 \u0645\u0627 \u0642\u0627\u0644\u061f .. \u0641\u0623\u062e\u0628\u0631\u062a\u0647\u0627 \u0623\u0645 \u0645\u0633\u0637\u062d \u0628\u0645\u0627 \u064a\u0642\u0648\u0644\u0647\u064f \u0623\u0647\u0644 \u0627\u0644\u0625\u0641\u0643\u0650\u060c \u0648\u0628\u0645\u0627 \u064a\u062e\u0648\u0636\u0648\u0646\u064e \u0628\u0647 \u0641\u064a \u0639\u0631\u0636\u0650\u0647\u0627 \u0631\u0636\u064a\u064e \u0627\u0644\u0644\u0647 \u0639\u0646\u0647\u0627."],t.s)
