B.aRY=s(["\u062a\u0647\u064a\u0651\u0623 \u0627\u0644\u0631\u0648\u0645 \u0641\u064a \u0627\u0644\u0634\u0627\u0645 \u0644\u0645\u0648\u0627\u062c\u0647\u0629 \u0627\u0644\u0645\u0633\u0644\u0645\u064a\u0646\u060c \u0625\u0630 \u0643\u0627\u0646\u062a \u0644\u0647\u0645 \u0641\u064a\u0647\u0627 \u0645\u0639\u0627\u0642\u0644 \u0631\u0627\u0633\u062e\u0629 \u0648\u062c\u064a\u0648\u0634 \u062c\u0631\u0651\u0627\u0631\u0629\u060c \u064a\u0633\u0639\u0648\u0646 \u0645\u0646 \u062e\u0644\u0627\u0644\u0647\u0627 \u0625\u0644\u0649 \u0627\u0633\u062a\u0639\u0627\u062f\u0629 \u0646\u0641\u0648\u0630\u0647\u0645 \u0639\u0644\u0649 \u0634\u0645\u0627\u0644 \u0627\u0644\u062c\u0632\u064a\u0631\u0629.","\u0641\u0628\u0639\u062b \u0623\u0628\u0648 \u0628\u0643\u0631\u064d \u0627\u0644\u0635\u062f\u064a\u0642 \u0631\u0636\u064a\u064e \u0627\u0644\u0644\u0647 \u0639\u0646\u0647 \u0623\u0631\u0628\u0639\u0629 \u062c\u064a\u0648\u0634 \u0625\u0644\u0649 \u0627\u0644\u0634\u0627\u0645\u060c \u064a\u0642\u0648\u062f\u0647\u0627: \u064a\u0632\u064a\u062f \u0628\u0646 \u0623\u0628\u064a \u0633\u0641\u064a\u0627\u0646\u060c \u0648\u0634\u0631\u062d\u0628\u064a\u0644 \u0628\u0646 \u062d\u0633\u0646\u0629\u060c \u0648\u0639\u0645\u0631\u0648 \u0628\u0646 \u0627\u0644\u0639\u0627\u0635\u060c \u0648\u0623\u0628\u0648 \u0639\u0628\u064a\u062f\u0629 \u0628\u0646 \u0627\u0644\u062c\u0631\u0627\u062d \u0631\u0636\u064a\u064e \u0627\u0644\u0644\u0647 \u0639\u0646\u0647\u0645\u060c \u0648\u0633\u0627\u0631 \u0643\u0644\u0651\u064c \u0645\u0646\u0647\u0645 \u0641\u064a \u0648\u062c\u0647\u0629 \u0645\u062d\u062f\u0651\u062f\u0629\u060c \u062d\u062a\u0649 \u064a\u062a\u0641\u0631\u0651\u0642 \u0636\u063a\u0637 \u0627\u0644\u0631\u0648\u0645.","\u0641\u0644\u0645\u0651\u0627 \u0627\u062d\u062a\u062f\u0645 \u0627\u0644\u062e\u0637\u0631\u060c \u0623\u0631\u0633\u0644 \u0623\u0628\u0648 \u0628\u0643\u0631\u064d \u0625\u0644\u0649 \u062e\u0627\u0644\u062f \u0628\u0646 \u0627\u0644\u0648\u0644\u064a\u062f \u0628\u0631\u0633\u0627\u0644\u0629\u060c \u064a\u0623\u0645\u0631\u0647 \u0641\u064a\u0647\u0627 \u0628\u0627\u0644\u062a\u062d\u0631\u0651\u0643 \u0645\u0646 \u0627\u0644\u0639\u0631\u0627\u0642 \u0625\u0644\u0649 \u0627\u0644\u0634\u0627\u0645\u060c \u0648\u0642\u0627\u0644 \u0644\u0647: \u0627\u0646\u062c\u062f \u0625\u062e\u0648\u0627\u0646\u0643 \u0641\u064a \u0627\u0644\u0634\u0627\u0645\u060c \u0648\u0643\u0646 \u0639\u0644\u064a\u0647\u0645 \u0623\u0645\u064a\u0631\u064b\u0627."],t.s)
