B.aLL=s(["\u0627\u0646\u0637\u0644\u0642 \u062e\u0627\u0644\u062f \u0631\u0636\u064a\u064e \u0627\u0644\u0644\u0647 \u0639\u0646\u0647 \u064a\u0634\u0642 \u0637\u0631\u064a\u0642\u064b\u0627 \u0639\u0633\u0643\u0631\u064a\u064b\u0627 \u063a\u064a\u0631 \u0645\u0633\u0628\u0648\u0642 \u0645\u0646 \u0627\u0644\u0639\u0631\u0627\u0642 \u0625\u0644\u0649 \u0627\u0644\u0634\u0627\u0645\u060c \u0639\u0627\u0628\u0631\u064b\u0627 \u0635\u062d\u0631\u0627\u0621 \u0627\u0644\u0633\u0645\u0627\u0648\u0629 \u0627\u0644\u0642\u0627\u062d\u0644\u0629 \u062d\u064a\u062b \u0644\u0627 \u0645\u0627\u0621 \u064a\u064f\u0631\u062a\u062c\u0649\u060c \u0648\u0644\u0627 \u0638\u0644\u0651 \u0641\u064a\u0647 \u064a\u064f\u0633\u062a\u0631\u0627\u062d\u060c \u0641\u064a \u0645\u0633\u064a\u0631\u0629 \u0645\u0630\u0647\u0644\u0629\u060c \u0644\u064a\u0633\u0627\u0646\u062f \u0627\u0644\u0642\u0627\u0626\u062f \u0623\u0628\u0627 \u0639\u0628\u064a\u062f\u0629 \u0648\u0627\u0644\u0645\u062c\u0627\u0647\u062f\u064a\u0646 \u0647\u0646\u0627\u0643.","\u0648\u0643\u0627\u0646\u062a \u0635\u062d\u0631\u0627\u0621 \u0627\u0644\u0633\u0645\u0627\u0648\u0629\u0650 \u0623\u0648 \u0628\u0627\u062f\u064a\u0629 \u0627\u0644\u0634\u0627\u0645\u060c \u0628\u0645\u0646\u0627\u062e\u0647\u0627 \u0627\u0644\u0642\u0627\u0633\u064a \u0634\u0627\u0647\u062f\u064b\u0627 \u0639\u0644\u0649 \u0647\u0630\u0627 \u0627\u0644\u062a\u062d\u062f\u064a \u0627\u0644\u0641\u0630\u0651\u060c \u0625\u0630 \u0648\u0635\u0644 \u062e\u0627\u0644\u062f \u0645\u0639 \u0627\u0644\u062c\u064a\u0634 \u0625\u0644\u0649 \u0645\u0634\u0627\u0631\u0641 \u0627\u0644\u0634\u0627\u0645 \u0641\u064a \u0644\u062d\u0638\u0629 \u062d\u0627\u0633\u0645\u0629 \u063a\u064a\u0651\u0631\u062a \u0645\u062c\u0631\u0649 \u0627\u0644\u062a\u0627\u0631\u064a\u062e.","\u0648\u062a\u0645\u062a\u062f \u0635\u062d\u0631\u0627\u0621 \u0627\u0644\u0633\u0645\u0627\u0648\u0629 \u0645\u0646 \u063a\u0631\u0628 \u0627\u0644\u0639\u0631\u0627\u0642\u060c \u0625\u0644\u0649 \u0634\u0645\u0627\u0644 \u0634\u0631\u0642 \u0627\u0644\u0623\u0631\u062f\u0646\u060c \u0648\u062c\u0646\u0648\u0628 \u0634\u0631\u0642 \u0633\u0648\u0631\u064a\u0627\u060c \u0648\u062a\u0635\u0644 \u0623\u0637\u0631\u0627\u0641\u0647\u0627 \u0625\u0644\u0649 \u0634\u0645\u0627\u0644 \u0627\u0644\u0633\u0639\u0648\u062f\u064a\u0629."],t.s)
