B.ayn=s(["\u0627\u0644\u0648\u0627\u062c\u0628\u064f \u0639\u0644\u0649 \u0627\u0644\u0645\u064f\u0633\u0644\u0645\u0650 \u0623\u0646 \u064a\u064e\u062c\u062a\u0646\u0650\u0628\u064e \u0645\u064e\u0648\u0627\u0636\u0650\u0639\u064e \u0627\u0644\u0641\u0650\u062a\u0646\u0650\u061b \u0644\u0623\u0646\u0651\u064e\u0647 \u0644\u0627 \u0623\u062d\u064e\u062f\u064e \u064a\u064e\u0623\u0645\u064e\u0646\u064f \u0639\u0644\u0649 \u0646\u0641\u0633\u0650\u0647 \u0645\u0646\u0647\u0627\u060c \u0648\u0627\u0644\u0645\u064e\u0639\u0635\u0648\u0645\u064f \u0645\u064e\u0646 \u0639\u064e\u0635\u064e\u0645\u064e\u0647 \u0627\u0644\u0644\u0647\u064f \u062a\u0639\u0627\u0644\u064e\u0649\u060c \u0648\u0642\u062f \u0623\u0631\u0634\u064e\u062f\u064e \u0627\u0644\u0646\u0651\u064e\u0628\u064a\u0651\u064f \ufdfa \u0623\u064f\u0645\u0651\u064e\u062a\u064e\u0647 \u0625\u0644\u0649 \u0645\u0627 \u064a\u064e\u062c\u0650\u0628\u064f \u0641\u0650\u0639\u0644\u064f\u0647 \u0641\u064a \u0648\u064e\u0642\u062a\u0650 \u0627\u0644\u0641\u0650\u062a\u0646\u0650\u060c \u0648\u062d\u0630\u0651\u064e\u0631\u064e\u0647\u0627 \u0645\u0650\u0646 \u0633\u064f\u0648\u0621\u0650 \u0639\u0627\u0642\u0650\u0628\u0629\u0650 \u0627\u0644\u0627\u0646\u062e\u0650\u0631\u0627\u0637\u0650 \u0641\u064a\u0647\u0627.","\u0648\u0641\u064a \u0647\u0630\u0627 \u0627\u0644\u062d\u064e\u062f\u064a\u062b\u0650 \u064a\u064f\u062e\u0628\u0650\u0631\u064f \u0627\u0644\u0646\u0651\u064e\u0628\u064a\u0651\u064f \ufdfa \u0623\u0646\u0651\u064e\u0647 \u0633\u062a\u064e\u062d\u0635\u064f\u0644\u064f \u0648\u062a\u064e\u0623\u062a\u064a \u0641\u0650\u062a\u0646\u064c \u0639\u0644\u0649 \u0647\u0630\u0647 \u0627\u0644\u0623\u064f\u0645\u0651\u064e\u0629\u0650\u060c \u0648\u0627\u0644\u0645\u064f\u0631\u0627\u062f\u064f \u0628\u0647\u0630\u0647 \u0627\u0644\u0641\u0650\u062a\u0646\u0650: \u0627\u0644\u0651\u064e\u062a\u064a \u064a\u064e\u062e\u062a\u0644\u0650\u0637\u064f \u0641\u064a\u0647\u0627 \u0627\u0644\u062d\u0642\u0651\u064f \u0628\u0627\u0644\u0628\u0627\u0637\u0644\u0650\u061b \u0641\u0644\u0627 \u064a\u064f\u0639\u0644\u064e\u0645\u064f \u0627\u0644\u0645\u064f\u062d\u0650\u0642\u0651\u064f \u0641\u064a\u0647\u0627 \u0645\u0650\u0646 \u0627\u0644\u0645\u064f\u0628\u0637\u0650\u0644\u0650\u060c \u0648\u064a\u064f\u0642\u0627\u062a\u064e\u0644\u064f \u0641\u064a\u0647\u0627 \u0639\u0644\u0649 \u0627\u0644\u062f\u0651\u064f\u0646\u064a\u0627. \xab\u0627\u0644\u0642\u0627\u0639\u0650\u062f\u064f \u0641\u064a\u0647\u0627 \u062e\u064e\u064a\u0631\u064c \u0645\u0650\u0646 \u0627\u0644\u0642\u0627\u0626\u0645\u0650\u060c \u0648\u0627\u0644\u0642\u0627\u0626\u0645\u064f \u0641\u064a\u0647\u0627 \u062e\u064e\u064a\u0631\u064c \u0645\u0646\u064e \u0627\u0644\u0645\u0627\u0634\u064a\u060c \u0648\u0627\u0644\u0645\u0627\u0634\u064a \u0641\u064a\u0647\u0627 \u062e\u064e\u064a\u0631\u064c \u0645\u0646\u064e \u0627\u0644\u0633\u0651\u064e\u0627\u0639\u064a\xbb\u060c \u0648\u0627\u0644\u0645\u064e\u0642\u0635\u0648\u062f\u064f \u0628\u064e\u064a\u0627\u0646\u064f \u0639\u0650\u0638\u064e\u0645\u0650 \u062e\u064e\u0637\u064e\u0631\u0650\u0647\u0627\u060c \u0648\u0627\u0644\u062d\u064e\u062b\u0651\u064f \u0639\u0644\u0649 \u062a\u064e\u062c\u0646\u0651\u064f\u0628\u0650\u0647\u0627\u060c \u0648\u0627\u0644\u0647\u0631\u064e\u0628\u0650 \u0645\u0646\u0647\u0627\u060c \u0648\u0639\u062f\u064e\u0645\u0650 \u0627\u0644\u062a\u0651\u064e\u0633\u0628\u0651\u064f\u0628\u0650 \u0641\u064a \u0634\u064e\u064a\u0621\u064d \u0645\u0646\u0647\u0627\u061b \u0644\u0623\u0646\u0651\u064e \u0633\u064e\u0628\u0628\u064e\u0647\u0627 \u0648\u0634\u064e\u0631\u0651\u064e\u0647\u0627 \u0648\u0641\u0650\u062a\u0646\u062a\u064e\u0647\u0627 \u062a\u0643\u0648\u0646\u064f \u0639\u0644\u0649 \u062d\u0633\u064e\u0628\u0650 \u0627\u0644\u062a\u0651\u064e\u0639\u0644\u0651\u064f\u0642\u0650 \u0628\u0647\u0627\u061b \u0641\u0627\u0644\u0642\u0627\u0639\u0650\u062f\u064f \u064a\u0643\u0648\u0646\u064f \u0623\u0642\u0644\u0651\u064e \u0645\u0650\u0646 \u0627\u0644\u0645\u0627\u0634\u064a\u060c \u0648\u0627\u0644\u0645\u0627\u0634\u064a \u0623\u0642\u0644\u0651\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0633\u0651\u064e\u0627\u0639\u064a\u060c \u0648\u0647\u0643\u0630\u0627\u060c \xab\u0648\u0645\u064e\u0646 \u064a\u064f\u0634\u0631\u0650\u0641 \u0644\u0647\u0627 \u062a\u064e\u0633\u062a\u064e\u0634\u0631\u0650\u0641\u0647\xbb\u060c \u0623\u064a: \u0645\u064e\u0646 \u064a\u064e\u062a\u0637\u0644\u0651\u064e\u0639 \u0625\u0644\u064a\u0647\u0627 \u0648\u064a\u064e\u062a\u0639\u0631\u0651\u064e\u0636 \u0644\u0647\u0627 \u062a\u064e\u063a\u0644\u0650\u0628\u0647 \u0648\u062a\u064f\u0647\u0644\u0650\u0643\u0647\u060c \xab\u0648\u0645\u064e\u0646 \u0648\u062c\u064e\u062f\u064e \u0645\u064e\u0644\u062c\u0623\u064b\u060c \u0623\u0648 \u0645\u064e\u0639\u0627\u0630\u064b\u0627 \u0641\u0644\u064a\u064e\u0639\u064f\u0630 \u0628\u0647\xbb\u060c \u0623\u064a: \u0645\u064e\u0646 \u0648\u064e\u062c\u062f\u064e \u0637\u064e\u0631\u064a\u0642\u064b\u0627 \u064a\u064e\u062a\u0651\u0650\u0642\u064a \u0628\u0647 \u0627\u0644\u0645\u064f\u0634\u0627\u0631\u064e\u0643\u0629\u064e \u0641\u064a \u0647\u0630\u0647 \u0627\u0644\u0641\u0650\u062a\u064e\u0646\u0650 \u0641\u0644\u064a\u0641\u0639\u064e\u0644\u060c \u0648\u0644\u064a\u064e\u0639\u0635\u0650\u0645 \u062f\u0650\u064a\u0646\u064e\u0647 \u0648\u062f\u064f\u0646\u064a\u0627\u0647 \u0645\u0650\u0646 \u0627\u0644\u062e\u064e\u0648\u0636\u0650 \u0641\u064a\u0647\u0627.","\u0648\u0641\u064a \u0627\u0644\u062d\u064e\u062f\u064a\u062b\u0650: \u0639\u064e\u0644\u0627\u0645\u0629\u064c \u0645\u0650\u0646 \u0639\u064e\u0644\u0627\u0645\u0627\u062a\u0650 \u0627\u0644\u0646\u0651\u064f\u0628\u0648\u0651\u064e\u0629\u0650\u060c \u0648\u0641\u064a\u0647: \u0627\u0644\u0625\u062e\u0628\u0627\u0631\u064f \u0628\u0648\u064f\u0642\u0648\u0639\u0650 \u0627\u0644\u0641\u0650\u062a\u0646\u0650 \u0644\u0644\u062a\u0651\u064e\u062d\u0630\u064a\u0631\u0650 \u0645\u0646\u0647\u0627\u060c \u0648\u0644\u064a\u064e\u062a\u0623\u0647\u0651\u064e\u0628\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u064f \u0644\u0647\u0627\u060c \u0641\u0644\u0627 \u064a\u064e\u062e\u0648\u0636\u0648\u0627 \u0641\u064a\u0647\u0627\u060c \u0648\u064a\u064e\u0633\u0623\u064e\u0644\u0648\u0627 \u0627\u0644\u0644\u0647\u064e \u0627\u0644\u0635\u0651\u064e\u0628\u0631\u064e \u0648\u0627\u0644\u0646\u0651\u064e\u062c\u0627\u0629\u064e \u0645\u0650\u0646 \u0634\u064e\u0631\u0651\u0650\u0647\u0627."],t.s)
B.anI=new A.h("fitanHadiths_7","\u0627\u0644\u062a\u064e\u0651\u062d\u0631\u064f\u0651\u0632 \u0645\u0646 \u0627\u0644\u062e\u0648\u0636\u0650 \u0641\u064a \u0627\u0644\u0641\u0650\u062a\u0646","\u0639\u064e\u0646 \u0623\u0628\u064a \u0647\u064f\u0631\u064a\u0631\u064e\u0629 \u0631\u064e\u0636\u064a\u064e \u0627\u0644\u0644\u0647\u064f \u0639\u0646\u0647 \u0642\u0627\u0644\u064e: \u0642\u0627\u0644\u064e \u0631\u0633\u0648\u0644\u064f \u0627\u0644\u0644\u0647\u0650 \ufdfa : \u0633\u064e\u062a\u064e\u0643\u064f\u0648\u0646\u064f \u0641\u0650\u062a\u064e\u0646\u064c \u0627\u0644\u0642\u0627\u0639\u0650\u062f\u064f \u0641\u064a\u0647\u0627 \u062e\u064e\u064a\u0631\u064c \u0645\u0650\u0646\u064e \u0627\u0644\u0642\u0627\u0626\u0650\u0645\u0650\u060c \u0648\u0627\u0644\u0642\u0627\u0626\u0650\u0645\u064f \u0641\u064a\u0647\u0627 \u062e\u064e\u064a\u0631\u064c \u0645\u0650\u0646\u064e \u0627\u0644\u0645\u0627\u0634\u0650\u064a\u060c \u0648\u0627\u0644\u0645\u0627\u0634\u0650\u064a \u0641\u064a\u0647\u0627 \u062e\u064e\u064a\u0631\u064c \u0645\u0650\u0646\u064e \u0627\u0644\u0633\u0651\u064e\u0627\u0639\u0650\u064a\u060c \u0648\u0645\u064e\u0646 \u064a\u064f\u0634\u0631\u0650\u0641 \u0644\u0647\u0627 \u062a\u064e\u0633\u062a\u064e\u0634\u0631\u0650\u0641\u0647\u064f\u060c \u0648\u0645\u064e\u0646 \u0648\u062c\u064e\u062f\u064e \u0645\u064e\u0644\u062c\u064e\u0623\u064b \u0623\u0648 \u0645\u064e\u0639\u0627\u0630\u064b\u0627 \u0641\u064e\u0644\u064a\u064e\u0639\u064f\u0630 \u0628\u0647\u0650 - \u0631\u0648\u0627\u0647 \u0627\u0644\u0628\u062e\u0627\u0631\u064a",B.ayn)
B.aIQ=s(["\u0643\u0627\u0646 \u0627\u0644\u0646\u0628\u064a\u0651\u064f \ufdfa \u064a\u064f\u062d\u0630\u0651\u0650\u0631\u064f \u0623\u064f\u0645\u0651\u064e\u062a\u064e\u0647 \u0645\u0650\u0646\u064e \u0627\u0644\u0641\u0650\u062a\u0646\u0650\u060c \u0648\u062e\u0627\u0635\u0651\u064e\u0629\u064b \u0645\u0627 \u064a\u0643\u0648\u0646\u064f \u0645\u0646\u0647\u0627 \u0641\u064a \u0622\u062e\u0650\u0631\u0650 \u0627\u0644\u0632\u0651\u064e\u0645\u0627\u0646\u0650\u060c \u0648\u0641\u064a \u0647\u0630\u0627 \u0627\u0644\u062d\u064e\u062f\u064a\u062b\u0650 \u064a\u064f\u0628\u064a\u0651\u0650\u0646\u064f \u0627\u0644\u0646\u0628\u064a\u0651\u064f \ufdfa \u0644\u0644\u0635\u0651\u064e\u062d\u0627\u0628\u0629\u0650 \u0627\u0644\u0643\u0631\u0627\u0645\u0650 \u0631\u064e\u0636\u064a\u064e \u0627\u0644\u0644\u0647\u064f \u0639\u0646\u0647\u0645 \u0623\u0646\u0651\u064e\u0647 \u064a\u064e\u0642\u0631\u064f\u0628\u064f \u0623\u0646 \u062a\u064e\u062a\u063a\u064a\u0651\u064e\u0631\u064e \u0648\u062a\u064e\u062a\u0628\u062f\u0651\u064e\u0644\u064e \u0627\u0644\u0623\u062d\u0648\u0627\u0644\u064f\u060c \u0648\u062a\u064e\u062f\u062e\u064f\u0644\u064e \u0627\u0644\u0641\u0650\u062a\u064e\u0646\u064f \u0648\u062a\u064e\u0639\u064f\u0645\u0651\u064e \u0627\u0644\u0646\u0627\u0633\u064e \u0648\u0627\u0644\u0628\u0650\u0644\u0627\u062f\u064e.","\u0641\u0625\u0630\u0627 \u0643\u0627\u0646 \u0627\u0644\u062d\u0627\u0644\u064f \u0643\u0630\u0644\u0643\u061b \u0641\u0625\u0646\u0651\u064e \u062e\u064a\u0631\u064e \u0645\u0627\u0644\u064d \u064a\u062a\u0651\u064e\u062e\u0650\u0630\u064f\u0647 \u0627\u0644\u0645\u0633\u0644\u0650\u0645\u064f \u062d\u064a\u064e\u0646\u0626\u0630\u064d \u0647\u0648 \u0627\u0644\u063a\u064e\u0646\u064e\u0645\u064f\u060c \u0648\u062e\u064f\u0635\u0651\u064e\u062a \u0628\u0630\u0644\u0643\u061b \u0644\u0650\u0645\u064e\u0627 \u0641\u064a\u0647\u0627 \u0645\u0650\u0646 \u0627\u0644\u0633\u0651\u064e\u0643\u064a\u0646\u0629\u0650 \u0648\u0627\u0644\u0628\u064e\u0631\u064e\u0643\u0629\u0650\u061b \u0644\u0623\u0646\u0651\u064e \u0627\u0644\u0645\u064f\u0639\u062a\u0632\u0650\u0644\u064e \u0639\u0646\u0650 \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0628\u0627\u0644\u063a\u064e\u0646\u0645\u0650 \u064a\u064e\u0623\u0643\u064f\u0644\u064f \u0645\u0650\u0646 \u0644\u064f\u062d\u0648\u0645\u0650\u0647\u0627 \u0648\u0646\u0650\u062a\u0627\u062c\u0650\u0647\u0627\u060c \u0648\u064a\u064e\u0634\u0631\u064e\u0628\u064f \u0645\u0650\u0646 \u0623\u0644\u0628\u0627\u0646\u0650\u0647\u0627\u060c \u0648\u064a\u064e\u0633\u062a\u0645\u062a\u0650\u0639\u064f \u0628\u0623\u0635\u0648\u0627\u0641\u0650\u0647\u0627 \u0628\u0627\u0644\u0644\u0651\u064f\u0628\u0633\u0650 \u0648\u063a\u064a\u0631\u0650\u0647\u060c \u0648\u0647\u064a \u062a\u064e\u0631\u0639\u064e\u0649 \u0627\u0644\u0646\u0651\u064e\u0628\u0627\u062a\u064e \u0648\u0627\u0644\u0639\u064f\u0634\u0628\u064e \u0641\u064a \u0627\u0644\u062c\u0650\u0628\u0627\u0644\u0650\u060c \u0648\u062a\u064e\u0631\u0650\u062f\u064f \u0627\u0644\u0645\u0650\u064a\u0627\u0647\u064e\u060c \u0648\u0647\u0630\u0647 \u0627\u0644\u0645\u064e\u0646\u0627\u0641\u0639\u064f \u0648\u0627\u0644\u0645\u0631\u0627\u0641\u0650\u0642\u064f \u0644\u0627 \u062a\u064f\u0648\u062c\u064e\u062f\u064f \u0641\u064a \u063a\u064a\u0631\u0650 \u0627\u0644\u063a\u064e\u0646\u0645\u0650\u060c \u0648\u0643\u0630\u0644\u0643 \u0647\u064a \u0641\u064a \u0646\u064f\u0645\u064f\u0648\u0651\u0650\u0647\u0627 \u0648\u0632\u0650\u064a\u0627\u062f\u062a\u0650\u0647\u0627 \u0623\u0628\u0639\u064e\u062f\u064f \u0645\u0650\u0646 \u0627\u0644\u0634\u0651\u064e\u0648\u0627\u0626\u0628\u0650 \u0627\u0644\u0645\u064f\u062d\u0631\u0651\u064e\u0645\u0629\u0650\u061b \u0643\u0627\u0644\u0631\u0651\u0650\u0628\u0627\u060c \u0648\u0627\u0644\u0634\u0651\u064f\u0628\u0647\u0627\u062a\u0650 \u0627\u0644\u0645\u064e\u0643\u0631\u0648\u0647\u0629\u0650\u060c \u0648\u0647\u064a \u0633\u064e\u0647\u0644\u0629\u064f \u0627\u0644\u0627\u0646\u0642\u064a\u0627\u062f\u0650\u060c \u062e\u064e\u0641\u064a\u0641\u0629\u064f \u0627\u0644\u0645\u064e\u0624\u064f\u0648\u0646\u0629\u0650\u060c \u0643\u064e\u062b\u064a\u0631\u0629\u064f \u0627\u0644\u0646\u0651\u064e\u0641\u0639\u0650\u060c \u0641\u064a\u064e\u0631\u0639\u0627\u0647\u0627 \u0648\u064a\u064e\u062a\u0628\u064e\u0639\u064f \u0628\u0647\u0627 \xab\u0634\u064e\u0639\u064e\u0641\u064e \u0627\u0644\u062c\u0628\u0627\u0644\u0650\xbb\u060c \u0623\u064a: \u0631\u064f\u0624\u0648\u0633\u064e\u0647\u0627 \u0648\u0623\u0639\u0627\u0644\u064a\u064e\u0647\u0627\u061b \u0641\u0625\u0646\u0651\u064e\u0647\u0627 \u062a\u064e\u0639\u0635\u0650\u0645\u064f \u0645\u064e\u0646 \u0644\u064e\u062c\u064e\u0623 \u0625\u0644\u064a\u0647\u0627 \u0645\u0650\u0646 \u0639\u062f\u064f\u0648\u0651\u064d\u060c \xab\u0648\u0645\u064e\u0648\u0627\u0642\u0650\u0639\u064e \u0627\u0644\u0645\u064e\u0637\u0631\u0650\xbb\u061b \u0648\u0647\u064a \u0628\u064f\u0637\u0648\u0646\u064f \u0627\u0644\u0623\u0648\u062f\u064a\u0629\u0650 \u0648\u0627\u0644\u0635\u0651\u064e\u062d\u0627\u0631\u0649\u061b \u0644\u0623\u0646\u0651\u064e\u0647 \u064a\u064e\u062c\u0650\u062f\u064f \u0641\u064a\u0647\u0627 \u0627\u0644\u0643\u0644\u064e\u0623\u064e \u0648\u0627\u0644\u0639\u064f\u0634\u0628\u064e \u0648\u0627\u0644\u0645\u0627\u0621\u064e\u060c \u0641\u064a\u064e\u0634\u0631\u064e\u0628\u064f \u0645\u0646\u0647\u0627\u060c \u0648\u064a\u064e\u0633\u0642\u0650\u064a \u063a\u064e\u0646\u064e\u0645\u064e\u0647\u060c \u0648\u062a\u064e\u0631\u0639\u0649 \u063a\u0646\u064e\u0645\u064f\u0647 \u0645\u0650\u0646 \u0627\u0644\u0643\u0644\u0623\u0650.","\u0641\u064a\u064e\u0647\u0631\u064f\u0628\u064f \u062e\u064e\u0634\u064a\u0629\u064b \u0639\u0644\u0649 \u062f\u0650\u064a\u0646\u0650\u0647 \u0645\u0650\u0646 \u0627\u0644\u0648\u0642\u0648\u0639\u0650 \u0641\u064a \u062a\u0644\u0643 \u0627\u0644\u0641\u0650\u062a\u064e\u0646\u0650\u060c \u0648\u0637\u0644\u064e\u0628\u064b\u0627 \u0644\u0644\u0633\u0651\u064e\u0644\u0627\u0645\u0629\u0650\u061b \u0641\u0625\u0646\u0651\u064e \u0645\u064e\u0646 \u062e\u0627\u0644\u064e\u0637\u064e \u0627\u0644\u0641\u0650\u062a\u064e\u0646\u064e \u0644\u0645 \u064a\u064e\u0633\u0644\u064e\u0645 \u062f\u0650\u064a\u0646\u064f\u0647 \u0645\u0650\u0646 \u0627\u0644\u0625\u062b\u0645\u0650.","\u0648\u0627\u0644\u0645\u0631\u0627\u062f\u064f \u0628\u0627\u0644\u0641\u0650\u062a\u064e\u0646\u0650 \u0627\u0644\u062a\u064a \u0641\u064a \u0627\u0644\u062d\u062f\u064a\u062b\u0650: \u0647\u064a \u0627\u0644\u0651\u064e\u062a\u064a \u064a\u064e\u062e\u062a\u0644\u0650\u0637\u064f \u0641\u064a\u0647\u0627 \u0627\u0644\u062d\u0642\u0651\u064f \u0628\u0627\u0644\u0628\u0627\u0637\u0644\u0650\u060c \u0648\u0644\u0627 \u064a\u064e\u0642\u062f\u0650\u0631\u064f \u0627\u0644\u0645\u0631\u0621\u064f \u0639\u0644\u0649 \u062a\u064e\u0645\u064a\u064a\u0632\u0650\u0647\u0645\u0627\u060c \u0623\u0645\u0651\u064e\u0627 \u0627\u0644\u0651\u064e\u062a\u064a \u064a\u064e\u062a\u0645\u0627\u064a\u064e\u0632\u064f \u0641\u064a\u0647\u0627 \u0627\u0644\u062d\u0642\u0651\u064f \u0639\u0646 \u0627\u0644\u0628\u0627\u0637\u0644\u0650 \u0641\u0625\u0646\u0651\u064e \u0627\u0644\u0645\u0631\u0621\u064e \u0645\u064f\u0637\u0627\u0644\u064e\u0628\u064c \u0628\u0627\u0644\u0627\u0646\u062d\u064a\u0627\u0632\u0650 \u0625\u0644\u0649 \u0627\u0644\u062d\u0642\u0651\u0650 \u0648\u0645\u064f\u062f\u0627\u0641\u0639\u0629\u0650 \u0627\u0644\u0628\u0627\u0637\u0644\u0650.","\u0648\u064a\u064e\u062d\u062a\u0645\u0650\u0644\u064f \u0623\u0646 \u064a\u0643\u0648\u0646\u064e \u0627\u0644\u0645\u0631\u0627\u062f\u064f \u0628\u0627\u0644\u0641\u0650\u062a\u064e\u0646\u0650: \u0645\u0627 \u064a\u0643\u0648\u0646\u064f \u0645\u0650\u0646 \u063a\u064e\u0644\u064e\u0628\u0629\u0650 \u0627\u0644\u0641\u064e\u0633\u0627\u062f\u0650 \u0639\u0644\u0649 \u0623\u0647\u0644\u0650 \u0627\u0644\u0632\u0651\u064e\u0645\u0627\u0646\u0650\u060c \u0648\u0627\u0633\u062a\u0642\u0648\u0627\u0621\u0650 \u0623\u0647\u0644\u0650 \u0627\u0644\u0628\u0627\u0637\u0644\u0650\u060c \u0648\u0636\u064e\u0639\u0641\u0650 \u0623\u0647\u0644\u0650 \u0627\u0644\u0625\u064a\u0645\u0627\u0646\u0650\u060c \u0641\u0644\u0627 \u064a\u064e\u0633\u0644\u064e\u0645\u064f \u0645\u0646\u0647\u0627 \u0627\u0644\u0645\u064f\u0642\u064a\u0645\u064f \u0641\u064a\u0647\u0627\u060c \u0641\u064a\u064e\u0641\u0650\u0631\u0651\u064f \u0628\u062f\u0650\u064a\u0646\u0650\u0647 \u0645\u0646\u0647\u0627\u061b \u0644\u0623\u0646\u0651\u064e \u0645\u064f\u0635\u064a\u0628\u0629\u064e \u0627\u0644\u062f\u0651\u0650\u064a\u0646\u0650 \u0644\u0627 \u062a\u064e\u0646\u062c\u0628\u0650\u0631\u064f.","\u0648\u0641\u064a \u0627\u0644\u062d\u062f\u064a\u062b\u0650: \u0641\u0636\u0644\u064f \u062a\u064e\u0631\u0628\u064a\u0629\u0650 \u0627\u0644\u063a\u0646\u064e\u0645\u0650\u060c \u0648\u0623\u0646\u0651\u064e\u0647\u0627 \u0623\u0646\u0641\u064e\u0639\u064f \u0627\u0644\u0623\u0645\u0648\u0627\u0644\u0650 \u0639\u0650\u0646\u062f\u064e \u0627\u0644\u0641\u0650\u062a\u064e\u0646\u0650\u060c \u0648\u0641\u064a\u0647: \u0627\u0644\u062a\u0651\u064e\u062d\u0630\u064a\u0631\u064f \u0645\u0650\u0646\u064e \u0627\u0644\u0641\u0650\u062a\u064e\u0646\u0650 \u0648\u0645\u064f\u062e\u0627\u0644\u064e\u0637\u062a\u0650\u0647\u0627 \u0648\u0627\u0644\u0648\u064f\u0642\u0648\u0639\u0650 \u0641\u064a\u0647\u0627."],t.s)
