B.aLp=s(["\u0644\u0645 \u064a\u0643\u0646 \u0627\u0628\u0646\u064f \u0627\u0644\u0642\u064a\u0645 \u0645\u0646\u0642\u0637\u0639\u064b\u0627 \u0639\u0646 \u0634\u0624\u0648\u0646 \u0627\u0644\u062d\u064a\u0627\u0629 \u0645\u0646\u0643\u0641\u0626\u064b\u0627 \u0639\u0644\u0649 \u0643\u062a\u0628\u0647 \u0641\u062d\u0633\u0628\u060c \u0628\u0644 \u0639\u0627\u0634 \u062d\u064a\u0627\u0629\u064b \u0623\u064f\u0633\u0631\u064a\u0651\u0629\u061b \u0641\u062a\u0632\u0648\u0651\u062c \u0648\u0623\u0646\u062c\u0628 \u0648\u0631\u0628\u0651\u0649\u060c \u0648\u0643\u0627\u0646 \u0645\u0646 \u0623\u0628\u0631\u0632 \u0623\u0628\u0646\u0627\u0626\u0647 \u062c\u0645\u0627\u0644\u064f \u0627\u0644\u062f\u064a\u0646 \u0639\u0628\u062f\u064f \u0627\u0644\u0644\u0647\u060c \u0627\u0644\u0630\u064a \u0633\u0644\u0643 \u0637\u0631\u064a\u0642 \u0623\u0628\u064a\u0647 \u0641\u064a \u0627\u0644\u0639\u0644\u0645\u060c \u0641\u062f\u0631\u0651\u0633 \u0641\u064a \u0627\u0644\u0645\u062f\u0631\u0633\u0629 \u0627\u0644\u0635\u062f\u0631\u064a\u0629 \u0628\u062f\u0645\u0634\u0642 \u0628\u0639\u062f \u0648\u0641\u0627\u0629 \u0648\u0627\u0644\u062f\u0647\u060c \u0648\u0643\u0627\u0646 \u0645\u0646 \u062a\u0644\u0627\u0645\u064a\u0630\u0647 \u0648\u0642\u062f \u0631\u0648\u0649 \u0639\u0646\u0647\u060c \u063a\u064a\u0631 \u0623\u0646\u0651 \u0627\u0644\u0645\u0646\u064a\u0629 \u0639\u0627\u062c\u0644\u062a\u0647 \u0634\u0627\u0628\u064b\u0627\u061b \u0625\u0630 \u062a\u064f\u0648\u0641\u0651\u064a \u0628\u0639\u062f \u0648\u0641\u0627\u0629 \u0648\u0627\u0644\u062f\u0647 \u0627\u0628\u0646\u0650 \u0627\u0644\u0642\u064a\u0645 \u0628\u062e\u0645\u0633 \u0633\u0646\u0648\u0627\u062a\u060c \u0641\u062a\u0648\u0642\u0651\u0641 \u0647\u0630\u0627 \u0627\u0644\u0627\u0645\u062a\u062f\u0627\u062f \u0627\u0644\u0639\u0644\u0645\u064a \u0645\u0628\u0643\u0631\u064b\u0627 \u0642\u0628\u0644 \u0623\u0646 \u064a\u0628\u0644\u063a \u0645\u062f\u0627\u0647.","\u0648\u0623\u062f\u0651\u0649 \u0627\u0628\u0646 \u0627\u0644\u0642\u064a\u0645 \u0641\u0631\u064a\u0636\u0629 \u0627\u0644\u062d\u062c \u0623\u0643\u062b\u0631 \u0645\u0646 \u0645\u0631\u0629\u060c \u0648\u0643\u0627\u0646\u062a \u0647\u0630\u0647 \u0627\u0644\u0631\u062d\u0644\u0627\u062a \u062a\u064f\u0645\u062b\u0651\u0644 \u0644\u0647 \u0623\u0643\u062b\u0631 \u0645\u0646 \u0623\u062f\u0627\u0621 \u0634\u0639\u064a\u0631\u0629\u061b \u0641\u0642\u062f \u0643\u0627\u0646 \u064a\u062c\u062f \u0641\u064a \u0627\u0644\u0637\u0648\u0627\u0641 \u0648\u0627\u0644\u0648\u0642\u0648\u0641 \u0628\u0639\u0631\u0641\u0629 \u0648\u0627\u0644\u062c\u0644\u0648\u0633 \u0641\u064a \u0627\u0644\u0645\u0633\u062c\u062f \u0627\u0644\u0646\u0628\u0648\u064a \u0645\u0627 \u064a\u064f\u063a\u0630\u0651\u064a \u0631\u0648\u062d\u0647 \u0648\u064a\u064f\u0639\u0645\u0651\u0642 \u062a\u062c\u0631\u0628\u062a\u0647 \u0627\u0644\u062f\u0627\u062e\u0644\u064a\u0629 \u0627\u0644\u062a\u064a \u062a\u0638\u0647\u0631 \u0622\u062b\u0627\u0631\u0647\u0627 \u0648\u0627\u0636\u062d\u0629\u064b \u0641\u064a \u0643\u062a\u0628\u0647\u060c \u0648\u062e\u0627\u0635\u0629\u064b \u0641\u064a \u0632\u0627\u062f \u0627\u0644\u0645\u0639\u0627\u062f \u0627\u0644\u0630\u064a \u064a\u064f\u062d\u0633\u0651 \u0641\u064a\u0647 \u0627\u0644\u0642\u0627\u0631\u0626 \u0623\u0646 \u0635\u0627\u062d\u0628\u0647 \u0644\u0645 \u064a\u0643\u062a\u0628 \u0639\u0646 \u0627\u0644\u0633\u064a\u0631\u0629 \u0627\u0644\u0646\u0628\u0648\u064a\u0629 \u0645\u0646 \u0628\u0639\u064a\u062f \u0628\u0644 \u0639\u0627\u0634 \u0641\u064a \u0623\u0645\u0627\u0643\u0646\u0647\u0627 \u0648\u062a\u0646\u0641\u0651\u0633 \u0647\u0648\u0627\u0621\u0647\u0627\u060c \u0648\u0643\u0627\u0646\u062a \u0632\u064a\u0627\u0631\u0627\u062a\u0647 \u0644\u0644\u062d\u0631\u0645\u064a\u0646 \u062a\u064f\u0636\u064a\u0641 \u0625\u0644\u0649 \u0643\u062a\u0627\u0628\u0627\u062a\u0647 \u0639\u0646 \u0627\u0644\u0633\u064a\u0631\u0629 \u0648\u0627\u0644\u0639\u0628\u0627\u062f\u0627\u062a \u0637\u0628\u0642\u0629\u064b \u0645\u0646 \u0627\u0644\u0639\u064a\u0627\u0646\u064a\u0629 \u0627\u0644\u062d\u064a\u0651\u0629 \u0644\u0627 \u062a\u062c\u062f\u0647\u0627 \u0639\u0646\u062f \u0645\u0646 \u0627\u0643\u062a\u0641\u0649 \u0628\u0627\u0644\u0645\u0635\u0627\u062f\u0631 \u0627\u0644\u0645\u0643\u062a\u0648\u0628\u0629."],t.s)
