B.anu=new A.h("muminatHadiths_31","\u0639\u0642\u0648\u0628\u0629 \u0627\u0644\u0645\u064f\u0645\u062a\u0646\u0639\u064e\u0629\u0650 \u0639\u0646 \u0641\u0650\u0631\u0627\u0634 \u0632\u0648\u062c\u0647\u0627","\u0639\u064e\u0646 \u0623\u0628\u064a \u0647\u064f\u0631\u064a\u0631\u064e\u0629 \u0631\u064e\u0636\u064a\u064e \u0627\u0644\u0644\u0647\u064f \u0639\u0646\u0647 \u0642\u0627\u0644\u064e: \u0642\u0627\u0644\u064e \u0631\u0633\u0648\u0644\u064f \u0627\u0644\u0644\u0647\u0650 \ufdfa : \u0625\u0650\u0630\u064e\u0627 \u062f\u064e\u0639\u064e\u0627 \u0627\u0644\u0631\u0651\u064e\u062c\u064f\u0644\u064f \u0627\u0645\u0631\u064e\u0623\u064e\u062a\u064e\u0647\u064f \u0625\u0644\u0649 \u0641\u0650\u0631\u064e\u0627\u0634\u0650\u0647\u0650 \u0641\u0623\u0628\u064e\u062a \u0641\u064e\u0628\u064e\u0627\u062a\u064e \u063a\u064e\u0636\u0628\u064e\u0627\u0646\u064e \u0639\u064e\u0644\u064e\u064a\u0647\u064e\u0627 \u0644\u064e\u0639\u064e\u0646\u064e\u062a\u0647\u064e\u0627 \u0627\u0644\u0645\u064e\u0644\u064e\u0627\u0626\u0650\u0643\u064e\u0629\u064f \u062d\u062a\u0651\u064e\u0649 \u062a\u064f\u0635\u0628\u0650\u062d\u064e - \u0631\u0648\u0627\u0647 \u0627\u0644\u0628\u062e\u0627\u0631\u064a",B.aGu)
B.aKh=s(["\u0644\u0627 \u064a\u064e\u0641\u0639\u064e\u0644\u064f \u0627\u0644\u0639\u0628\u062f\u064f \u0627\u0644\u0645\u0633\u0644\u0645\u064f \u062d\u064e\u0633\u0646\u0629\u064b \u0623\u0648 \u0645\u064e\u0639\u0631\u0648\u0641\u064b\u0627\u060c \u0625\u0644\u0651\u064e\u0627 \u062c\u0627\u0632\u0627\u0647\u064f \u0627\u0644\u0644\u0647\u064f \u0628\u0647 \u0648\u0644\u0648 \u0643\u0627\u0646 \u064a\u064e\u0633\u064a\u0631\u064b\u0627\u061b \u0642\u0627\u0644 \u062a\u064e\u0639\u0627\u0644\u0649: \ufd3f\u0641\u064e\u0645\u064e\u0646\u064e \u064a\u064e\u0639\u0645\u064e\u0644 \u0645\u0650\u062b\u0642\u064e\u0627\u0644\u064e \u0630\u064e\u0631\u0651\u064e\u0629\u064d \u062e\u064e\u064a\u0631\u064b\u0627 \u064a\u064e\u0631\u064e\u0647\u064f\ufd3e - \u0633\u0648\u0631\u0629 \u0627\u0644\u0632\u0644\u0632\u0644\u0629.","\u0648\u0641\u064a \u0647\u0630\u0627 \u0627\u0644\u062d\u062f\u064a\u062b\u0650 \u064a\u064f\u062e\u0627\u0637\u0650\u0628\u064f \u0627\u0644\u0646\u0651\u064e\u0628\u064a\u0651\u064f \ufdfa \u0627\u0644\u0646\u0651\u0650\u0633\u0627\u0621\u064e \u0648\u064a\u064e\u0623\u0645\u064f\u0631\u064f\u0647\u064f\u0646\u0651\u064e \u0623\u0644\u0651\u064e\u0627 \u064a\u064e\u062d\u062a\u0642\u0650\u0631\u0646\u064e \u0623\u064a\u0651\u064e \u0634\u064e\u064a\u0621\u064d \u062a\u064f\u0647\u062f\u0650\u064a\u0647 \u0625\u062d\u062f\u0627\u0647\u064f\u0646\u0651\u064e \u0644\u062c\u0627\u0631\u062a\u0650\u0647\u0627\u060c \u0648\u0644\u0648 \u0643\u0627\u0646 \u0627\u0644\u0645\u064f\u0647\u062f\u0649 \u0641\u0650\u0631\u0633\u0650\u0646\u064e \u0634\u0627\u0629\u064d\u060c \u0648\u0647\u0648 \u0638\u0650\u0644\u0641\u064f \u0627\u0644\u0634\u0651\u064e\u0627\u0629\u0650 \u0643\u0627\u0644\u062d\u0627\u0641\u0631\u0650 \u0645\u0650\u0646 \u0627\u0644\u0641\u0631\u064e\u0633\u0650\u060c \u0648\u0642\u064a\u0644: \u0647\u0648 \u0639\u064e\u0638\u0645\u064c \u0642\u064e\u0644\u064a\u0644\u064f \u0627\u0644\u0644\u0651\u064e\u062d\u0645\u0650\u060c \u0648\u0627\u0644\u0645\u0642\u0635\u0648\u062f\u064f: \u0627\u0644\u0645\u0628\u0627\u0644\u064e\u063a\u0629\u064f \u0641\u064a \u0627\u0644\u062d\u062b\u0651\u0650 \u0639\u0644\u0649 \u0627\u0644\u0625\u0647\u062f\u0627\u0621\u0650 \u0648\u0644\u0648 \u0643\u0627\u0646 \u0634\u064e\u064a\u0626\u064b\u0627 \u064a\u064e\u0633\u064a\u0631\u064b\u0627\u060c \u0648\u0645\u0639\u0646\u0627\u0647: \u0644\u0627 \u062a\u064e\u0645\u062a\u0646\u0650\u0639 \u062c\u0627\u0631\u0629\u064c \u0645\u0650\u0646 \u0627\u0644\u0635\u0651\u064e\u062f\u064e\u0642\u0629\u0650 \u0648\u0627\u0644\u0647\u064e\u062f\u064e\u064a\u0651\u064e\u0629\u0650 \u0644\u0650\u062c\u0627\u0631\u062a\u0650\u0647\u0627\u061b \u0644\u0627\u0633\u062a\u0642\u0644\u0627\u0644\u0650\u0647\u0627 \u0648\u0627\u062d\u062a\u0642\u0627\u0631\u0650\u0647\u0627 \u0627\u0644\u0645\u0648\u062c\u0648\u062f\u064e \u0639\u0646\u062f\u0647\u0627\u060c \u0628\u0644 \u064a\u064e\u0646\u0628\u063a\u064a \u0623\u0646 \u062a\u064e\u062c\u0648\u062f\u064e \u0628\u0645\u0627 \u062a\u064e\u064a\u0633\u0651\u064e\u0631\u064e \u0648\u0644\u0648 \u0643\u0627\u0646 \u0642\u0644\u064a\u0644\u064b\u0627\u060c \u0643\u0641\u0650\u0631\u0633\u0650\u0646\u0650 \u0634\u0627\u0629\u064d\u060c \u0648\u0647\u0648 \u062e\u064e\u064a\u0631\u064c \u0645\u0650\u0646 \u0627\u0644\u0639\u062f\u064e\u0645\u0650\u060c \u0648\u0625\u0630\u0627 \u062a\u064e\u0648\u0627\u0635\u064e\u0644\u064e \u0627\u0644\u0642\u0644\u064a\u0644\u064f \u0635\u0627\u0631 \u0643\u064e\u062b\u064a\u0631\u064b\u0627\u061b \u0641\u0625\u0646\u0651\u064e \u0627\u0644\u062a\u0651\u064e\u0647\u0627\u062f\u0650\u064a\u064e \u0648\u0644\u0648 \u0628\u0627\u0644\u0642\u0644\u064a\u0644\u0650 \u062c\u0627\u0644\u0628\u064c \u0644\u0644\u0645\u064e\u062d\u0628\u0651\u064e\u0629\u0650 \u0648\u0627\u0644\u0645\u0648\u062f\u0651\u064e\u0629\u0650\u060c \u0648\u0645\u064f\u0630\u0647\u0650\u0628\u064c \u0644\u0644\u0636\u0651\u064e\u063a\u0627\u0626\u0646\u0650\u060c \u0648\u0623\u064a\u0636\u064b\u0627 \u0641\u0625\u0646\u0651\u064e \u0627\u0644\u0647\u064e\u062f\u064a\u0651\u064e\u0629\u064e \u0625\u0630\u0627 \u0643\u0627\u0646\u062a \u064a\u064e\u0633\u064a\u0631\u0629\u064b \u0641\u0647\u064a \u0623\u062f\u0644\u0651\u064f \u0639\u0644\u0649 \u0627\u0644\u0645\u0648\u062f\u0651\u064e\u0629\u0650\u060c \u0648\u0623\u062e\u0641\u0651\u064f \u0641\u064a \u0627\u0644\u0645\u0624\u0646\u0629\u0650 \u0628\u0627\u0644\u0646\u0651\u0650\u0633\u0628\u0629\u0650 \u0644\u0644\u0645\u064f\u0647\u062f\u064a\u060c \u0648\u0623\u0633\u0647\u064e\u0644\u064f \u0639\u0644\u0649 \u0627\u0644\u0645\u064f\u0647\u062f\u0649\u061b \u0644\u0639\u062f\u064e\u0645\u0650 \u0627\u0644\u062a\u0651\u064e\u0643\u0644\u064a\u0641\u0650.","\u0648\u062e\u064e\u0635\u0651\u064e \u0627\u0644\u0646\u0651\u064e\u0628\u064a\u0651\u064f \ufdfa \u0627\u0644\u0646\u0651\u0650\u0633\u0627\u0621\u064e \u0628\u0627\u0644\u062e\u0650\u0637\u0627\u0628\u0650\u061b \u0644\u0623\u0646\u0651\u064e\u0647\u0646\u0651\u064e \u064a\u064e\u063a\u0644\u0650\u0628\u064f \u0639\u0644\u064a\u0647\u0646\u0651\u064e \u0627\u0633\u062a\u0635\u063a\u0627\u0631\u064f \u0627\u0644\u0634\u0651\u064e\u064a\u0621\u0650 \u0627\u0644\u064a\u064e\u0633\u064a\u0631\u0650\u060c \u0648\u0627\u0644\u062a\u0651\u064e\u0628\u0627\u0647\u064a \u0628\u0627\u0644\u0643\u062b\u0631\u0629\u0650\u060c \u0648\u0623\u0634\u0628\u0627\u0647\u064f \u0630\u0644\u0643.","\u0648\u0641\u064a \u0627\u0644\u062d\u062f\u064a\u062b\u0650: \u0627\u0644\u062a\u0651\u064e\u0631\u063a\u064a\u0628\u064f \u0641\u064a \u0627\u0644\u0647\u064e\u062f\u0627\u064a\u0627 \u0625\u0644\u0649 \u0627\u0644\u062c\u0650\u064a\u0631\u0627\u0646\u0650."],t.s)
B.arS=new A.h("muminatHadiths_32","\u0644\u0627 \u062a\u062d\u0642\u0650\u0631\u0646\u064e\u0651 \u062c\u0627\u0631\u0629\u064c \u0644\u0650\u062c\u0627\u0631\u062a\u0650\u0647\u0627","\u0639\u064e\u0646 \u0623\u0628\u064a \u0647\u064f\u0631\u064a\u0631\u064e\u0629 \u0631\u064e\u0636\u064a\u064e \u0627\u0644\u0644\u0647\u064f \u0639\u0646\u0647\u060c \u0639\u0646 \u0627\u0644\u0646\u0628\u064a\u0651\u0650 \ufdfa \u0642\u0627\u0644\u064e: \u064a\u0627 \u0646\u0650\u0633\u0627\u0621\u064e \u0627\u0644\u0645\u064f\u0633\u0644\u0650\u0645\u0627\u062a\u0650\u060c \u0644\u0627 \u062a\u064e\u062d\u0642\u0650\u0631\u064e\u0646\u0651\u064e \u062c\u0627\u0631\u064e\u0629\u064c \u0644\u0650\u062c\u0627\u0631\u064e\u062a\u0650\u0647\u0627\u060c \u0648\u0644\u0648 \u0641\u0650\u0631\u0633\u0650\u0646\u064e \u0634\u0627\u0629\u064d - \u0631\u0648\u0627\u0647 \u0627\u0644\u0628\u062e\u0627\u0631\u064a",B.aKh)
B.aJB=s(["\u0627\u0644\u062c\u0650\u0647\u0627\u062f\u064f \u0630\u0650\u0631\u0648\u0629\u064f \u0633\u064e\u0646\u0627\u0645\u0650 \u0627\u0644\u0625\u0633\u0644\u0627\u0645\u0650\u060c \u0648\u064e\u0647\u0648\u064e \u064a\u064e\u062d\u062a\u0627\u062c\u064f \u0625\u0644\u0649 \u0642\u064f\u062f\u064f\u0631\u0627\u062a\u064d \u0645\u064f\u0639\u064a\u0651\u064e\u0646\u0629\u064d\u060c \u0648\u0642\u062f \u0631\u064e\u0641\u064e\u0639\u064e \u0627\u0644\u0644\u0647\u064f \u0633\u064f\u0628\u062d\u0627\u0646\u064e\u0647 \u0648\u062a\u0639\u0627\u0644\u064e\u0649 \u0627\u0644\u062d\u064e\u0631\u064e\u062c\u064e \u0639\u0646\u0650 \u0627\u0644\u0642\u0650\u064a\u0627\u0645\u0650 \u0628\u0647 \u0644\u0650\u0628\u064e\u0639\u0636\u0650 \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u0650\u060c \u0648\u0645\u0650\u0646 \u0647\u0624\u0644\u0627\u0621\u0650 \u0627\u0644\u0646\u0651\u0650\u0633\u0627\u0621\u064f.","\u0648\u0641\u064a \u0647\u0630\u0627 \u0627\u0644\u062d\u064e\u062f\u064a\u062b\u0650 \u062a\u064f\u062e\u0628\u0650\u0631\u064f \u0623\u064f\u0645\u0651\u064f \u0627\u0644\u0645\u064f\u0624\u0645\u0650\u0646\u064a\u0646\u064e \u0639\u064e\u0627\u0626\u0650\u0634\u0629\u064f \u0631\u064e\u0636\u064a\u064e \u0627\u0644\u0644\u0647\u064f \u0639\u0646\u0647\u0627 \u0623\u0646\u0651\u064e\u0647\u0627 \u0627\u0633\u062a\u064e\u0623\u0630\u064e\u0646\u064e\u062a\u0650 \u0627\u0644\u0646\u0651\u064e\u0628\u064a\u0651\u064e \ufdfa \u0641\u064a \u0627\u0644\u062e\u064f\u0631\u0648\u062c\u0650 \u0645\u0639\u0647 \u0625\u0644\u0649 \u0627\u0644\u062c\u0650\u0647\u0627\u062f\u0650 \u0648\u0627\u0644\u063a\u064e\u0632\u0648\u0650 \u0641\u064a \u0633\u064e\u0628\u064a\u0644\u0650 \u0627\u0644\u0644\u0647\u0650\u061b \u0644\u0650\u0645\u064e\u0627 \u0641\u064a \u0627\u0644\u062c\u0650\u0647\u0627\u062f\u0650 \u0645\u0650\u0646 \u0641\u064e\u0636\u0644\u064d \u0639\u064e\u0638\u064a\u0645\u064d\u060c \u0648\u0645\u064e\u0646\u0627\u0632\u0650\u0644\u064e \u0631\u064e\u0641\u064a\u0639\u0629\u064d \u0639\u0650\u0646\u062f\u064e \u0627\u0644\u0645\u064e\u0648\u0644\u0649 \u0633\u064f\u0628\u062d\u0627\u0646\u064e\u0647\u064f \u0648\u062a\u064e\u0639\u0627\u0644\u0649\u060c \u0641\u0642\u0627\u0644 \u0644\u0647\u0627 \u0627\u0644\u0646\u0651\u064e\u0628\u064a\u0651\u064f \ufdfa: \xab\u062c\u0650\u0647\u0627\u062f\u064f\u0643\u064f\u0646\u0651\u064e \u0627\u0644\u062d\u064e\u062c\u0651\u064f\xbb\u060c \u0623\u064a\u0650: \u0627\u0644\u0630\u064a \u0639\u0644\u064a\u0643\u064f\u0646\u0651\u064e \u0628\u064e\u0630\u0644\u064f \u0627\u0644\u062c\u064e\u0647\u062f\u0650 \u0641\u064a\u0647 \u0647\u0648 \u0627\u0644\u062d\u064e\u062c\u0651\u064f\u060c \u0648\u0644\u064a\u0633 \u0639\u0644\u064a\u0643\u064f\u0646\u0651\u064e \u0627\u0644\u062d\u064f\u0631\u0648\u0628\u064f \u0648\u0646\u064e\u062d\u0648\u064f\u0647\u0627\u061b \u0641\u0627\u0644\u0645\u0631\u0623\u0629\u064f \u0636\u064e\u0639\u064a\u0641\u0629\u064c \u0639\u0644\u0649 \u0645\u064f\u062c\u0627\u0628\u064e\u0647\u0629\u0650 \u0627\u0644\u0639\u064e\u062f\u064f\u0648\u0651\u0650 \u0648\u064e\u062c\u0647\u064b\u0627 \u0644\u0650\u0648\u064e\u062c\u0647\u064d\u060c \u0641\u0647\u0630\u0627 \u0641\u064e\u0648\u0642\u064e \u0645\u0627 \u062a\u064e\u0633\u062a\u064e\u0637\u064a\u0639\u064f\u060c \u0648\u0645\u0650\u062b\u0644\u064f \u0627\u0644\u062d\u064e\u062c\u0651\u0650 \u0627\u0644\u0639\u064f\u0645\u0631\u0629\u064f \u0644\u0650\u0644\u0645\u0631\u0623\u0629\u0650\u060c \u0643\u0645\u0627 \u0641\u064a \u0631\u0650\u0648\u0627\u064a\u0629\u0650 \u0627\u0628\u0646\u0650 \u0645\u0627\u062c\u064e\u0647: \xab\u0639\u0644\u064a\u0647\u0650\u0646\u0651\u064e \u062c\u0650\u0647\u0627\u062f\u064c \u0644\u0627 \u0642\u0650\u062a\u0627\u0644\u064e \u0641\u064a\u0647: \u0627\u0644\u062d\u064e\u062c\u0651\u064f \u0648\u0627\u0644\u0639\u064f\u0645\u0631\u0629\u064f\xbb.","\u0641\u0627\u0644\u0646\u0651\u0650\u0633\u0627\u0621\u064f \u064a\u064f\u0624\u062c\u064e\u0631\u0646\u064e \u0628\u0623\u062f\u0627\u0621\u0650 \u0627\u0644\u062d\u064e\u062c\u0651\u0650 \u0648\u0627\u0644\u0639\u064f\u0645\u0631\u0629\u0650 \u0628\u0645\u0650\u062b\u0644\u0650 \u0645\u0627 \u064a\u064f\u0624\u062c\u064e\u0631\u064f \u0628\u0647 \u0645\u064e\u0646 \u064a\u064e\u062e\u0631\u064f\u062c\u064f \u0644\u0650\u0644\u063a\u064e\u0632\u0648\u0650 \u0648\u0627\u0644\u062c\u0650\u0647\u0627\u062f\u0650 \u0641\u064a \u0633\u064e\u0628\u064a\u0644\u0650 \u0627\u0644\u0644\u0647\u0650 \u0639\u0632\u0651\u064e \u0648\u062c\u0644\u0651\u064e\u060c \u0648\u0642\u064a\u0644\u064e: \u0627\u0644\u0645\u064f\u0631\u0627\u062f\u064f \u0623\u0646\u0651\u064e \u0627\u0644\u062c\u0650\u0647\u0627\u062f\u064e \u0627\u0644\u0645\u064e\u0641\u0631\u0648\u0636\u064e \u0639\u0644\u064a\u0647\u0650\u0646\u0651\u064e \u0647\u0648 \u0623\u062f\u0627\u0621\u064f \u0627\u0644\u062d\u064e\u062c\u0651\u0650 \u0648\u0627\u0644\u0639\u064f\u0645\u0631\u0629\u0650 \u0628\u0645\u0650\u062b\u0644\u0650 \u0627\u0644\u062c\u0650\u0647\u0627\u062f\u0650 \u0641\u064a \u0633\u064e\u0628\u064a\u0644\u0650 \u0627\u0644\u0644\u0647\u0650 \u0639\u0632\u0651\u064e \u0648\u062c\u0644\u0651\u064e \u0627\u0644\u0645\u064e\u0641\u0631\u0648\u0636\u0650 \u0639\u0644\u0649 \u0643\u064f\u0644\u0651\u0650 \u0645\u064f\u0624\u0645\u0650\u0646\u064d \u0642\u0627\u062f\u0650\u0631\u064d.","\u0648\u0633\u064f\u0645\u0651\u0650\u064a\u064e \u0627\u0644\u062d\u064e\u062c\u0651\u064f \u062c\u0650\u0647\u0627\u062f\u064b\u0627\u060c \u0625\u0645\u0651\u064e\u0627 \u0645\u0650\u0646 \u0628\u0627\u0628\u0650 \u0627\u0644\u062a\u0651\u064e\u063a\u0644\u064a\u0628\u0650\u060c \u0648\u0625\u0645\u0651\u064e\u0627 \u0639\u0644\u0649 \u0627\u0644\u062d\u064e\u0642\u064a\u0642\u0629\u0650\u060c \u0648\u0627\u0644\u0645\u064f\u0631\u0627\u062f\u064f \u062c\u0650\u0647\u0627\u062f\u064f \u0627\u0644\u0646\u0651\u064e\u0641\u0633\u0650\u061b \u0644\u0650\u0645\u064e\u0627 \u0641\u064a\u0647 \u0645\u0650\u0646 \u0625\u062f\u062e\u0627\u0644\u0650 \u0627\u0644\u0645\u064e\u0634\u064e\u0642\u0651\u064e\u0629\u0650 \u0639\u0644\u0649 \u0627\u0644\u0628\u064e\u062f\u064e\u0646\u0650 \u0648\u0627\u0644\u0645\u0627\u0644\u0650. \u0648\u064a\u064f\u0634\u0631\u064e\u0639\u064f \u062e\u064f\u0631\u0648\u062c\u064f \u0627\u0644\u0645\u0631\u0623\u0629\u0650 \u0645\u0639 \u0627\u0644\u062c\u064e\u064a\u0634\u0650\u061b \u0644\u0650\u062a\u064f\u0639\u064a\u0646\u064e \u0627\u0644\u0645\u064f\u0642\u0627\u062a\u0650\u0644\u064a\u0646\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0631\u0651\u0650\u062c\u0627\u0644\u0650\u060c \u0628\u0645\u0627 \u064a\u064e\u062a\u0648\u0627\u0641\u064e\u0642\u064f \u0645\u0639 \u0642\u064f\u062f\u064f\u0631\u0627\u062a\u0650\u0647\u0627\u060c \u0643\u0627\u0644\u062a\u0651\u064e\u0637\u0628\u064a\u0628\u0650 \u0648\u0633\u064f\u0642\u064a\u0627 \u0627\u0644\u0645\u0627\u0621\u0650 \u0648\u0646\u064e\u062d\u0648\u0650\u0647\u0645\u0627.","\u0648\u0641\u064a \u0627\u0644\u062d\u064e\u062f\u064a\u062b\u0650: \u0641\u064e\u0636\u0644\u064f \u0627\u0644\u062d\u064e\u062c\u0651\u0650 \u0648\u0639\u064e\u0638\u064a\u0645\u064f \u0623\u062c\u0631\u0650 \u0627\u0644\u0644\u0647\u0650 \u0639\u064e\u0632\u0651\u064e \u0648\u062c\u064e\u0644\u0651\u064e \u0639\u0644\u0649 \u0645\u064e\u0646 \u0642\u0627\u0645\u064e \u0628\u0647 \u0641\u064e\u0631\u0636\u064b\u0627 \u0623\u0648 \u0646\u064e\u0641\u0644\u064b\u0627\u060c \u0648\u0641\u064a\u0647: \u0639\u064e\u0638\u064a\u0645\u064f \u0641\u0636\u0644\u0650 \u0627\u0644\u0644\u0647\u0650 \u0639\u0644\u0649 \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u0650\u061b \u0641\u0645\u0627 \u0623\u063a\u0644\u064e\u0642\u064e \u0628\u0627\u0628\u064b\u0627 \u0625\u0644\u0651\u064e\u0627 \u0641\u064e\u062a\u064e\u062d\u064e \u063a\u064e\u064a\u0631\u064e\u0647."],t.s)
B.aof=new A.h("muminatHadiths_33","\u062c\u0650\u0647\u0627\u062f\u064f\u0643\u064f\u0646\u064e\u0651 \u0627\u0644\u062d\u064e\u062c","\u0639\u064e\u0646 \u0623\u0645\u0651\u0650 \u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646 \u0639\u0627\u0626\u0634\u0629\u064e \u0631\u064e\u0636\u064a\u064e \u0627\u0644\u0644\u0647\u064f \u0639\u0646\u0647\u0627 \u0642\u0627\u0644\u064e\u062a: \u0627\u0633\u062a\u064e\u0623\u0630\u064e\u0646\u062a\u064f \u0627\u0644\u0646\u0628\u064a\u0651\u064e \ufdfa \u0641\u064a \u0627\u0644\u062c\u0650\u0647\u064e\u0627\u062f\u0650\u060c \u0641\u064e\u0642\u0627\u0644\u064e: \u062c\u0650\u0647\u064e\u0627\u062f\u064f\u0643\u064f\u0646\u0651\u064e \u0627\u0644\u062d\u064e\u062c\u0651\u064f - \u0631\u0648\u0627\u0647 \u0627\u0644\u0628\u062e\u0627\u0631\u064a",B.aJB)
B.aR7=s(["\u0644\u0645 \u064a\u064e\u0643\u062a\u064f\u0628\u0650 \u0627\u0644\u0644\u0647\u064f \u062a\u0639\u0627\u0644\u064e\u0649 \u0639\u0644\u0649 \u0627\u0644\u0646\u0651\u0650\u0633\u0627\u0621\u0650 \u0627\u0644\u0642\u0650\u062a\u0627\u0644\u064e\u060c \u0648\u0625\u0646\u0651\u064e\u0645\u0627 \u0647\u0648 \u0645\u0650\u0646\u064e \u0627\u0644\u0623\u0639\u0645\u0627\u0644\u0650 \u0627\u0644\u062e\u0627\u0635\u0651\u064e\u0629\u0650 \u0628\u0627\u0644\u0631\u0651\u0650\u062c\u0627\u0644\u0650\u060c \u0648\u0644\u0643\u0650\u0646\u0651\u064e \u0627\u0644\u0646\u0651\u0650\u0633\u0627\u0621\u064e \u0644\u0647\u064f\u0646\u0651\u064e \u0623\u0646 \u064a\u064f\u0634\u0627\u0631\u0650\u0643\u0646\u064e \u0641\u064a \u0627\u0644\u063a\u064e\u0632\u0648\u0650 \u0648\u0627\u0644\u062c\u0650\u0647\u0627\u062f\u0650 \u0645\u0639 \u0627\u0644\u0631\u0651\u0650\u062c\u0627\u0644\u0650 \u0648\u064a\u064e\u0642\u064f\u0645\u0646\u064e \u0628\u0627\u0644\u0623\u0639\u0645\u0627\u0644\u0650 \u0627\u0644\u062a\u064a \u062a\u064f\u0646\u0627\u0633\u0650\u0628\u064f \u0637\u064e\u0628\u064a\u0639\u062a\u064e\u0647\u064f\u0646\u0651\u064e \u0627\u0644\u062a\u064a \u062c\u064e\u0628\u064e\u0644\u064e\u0647\u064f\u0646\u0651\u064e \u0627\u0644\u0644\u0647\u064f \u0639\u0644\u064a\u0647\u0627.","\u0648\u0641\u064a \u0647\u0630\u0627 \u0627\u0644\u062d\u064e\u062f\u064a\u062b\u0650 \u062a\u064f\u062e\u0628\u0650\u0631\u064f \u0627\u0644\u0631\u0651\u064f\u0628\u064e\u064a\u0651\u0650\u0639\u064f \u0628\u0650\u0646\u062a\u064f \u0645\u064f\u0639\u064e\u0648\u0651\u0650\u0630\u0650 \u0628\u0646\u0650 \u0639\u064e\u0641\u0631\u0627\u0621\u064e \u0631\u064e\u0636\u064a\u064e \u0627\u0644\u0644\u0647\u064f \u0639\u0646\u0647\u0645\u0627 \u0623\u0646\u0651\u064e\u0647\u0627 \u0648\u0628\u064e\u0639\u0636\u064e \u0627\u0644\u0646\u0651\u0650\u0633\u0627\u0621\u0650 \u0641\u064a \u0639\u064e\u0647\u062f\u0650 \u0631\u064e\u0633\u0648\u0644\u0650 \u0627\u0644\u0644\u0647\u0650 \ufdfa \u0643\u064f\u0646\u0651\u064e \u064a\u064e\u062e\u0631\u064f\u062c\u0646\u064e \u0645\u0639\u0647 \ufdfa \u0641\u064a \u0627\u0644\u063a\u064e\u0632\u0648\u0650\u061b \u064a\u064e\u0646\u0642\u064f\u0644\u0646\u064e \u0627\u0644\u0645\u0627\u0621\u064e\u060c \u0648\u064a\u064e\u0633\u0642\u064a\u0646\u064e \u0627\u0644\u0645\u064f\u062d\u0627\u0631\u0650\u0628\u064a\u0646\u064e\u060c \u0648\u064a\u064f\u062f\u0627\u0648\u064a\u0646\u064e \u0627\u0644\u062c\u064e\u0631\u062d\u0649 \u0645\u0646\u0647\u0645\u060c \u0648\u064a\u064e\u0642\u064f\u0645\u0646\u064e \u0628\u0631\u064e\u062f\u0651\u0650 \u0627\u0644\u0642\u064e\u062a\u0644\u0649 \u0645\u0650\u0646 \u0623\u0631\u0636\u0650 \u0627\u0644\u0645\u064e\u0639\u0631\u064e\u0643\u0629\u0650 \u0625\u0644\u0649 \u0645\u064e\u0648\u0627\u0636\u0650\u0639\u0650 \u0642\u064f\u0628\u0648\u0631\u0650\u0647\u0645 \u0641\u064a \u0627\u0644\u0645\u064e\u062f\u064a\u0646\u0629\u0650 \u0627\u0644\u0645\u064f\u0646\u064e\u0648\u0651\u064e\u0631\u0629\u0650."],t.s)
