B.as5=new A.h("imanHadiths_3","\u062b\u0644\u0627\u062b \u0645\u0646 \u0643\u064f\u0646\u064e\u0651 \u0641\u064a\u0647 \u0648\u062c\u064e\u062f \u062d\u0644\u0627\u0648\u0629 \u0627\u0644\u0625\u064a\u0645\u0627\u0646","\u0639\u064e\u0646 \u0623\u0646\u0633 \u0628\u0646 \u0645\u064e\u0627\u0644\u0650\u0643 \u0631\u064e\u0636\u064a\u064e \u0627\u0644\u0644\u0647\u064f \u0639\u0646\u0647\u060c \u0639\u064e\u0646\u0650 \u0627\u0644\u0646\u0628\u064a\u0651\u0650 \ufdfa \u0642\u0627\u0644\u064e: \u062b\u064e\u0644\u0627\u062b\u064c \u0645\u064e\u0646 \u0643\u064f\u0646\u0651\u064e \u0641\u064a\u0647 \u0648\u062c\u064e\u062f\u064e \u062d\u064e\u0644\u0627\u0648\u0629\u064e \u0627\u0644\u0625\u064a\u0645\u0627\u0646\u0650: \u0623\u0646 \u064a\u064e\u0643\u0648\u0646\u064e \u0627\u0644\u0644\u0647\u064f \u0648\u0631\u064e\u0633\u0648\u0644\u064f\u0647 \u0623\u062d\u064e\u0628\u0651\u064e \u0625\u0644\u064a\u0647 \u0645\u0645\u0651\u064e\u0627 \u0633\u0650\u0648\u0627\u0647\u0645\u0627\u060c \u0648\u0623\u0646 \u064a\u064f\u062d\u0650\u0628\u0651\u064e \u0627\u0644\u0645\u064e\u0631\u0621\u064e \u0644\u0627 \u064a\u064f\u062d\u0650\u0628\u0651\u064f\u0647 \u0625\u0644\u0651\u064e\u0627 \u0644\u0644\u0651\u064e\u0647\u0650\u060c \u0648\u0623\u0646 \u064a\u064e\u0643\u0631\u064e\u0647\u064e \u0623\u0646 \u064a\u064e\u0639\u0648\u062f\u064e \u0641\u064a \u0627\u0644\u0643\u064f\u0641\u0631\u0650 \u0643\u0645\u0627 \u064a\u064e\u0643\u0631\u064e\u0647\u064f \u0623\u0646 \u064a\u064f\u0642\u0630\u064e\u0641\u064e \u0641\u064a \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u0650 - \u0631\u0648\u0627\u0647 \u0627\u0644\u0628\u062e\u0627\u0631\u064a",B.aP8)
B.aAR=s([u.dZ,"\u0648\u0642\u062f \u0623\u0633\u0651\u064e\u0633 \ufdfa \u0641\u064a \u0623\u0648\u0651\u064e\u0644\u0650 \u0627\u0644\u062d\u062f\u064a\u062b\u0650 \u0647\u0630\u0627 \u0627\u0644\u0623\u0635\u0644\u064e \u0627\u0644\u0643\u0628\u064a\u0631\u064e\u060c \u0641\u0642\u0627\u0644: \xab\u0625\u0646\u0651\u064e \u0627\u0644\u062f\u0651\u0650\u064a\u0646\u064e \u064a\u064f\u0633\u0631\u064c\xbb\u060c \u0641\u0647\u0648 \u0645\u064f\u064a\u0633\u0651\u064e\u0631\u064c \u0645\u064f\u0633\u0647\u0651\u064e\u0644\u064c \u0641\u064a \u0639\u064e\u0642\u0627\u0626\u062f\u0650\u0647 \u0648\u0623\u062e\u0644\u0627\u0642\u0650\u0647\u060c \u0648\u0641\u064a \u0623\u0641\u0639\u0627\u0644\u0650\u0647 \u0648\u062a\u064f\u0631\u0648\u0643\u0650\u0647.","\u062b\u0645\u0651\u064e \u0648\u0635\u0651\u064e\u0649 \u0628\u0627\u0644\u062a\u0651\u064e\u0633\u062f\u064a\u062f\u0650 \u0648\u0627\u0644\u0645\u0642\u0627\u0631\u064e\u0628\u0629\u0650\u060c \u0648\u062a\u064e\u0642\u0648\u064a\u0629\u0650 \u0627\u0644\u0646\u0651\u064f\u0641\u0648\u0633\u0650 \u0628\u0627\u0644\u0628\u0650\u0634\u0627\u0631\u0629\u0650 \u0628\u0627\u0644\u062e\u064a\u0631\u0650\u060c \u0648\u0639\u062f\u064e\u0645\u0650 \u0627\u0644\u064a\u0623\u0633\u0650\u060c \u0648\u0627\u0644\u062a\u0651\u064e\u0633\u062f\u064a\u062f\u064f: \u0647\u0648 \u0627\u0644\u0639\u0645\u0644\u064f \u0628\u0627\u0644\u0642\u0635\u062f\u0650\u060c \u0648\u0627\u0644\u062a\u0651\u064e\u0648\u0633\u0651\u064f\u0637\u064f \u0641\u064a \u0627\u0644\u0639\u0650\u0628\u0627\u062f\u0629\u0650\u060c \u0641\u0644\u0627 \u064a\u064f\u0642\u0635\u0651\u0650\u0631\u064f \u0641\u064a\u0645\u0627 \u0623\u064f\u0645\u0650\u0631\u064e \u0628\u0647\u060c \u0648\u0644\u0627 \u064a\u064e\u062a\u062d\u0645\u0651\u064e\u0644\u064f \u0645\u0646\u0647\u0627 \u0645\u0627 \u0644\u0627 \u064a\u064f\u0637\u0650\u064a\u0642\u064f\u0647\u060c \u0645\u0650\u0646 \u063a\u064a\u0631\u0650 \u0625\u0641\u0631\u0627\u0637\u064d \u0648\u0644\u0627 \u062a\u064e\u0641\u0631\u064a\u0637\u064d.","\u0648\u0642\u0648\u0644\u064f\u0647: \xab\u0648\u0642\u0627\u0631\u0650\u0628\u0648\u0627\xbb\u060c \u0623\u064a: \u0625\u0646 \u0644\u0645 \u062a\u064e\u0633\u062a\u0637\u064a\u0639\u0648\u0627 \u0627\u0644\u0623\u062e\u0630\u064e \u0628\u0627\u0644\u0623\u0643\u0645\u0644\u0650\u060c \u0641\u0627\u0639\u0645\u064e\u0644\u0648\u0627 \u0628\u0645\u0627 \u064a\u064e\u0642\u0631\u064f\u0628\u064f \u0645\u0646\u0647.","\u0648\u0642\u0648\u0644\u064f\u0647: \xab\u0648\u0623\u0628\u0634\u0650\u0631\u0648\u0627\xbb\u060c \u0623\u064a: \u0628\u0627\u0644\u062b\u0651\u064e\u0648\u0627\u0628\u0650 \u0639\u0644\u0649 \u0627\u0644\u0639\u0645\u0644\u0650 \u0648\u0625\u0646 \u0642\u064e\u0644\u0651\u064e.","\u062b\u0645\u0651\u064e \u0623\u0631\u0634\u064e\u062f\u064e \u0627\u0644\u0646\u0628\u064a\u0651\u064f \ufdfa \u0625\u0644\u0649 \u0645\u0627 \u064a\u064f\u0633\u0627\u0639\u0650\u062f\u064f \u0639\u0644\u0649 \u0627\u0644\u0633\u0651\u064e\u062f\u0627\u062f\u0650 \u0648\u0627\u0644\u0645\u0642\u0627\u0631\u064e\u0628\u0629\u0650\u060c \u0641\u0642\u0627\u0644: \xab\u0648\u0627\u0633\u062a\u0639\u0650\u064a\u0646\u0648\u0627 \u0628\u0627\u0644\u063a\u064e\u062f\u0648\u0629\u0650 \u0648\u0627\u0644\u0631\u0651\u064e\u0648\u062d\u0629\u0650\u060c \u0648\u0634\u064e\u064a\u0621\u064d \u0645\u0650\u0646 \u0627\u0644\u062f\u0651\u064f\u0644\u062c\u0629\u0650\xbb\u061b \u0641\u0647\u0630\u0647 \u0627\u0644\u0623\u0648\u0642\u0627\u062a\u064f \u0627\u0644\u062b\u0651\u064e\u0644\u0627\u062b\u0629\u064f \u0623\u0648\u0642\u0627\u062a\u064f \u0627\u0644\u0639\u0645\u0644\u0650 \u0648\u0627\u0644\u0633\u0651\u064e\u064a\u0631\u0650 \u0625\u0644\u0649 \u0627\u0644\u0644\u0647\u0650\u061b \u0641\u0627\u0644\u063a\u064e\u062f\u0648\u0629\u064f: \u0623\u0648\u0651\u064e\u0644\u064f \u0627\u0644\u0646\u0651\u064e\u0647\u0627\u0631\u0650\u060c \u0648\u0627\u0644\u0631\u0651\u064e\u0648\u062d\u0629\u064f: \u0622\u062e\u0650\u0631\u064f\u0647\u060c \u0648\u0627\u0644\u062f\u0651\u064f\u0644\u062c\u0629\u064f: \u0633\u064e\u064a\u0631\u064f \u0622\u062e\u0631\u0650 \u0627\u0644\u0644\u0651\u064e\u064a\u0644\u060c \u0648\u0633\u064e\u064a\u0631\u064f \u0622\u062e\u0631\u0650 \u0627\u0644\u0644\u0651\u064e\u064a\u0644 \u0645\u064e\u062d\u0645\u0648\u062f\u064c \u0641\u064a \u0633\u064e\u064a\u0631\u0650 \u0627\u0644\u062f\u0651\u064f\u0646\u064a\u0627 \u0628\u0627\u0644\u0623\u0628\u062f\u0627\u0646\u0650\u060c \u0648\u0641\u064a \u0633\u064e\u064a\u0631\u0650 \u0627\u0644\u0642\u064f\u0644\u0648\u0628\u0650 \u0625\u0644\u0649 \u0627\u0644\u0644\u0647\u0650 \u0628\u0627\u0644\u0623\u0639\u0645\u0627\u0644\u0650.","\u0648\u0642\u0627\u0644: \u0648\u064e\u0634\u064a\u0621\u064d \u0645\u0650\u0646 \u0627\u0644\u062f\u0651\u064f\u0644\u062c\u0629\u0650\u060c \u0648\u0644\u0645 \u064a\u0642\u064f\u0644: \u0648\u0627\u0644\u062f\u0651\u064f\u0644\u062c\u0629\u061b \u062a\u064e\u062e\u0641\u064a\u0641\u064b\u0627\u061b \u0644\u0645\u064e\u0634\u0642\u0651\u064e\u0629\u0650 \u0639\u0645\u064e\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u064a\u0644.",u.dN,u.fa],t.s)
B.arz=new A.h("imanHadiths_4","\u0627\u0644\u062f\u0650\u0651\u064a\u0646 \u064a\u064f\u0633\u0631\u064c","\u0639\u064e\u0646 \u0623\u0628\u064a \u0647\u064f\u0631\u064a\u0631\u064e\u0629 \u0631\u064e\u0636\u064a\u064e \u0627\u0644\u0644\u0647\u064f \u0639\u0646\u0647\u060c \u0639\u0646 \u0627\u0644\u0646\u0628\u064a\u0651\u0650 \ufdfa \u0642\u0627\u0644\u064e: \u0625\u0646\u0651\u064e \u0627\u0644\u062f\u0651\u0650\u064a\u0646\u064e \u064a\u064f\u0633\u0631\u064c\u060c \u0648\u0644\u064e\u0646 \u064a\u064f\u0634\u0627\u062f\u0651\u064e \u0627\u0644\u062f\u0651\u0650\u064a\u0646\u064e \u0623\u062d\u064e\u062f\u064c \u0625\u0644\u0651\u064e\u0627 \u063a\u064e\u0644\u064e\u0628\u064e\u0647\u060c \u0641\u0633\u064e\u062f\u0651\u0650\u062f\u0648\u0627 \u0648\u0642\u0627\u0631\u0650\u0628\u0648\u0627\u060c \u0648\u0623\u0628\u0634\u0650\u0631\u0648\u0627\u060c \u0648\u0627\u0633\u062a\u064e\u0639\u064a\u0646\u0648\u0627 \u0628\u0627\u0644\u063a\u064e\u062f\u0648\u0629\u0650 \u0648\u0627\u0644\u0631\u0651\u064e\u0648\u062d\u0629\u0650 \u0648\u0634\u064a\u0621\u064d \u0645\u0650\u0646\u064e \u0627\u0644\u062f\u0651\u064f\u0644\u062c\u0629\u0650 - \u0631\u0648\u0627\u0647 \u0627\u0644\u0628\u062e\u0627\u0631\u064a",B.aAR)
B.avI=s([u.gc,u.aj,"\u0641\u0642\u0627\u0644 \u0639\u0645\u064e\u0631\u064f \u0631\u064e\u0636\u064a\u064e \u0627\u0644\u0644\u0647\u064f \u0639\u0646\u0647: \u0642\u062f \u0639\u064e\u0631\u064e\u0641\u0646\u0627 \u0630\u0644\u0643 \u0627\u0644\u064a\u0648\u0645\u064e \u0648\u0627\u0644\u0645\u0643\u0627\u0646\u064e \u0627\u0644\u0651\u064e\u0630\u064a \u0646\u0632\u064e\u0644\u064e\u062a \u0641\u064a\u0647 \u0647\u0630\u0647 \u0627\u0644\u0622\u064a\u0629\u064f \u0627\u0644\u0643\u0631\u064a\u0645\u0629\u064f\u060c \u0641\u0644\u0645 \u062a\u064f\u0646\u0628\u0651\u0650\u0647\u0646\u0627 \u0625\u0644\u0649 \u0634\u064e\u064a\u0621\u064d \u0643\u0646\u0651\u064e\u0627 \u0646\u064e\u062c\u0647\u064e\u0644\u064f\u0647\u061b \u0641\u0647\u064a \u0642\u062f \u0646\u0632\u064e\u0644\u064e\u062a \u0639\u0644\u0649 \u0627\u0644\u0646\u0628\u064a\u0651\u0650 \ufdfa \u0648\u0647\u0648 \u0642\u0627\u0626\u0645\u064c \u0628\u0639\u064e\u0631\u064e\u0641\u0629\u064e \u064a\u0648\u0645\u064e \u062c\u064f\u0645\u0639\u0629\u064d\u061b \u0641\u0647\u0648 \u064a\u0648\u0645\u064c \u0627\u062c\u062a\u064e\u0645\u064e\u0639\u064e \u0641\u064a\u0647 \u0639\u0650\u064a\u062f\u0627\u0646\u0650\u061b \u064a\u0648\u0645\u064f \u0639\u064e\u0631\u0641\u0629\u064e\u060c \u0648\u064a\u0648\u0645\u064f \u0627\u0644\u062c\u064f\u0645\u0639\u0629\u0650.","\u0648\u0642\u064e\u0648\u0644\u064f \u0643\u064e\u0639\u0628\u0650 \u0627\u0644\u0623\u062d\u0628\u0627\u0631\u0650: \xab\u0644\u0627\u062a\u0651\u064e\u062e\u064e\u0630\u0646\u0627 \u0630\u0644\u0643 \u0627\u0644\u064a\u0648\u0645\u064e \u0639\u0650\u064a\u062f\u064b\u0627\xbb\u060c \u064a\u064f\u0631\u064a\u062f\u064f: \u0648\u0644\u0645 \u062a\u064e\u062a\u0651\u064e\u062e\u0650\u0630\u0648\u0647 \u0623\u0646\u062a\u064f\u0645\u060c \u064a\u064f\u062d\u0627\u0648\u0650\u0644\u064f \u0646\u0642\u0636\u064e \u0643\u064e\u0648\u0646\u0650 \u0627\u0644\u0622\u064a\u0629\u0650 \u062d\u0642\u0651\u064b\u0627 \u0628\u0625\u0647\u0645\u0627\u0644\u0650 \u0627\u0644\u0645\u0633\u0644\u0650\u0645\u064a\u0646\u064e \u0644\u064a\u0648\u0645\u0650 \u0646\u064f\u0632\u0648\u0644\u0650\u0647\u0627\u060c \u0641\u0628\u064e\u064a\u0651\u064e\u0646\u064e \u0644\u0647 \u0639\u064f\u0645\u064e\u0631\u064f \u0623\u0646\u0651\u064e\u0647\u0645 \u0627\u062d\u062a\u064e\u0641\u064e\u0644\u0648\u0627 \u0641\u064a\u0647 \u0627\u062d\u062a\u0641\u0627\u0644\u064a\u0646\u0650\u060c \u0648\u0627\u062a\u0651\u064e\u062e\u064e\u0630\u0648\u0647 \u0639\u0650\u064a\u062f\u064a\u0646\u0650.","\u0648\u0641\u064a \u0627\u0644\u062d\u062f\u064a\u062b\u0650: \u062f\u064e\u0644\u0627\u0644\u0629\u064c \u0639\u0644\u0649 \u0623\u0646\u0651\u064e \u0627\u0644\u0623\u0639\u064a\u0627\u062f\u064e \u0644\u0627 \u062a\u0643\u0648\u0646\u064f \u0628\u0627\u0644\u0631\u0651\u064e\u0623\u064a\u0650 \u0648\u0627\u0644\u0627\u062e\u062a\u0631\u0627\u0639\u0650\u060c \u0643\u0645\u0627 \u064a\u064e\u0641\u0639\u064e\u0644\u064f\u0647 \u0623\u0647\u0644\u064f \u0627\u0644\u0643\u0650\u062a\u0627\u0628\u064a\u0646\u0650 \u0645\u0650\u0646 \u0642\u064e\u0628\u0644\u0650\u0646\u0627\u060c \u0625\u0646\u0651\u064e\u0645\u0627 \u062a\u0643\u0648\u0646\u064f \u0628\u0627\u0644\u0634\u0651\u064e\u0631\u0639\u0650 \u0648\u0627\u0644\u0627\u062a\u0651\u0650\u0628\u0627\u0639\u0650.","\u0648\u0641\u064a\u0647: \u0623\u0646\u0651\u064e \u0627\u0644\u0625\u064a\u0645\u0627\u0646\u064e \u064a\u064e\u0632\u064a\u062f\u064f \u0648\u064a\u064e\u0646\u0642\u064f\u0635\u064f\u060c \u062d\u064a\u062b \u0625\u0646\u0651\u064e \u0647\u0630\u0627 \u0627\u0644\u062f\u0651\u0650\u064a\u0646\u064e \u0642\u062f \u0643\u064e\u0645\u064e\u0644\u064e \u0628\u062a\u064e\u0645\u0627\u0645\u0650 \u0623\u0639\u0645\u0627\u0644\u0650\u0647."],t.s)
