B.b1m=new A.aD(5,"seira_chapter5","\u062c\u062f\u064f\u0651 \u0627\u0644\u0646\u0628\u064a\u0650\u0651 \ufdfa \u0648\u062d\u0641\u0631 \u0632\u0645\u0632\u0645 \u0648\u0642\u0635\u0629 \u0627\u0644\u0641\u064a\u0644",B.aLU,null,!1)
B.ayH=s(["\u0625\u0646\u064e\u0651 \u0627\u0644\u0646\u0628\u064a\u064e\u0651 \ufdfa \u0623\u0634\u0631\u0641\u064f \u0627\u0644\u0646\u0627\u0633 \u0646\u0633\u0628\u064b\u0627\u060c \u0648\u0623\u0643\u0645\u0644\u064f\u0647\u0645 \u062e\u064e\u0644\u0642\u064b\u0627 \u0648\u062e\u064f\u0644\u064f\u0642\u064b\u0627\u060c \u0648\u0642\u062f \u0648\u0631\u062f\u064e \u0641\u064a \u0634\u0631\u0641 \u0646\u0633\u0628\u0647 \u0623\u062d\u0627\u062f\u064a\u062b\u064f \u0635\u062d\u0627\u062d\u060c \u0645\u0646\u0647\u0627 \u0645\u0627 \u0631\u0648\u0627\u0647 \u0645\u0633\u0644\u0645: \u0623\u0646\u064e\u0651 \u0627\u0644\u0646\u0628\u064a\u064e\u0651 \ufdfa \u0642\u0627\u0644: \xab\u0625\u0646\u0651\u064e \u0627\u0644\u0644\u0647\u064e \u0627\u0635\u0637\u064e\u0641\u0649 \u0643\u0650\u0646\u0627\u0646\u0629\u064e \u0645\u0650\u0646 \u0648\u0644\u064e\u062f\u0650 \u0625\u0633\u0645\u0627\u0639\u064a\u0644\u064e\u060c \u0648\u0627\u0635\u0637\u064e\u0641\u0649 \u0642\u064f\u0631\u064e\u064a\u0634\u064b\u0627 \u0645\u0650\u0646 \u0643\u0650\u0646\u0627\u0646\u0629\u064e\u060c \u0648\u0627\u0635\u0637\u064e\u0641\u0649 \u0645\u0650\u0646 \u0642\u064f\u0631\u064e\u064a\u0634\u064d \u0628\u064e\u0646\u064a \u0647\u0627\u0634\u0650\u0645\u064d\u060c \u0648\u0627\u0635\u0637\u064e\u0641\u0627\u0646\u064a \u0645\u0650\u0646 \u0628\u064e\u0646\u064a \u0647\u0627\u0634\u0650\u0645\u064d\xbb - \u0631\u0648\u0627\u0647 \u0645\u0633\u0644\u0645.","\u0648\u0642\u062f \u0630\u0643\u0631\u064e \u0627\u0644\u0625\u0645\u0627\u0645\u064f \u0627\u0644\u0628\u062e\u0627\u0631\u064a\u064f\u0651 \u0631\u062d\u0645\u0647 \u0627\u0644\u0644\u0647 \u0646\u0633\u0628\u064e \u0627\u0644\u0646\u0628\u064a\u0650\u0651 \ufdfa \u0641\u0642\u0627\u0644: \xab\u0645\u064f\u062d\u064e\u0645\u0651\u064e\u062f\u064f \u0628\u0646\u064f \u0639\u064e\u0628\u062f\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0628\u0646\u0650 \u0639\u064e\u0628\u062f\u0650 \u0627\u0644\u0645\u064f\u0637\u0644\u0650\u0628\u0650 \u0628\u0646\u0650 \u0647\u064e\u0627\u0634\u0650\u0645\u0650 \u0628\u0646\u0650 \u0639\u064e\u0628\u062f\u0650 \u0645\u064e\u0646\u0627\u0641\u0650 \u0628\u0646\u0650 \u0642\u064f\u0635\u064e\u064a\u0651\u0650 \u0628\u0646\u0650 \u0643\u0650\u0644\u064e\u0627\u0628\u0650 \u0628\u0646\u0650 \u0645\u064f\u0631\u0651\u064e\u0629 \u0628\u0646\u0650 \u0643\u064e\u0639\u0628\u0650 \u0628\u0646\u0650 \u0644\u0624\u064a\u0651\u0650 \u0628\u0646\u0650 \u063a\u0627\u0644\u0650\u0628\u0650 \u0628\u0646\u0650 \u0641\u0650\u0647\u0631\u0650 \u0628\u0646\u0650 \u0645\u064e\u0627\u0644\u0650\u0643\u0650 \u0628\u0646\u0650 \u0627\u0644\u0646\u0651\u064e\u0636\u0631\u0650 \u0628\u0646\u0650 \u0643\u0650\u0646\u064e\u0627\u0646\u0629 \u0628\u0646\u0650 \u062e\u064f\u0632\u064e\u064a\u0645\u064e\u0629 \u0628\u0646\u0650 \u0645\u064f\u062f\u0631\u0650\u0643\u064e\u0629 \u0628\u0646\u0650 \u0625\u0644\u064a\u064e\u0627\u0633\u064e \u0628\u0646\u0650 \u0645\u064f\u0636\u0631\u064e \u0628\u0646\u0650 \u0646\u0650\u0632\u0627\u0631 \u0628\u0646\u0650 \u0645\u064e\u0639\u064e\u062f\u0651\u0650 \u0628\u0646\u0650 \u0639\u064e\u062f\u0646\u0627\u0646\u064e\xbb.","\u0627\u062a\u0641\u0642 \u0627\u0644\u0639\u0644\u0645\u0627\u0621 (\u0639\u0631\u0648\u0629 \u0628\u0646 \u0627\u0644\u0632\u0628\u064a\u0631\u060c \u0627\u0628\u0646 \u0633\u0639\u062f\u060c \u0627\u0644\u0628\u063a\u0648\u064a\u060c \u0627\u0644\u0630\u0647\u0628\u064a\u060c \u0627\u0628\u0646 \u0627\u0644\u0642\u064a\u0645) \u0639\u0644\u0649 \u0623\u0646 \u0646\u0633\u0628 \u0627\u0644\u0646\u0628\u064a \ufdfa \u0625\u0644\u0649 \u0639\u062f\u0646\u0627\u0646 \u0645\u0639\u0644\u0648\u0645\u064c \u0635\u062d\u064a\u062d\u064c \u0644\u0627 \u062e\u0644\u0627\u0641 \u0641\u064a\u0647 \u0628\u064a\u0646 \u0627\u0644\u0646\u0633\u0651\u0627\u0628\u064a\u0646\u060c \u0623\u0645\u0627 \u0645\u0627 \u0628\u064a\u0646 \u0639\u062f\u0646\u0627\u0646 \u0648\u0625\u0633\u0645\u0627\u0639\u064a\u0644 \u0639\u0644\u064a\u0647 \u0627\u0644\u0633\u0644\u0627\u0645 \u0645\u0646 \u0627\u0644\u0622\u0628\u0627\u0621 \u0641\u0645\u062e\u062a\u0644\u0641\u064c \u0641\u064a\u0647 \u0648\u0644\u0627 \u064a\u0635\u062d \u062d\u0641\u0638\u0647\u060c \u0645\u0639 \u0625\u062c\u0645\u0627\u0639\u0647\u0645 \u0639\u0644\u0649 \u0623\u0646 \u0639\u062f\u0646\u0627\u0646 \u0645\u0646 \u0648\u0644\u062f \u0625\u0633\u0645\u0627\u0639\u064a\u0644 \u0639\u0644\u064a\u0647 \u0627\u0644\u0633\u0644\u0627\u0645.","\u0648\u0642\u062f \u062c\u0639\u0644 \u0627\u0644\u0644\u0647\u064f \u0644\u0646\u0628\u064a\u0650\u0651\u0647 \ufdfa \u0634\u0631\u0641\u064e \u0627\u0644\u0646\u0633\u0628\u0650\u060c \u0641\u0623\u062d\u0628\u064e\u0651\u0647 \u0627\u0644\u0646\u0627\u0633\u064f \u0648\u0627\u0644\u062a\u0641\u0651\u0648\u0627 \u062d\u0648\u0644\u064e\u0647. \u0648\u062a\u062c\u0644\u0651\u0649 \u0647\u0630\u0627 \u0627\u0644\u0634\u0631\u0641\u064f \u0641\u064a \u0623\u0646\u064e\u0651 \u0627\u0644\u0644\u0647\u064e \u062a\u0639\u0627\u0644\u0649 \u0627\u062e\u062a\u0627\u0631 \u0627\u0644\u0639\u0631\u0628\u064e \u062f\u0648\u0646 \u0633\u0627\u0626\u0631 \u0627\u0644\u0623\u0645\u0645 \u0644\u062d\u0645\u0644 \u0627\u0644\u0631\u0633\u0627\u0644\u0629\u060c \u0648\u0627\u062e\u062a\u0627\u0631 \u0645\u0646 \u0627\u0644\u0639\u0631\u0628 \u0642\u0631\u064a\u0634\u064b\u0627\u060c \u0648\u0645\u0646 \u0642\u0631\u064a\u0634\u064d \u0628\u0646\u064a \u0647\u0627\u0634\u0645\u064d\u060c \u0644\u064a\u0643\u0648\u0646 \u0645\u0646\u0647\u0645 \u062e\u0627\u062a\u0645\u064f \u0627\u0644\u0623\u0646\u0628\u064a\u0627\u0621\u060c \u063a\u064a\u0631 \u0623\u0646\u064e\u0651 \u0647\u0630\u0627 \u0627\u0644\u0646\u0633\u0628\u064e \u062a\u0634\u0631\u064e\u0651\u0641 \u0628\u0627\u0644\u0631\u0633\u0648\u0644 \ufdfa\u060c \u0641\u0627\u0632\u062f\u0627\u062f\u064e \u0634\u0631\u0641\u064b\u0627 \u0648\u0639\u0644\u0648\u064b\u0651\u0627\u060c \u0648\u0644\u064a\u0633 \u0630\u0644\u0643 \u0639\u0635\u0645\u0629\u064b \u0644\u0643\u0644\u0650\u0651 \u0645\u0646 \u0627\u0646\u062a\u0633\u0628 \u0625\u0644\u064a\u0647\u061b \u0641\u0645\u0646 \u0627\u0646\u062d\u0631\u0641\u064e \u0639\u0646 \u0635\u0631\u0627\u0637 \u0627\u0644\u0644\u0647 \u0628\u064e\u0639\u064f\u062f\u064e \u0639\u0646 \u0627\u0644\u0646\u0628\u064a\u0650\u0651 \ufdfa \u0648\u0625\u0646 \u0643\u0627\u0646 \u0628\u064a\u0646\u0647\u0645\u0627 \u0646\u0633\u0628\u064c."],t.s)
B.a7k=new A.a("B1_C6_T1","\u0646\u0633\u0628 \u0627\u0644\u0646\u0628\u064a\u0650\u0651 \ufdfa",B.ayH)
B.aPg=s(["\u0643\u0627\u0646\u064e \u0639\u0628\u062f\u064f \u0627\u0644\u0644\u0647 \u0628\u0646 \u0639\u0628\u062f \u0627\u0644\u0645\u0637\u0644\u0628 \u0645\u0646 \u0623\u062d\u0628\u0650\u0651 \u0648\u0644\u062f\u0650 \u0623\u0628\u064a\u0647 \u0625\u0644\u064a\u0647\u060c \u0648\u0643\u0627\u0646 \u0639\u0628\u062f\u064f \u0627\u0644\u0645\u0637\u0644\u0628 \u0642\u062f \u0646\u0630\u064e\u0631\u064e \u0625\u0630 \u0646\u0627\u0632\u0639\u062a\u0647 \u0642\u0631\u064a\u0634\u064c \u0641\u064a \u062d\u0641\u0631\u0650 \u0632\u0645\u0632\u0645: \u0644\u0626\u0646 \u0648\u0644\u064e\u062f\u064e\u0647 \u0627\u0644\u0644\u0647\u064f \u0639\u0634\u0631\u0629\u064b \u064a\u0634\u0628\u0651\u0648\u0646 \u062d\u062a\u0649 \u064a\u0635\u064a\u0631\u0648\u0627 \u0631\u062c\u0627\u0644\u064b\u0627 \u064a\u062d\u0645\u0648\u0646\u0647 \u0648\u064a\u0643\u0648\u0646\u0648\u0646 \u0644\u0647 \u0639\u0650\u0632\u064b\u0651\u0627 \u0648\u0645\u0646\u0639\u0629\u060c \u0644\u064a\u0646\u062d\u0631\u0646\u064e\u0651 \u0623\u062d\u062f\u064e\u0647\u0645 \u0639\u0646\u062f \u0627\u0644\u0643\u0639\u0628\u0629\u060c \u0641\u0644\u0645\u064e\u0651\u0627 \u062a\u0645\u064e\u0651 \u0644\u0647 \u0639\u062f\u062f\u064f\u0647\u0645 \u0623\u0642\u0631\u0639\u064e \u0628\u064a\u0646\u0647\u0645\u060c \u0641\u0648\u0642\u0639\u062a \u0627\u0644\u0642\u0631\u0639\u0629\u064f \u0639\u0644\u0649 \u0639\u0628\u062f\u0650 \u0627\u0644\u0644\u0647\u060c \u0648\u0644\u0645\u064e\u0651\u0627 \u0646\u062c\u0627 \u0645\u0646 \u0627\u0644\u0630\u0628\u062d \u0648\u0641\u062f\u0627\u0647\u064f \u0639\u0628\u062f\u064f \u0627\u0644\u0645\u0637\u0644\u0628 \u0628\u0645\u0627\u0626\u0629 \u0645\u0646 \u0627\u0644\u0625\u0628\u0644\u060c \u0641\u0632\u0648\u064e\u0651\u062c\u064e\u0647 \u0645\u0646 \u0623\u0634\u0631\u0641 \u0646\u0633\u0627\u0621 \u0645\u0643\u0629 \u0646\u0633\u0628\u064b\u0627\u060c \u0648\u0647\u064a \u0622\u0645\u0650\u0646\u064e\u0629 \u0628\u0646\u062a \u0648\u064e\u0647\u0628 \u0628\u0646 \u0639\u0628\u062f \u0645\u064e\u0646\u0627\u0641 \u0628\u0646\u0650 \u0632\u064f\u0647\u0631\u064e\u0629 \u0628\u0646 \u0643\u0650\u0644\u064e\u0627\u0628.","\u0648\u0644\u0645 \u064a\u0644\u0628\u062b \u0639\u0628\u062f \u0627\u0644\u0644\u0647 \u0623\u0646 \u062a\u0648\u0641\u0650\u0651\u064a\u064e \u0628\u0639\u062f \u0623\u0646 \u062d\u0645\u0644\u064e\u062a \u0622\u0645\u0646\u0629\u060c \u0641\u0642\u062f \u0630\u0647\u0628\u064e \u0628\u062a\u062c\u0627\u0631\u0629 \u0625\u0644\u0649 \u0627\u0644\u0634\u0627\u0645 \u0641\u0623\u062f\u0631\u0643\u064e\u062a\u0647 \u0645\u0646\u064a\u064e\u0651\u062a\u064f\u0647 \u0648\u0647\u0648 \u0642\u0627\u062f\u0645\u064c \u0645\u0646\u0647\u0627\u060c \u0648\u062f\u064f\u0641\u0646\u064e \u0628\u0627\u0644\u0645\u062f\u064a\u0646\u0629 \u0639\u0646\u062f \u0623\u062e\u0648\u0627\u0644\u0647 \u0628\u0646\u064a \u0639\u062f\u064a \u0628\u0646 \u0627\u0644\u0646\u062c\u0627\u0631\u060c \u0648\u062a\u0631\u0643 \u0647\u0630\u0647 \u0627\u0644\u0646\u0633\u0645\u0629\u064e \u0627\u0644\u0645\u0628\u0627\u0631\u0643\u0629\u060c \u0648\u0643\u0623\u0646\u064e\u0651 \u0645\u0647\u0645\u062a\u064e\u0647 \u0641\u064a \u0627\u0644\u062d\u064a\u0627\u0629 \u0642\u062f \u0627\u0646\u062a\u0647\u062a \u0628\u0642\u062f\u0648\u0645 \u0647\u0630\u0627 \u0627\u0644\u062c\u0646\u064a\u0646\u060c \u0627\u0644\u0630\u064a \u062a\u0648\u0644\u0651\u0649 \u0627\u0644\u0644\u0647\u064f \u0639\u0632 \u0648\u062c\u0644 \u0628\u062d\u0643\u0645\u062a\u0647 \u0648\u0631\u062d\u0645\u062a\u0647 \u062a\u0631\u0628\u064a\u062a\u064e\u0647 \u0648\u0625\u0639\u062f\u0627\u062f\u064e\u0647 \u0644\u0625\u062e\u0631\u0627\u062c \u0627\u0644\u0628\u0634\u0631\u064a\u0629 \u0645\u0646 \u0627\u0644\u0638\u0644\u0645\u0627\u062a \u0625\u0644\u0649 \u0627\u0644\u0646\u0648\u0631."],t.s)
