B.aCG=s(["\u062b\u064f\u0648\u064e\u064a\u0628\u064e\u0629 \u0627\u0644\u0623\u0633\u0644\u0645\u064a\u0629 \u0647\u064a \u0623\u0648\u0644 \u0645\u0646 \u0623\u0631\u0636\u0639\u062a \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0628\u0639\u062f \u0623\u0645\u0647 \u0622\u0645\u0646\u0629 \u0628\u0646\u062a \u0648\u0647\u0628\u060c \u0642\u0628\u0644 \u0623\u0646 \u062a\u0642\u062f\u0645 \u062d\u0644\u064a\u0645\u0629 \u0627\u0644\u0633\u0639\u062f\u064a\u0629 \u0628\u0639\u062f \u0630\u0644\u0643 \u0625\u0644\u0649 \u0645\u0643\u0629\u060c \u0648\u062b\u064f\u0648\u064e\u064a\u0628\u064e\u0629 \u0647\u064a \u062c\u0627\u0631\u064a\u0629 \u0623\u0628\u064a \u0644\u0647\u0628 \u0628\u0646 \u0639\u0628\u062f \u0627\u0644\u0645\u0637\u0644\u0628 \u0639\u0645\u0651 \u0627\u0644\u0646\u0628\u064a \ufdfa\u060c \u0648\u0623\u0631\u0636\u0639\u062a -\u0623\u064a\u0636\u0627\u064b- \u062d\u0645\u0632\u0629 \u0628\u0646 \u0639\u0628\u062f \u0627\u0644\u0645\u0637\u0644\u0628 \u0639\u0645\u0651 \u0627\u0644\u0646\u0628\u064a \ufdfa\u060c \u0648\u0623\u0631\u0636\u0639\u062a \u0623\u0628\u0627 \u0633\u0644\u0645\u0629 \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647\u0645\u0627\u060c \u0641\u0635\u0627\u0631\u0627 \u0625\u062e\u0648\u0629\u064b \u0644\u0644\u0646\u0628\u064a \ufdfa \u0645\u0646 \u0627\u0644\u0631\u0636\u0627\u0639\u0629."],t.s)
