B.aG6=s(["\u0643\u0627\u0646 \u0623\u0628\u0648 \u0637\u0627\u0644\u0628 \u0636\u064a\u0650\u0651\u0642\u064e \u0627\u0644\u062d\u0627\u0644\u060c \u0641\u0639\u064e\u0645\u0650\u0644 \u0627\u0644\u0646\u0628\u064a \ufdfa \u0628\u0631\u0639\u064a \u0627\u0644\u063a\u0646\u0645 \u0645\u064f\u0633\u0627\u0639\u064e\u062f\u0629\u064b \u0645\u0646\u0647 \u0644\u0639\u0645\u0650\u0651\u0647\u060c \u0648\u0642\u062f \u0623\u062e\u0628\u064e\u0631 \ufdfa \u0639\u0646 \u0646\u0641\u0633\u0647 \u0627\u0644\u0643\u0631\u064a\u0645\u0629 \u0648\u0639\u0646 \u0625\u062e\u0648\u0627\u0646\u0647 \u0645\u0646 \u0627\u0644\u0623\u0646\u0628\u064a\u0627\u0621 \u0623\u0646\u0647\u0645 \u0631\u0639\u0648\u0627 \u0627\u0644\u063a\u0646\u0645\u060c \u0623\u0645\u0627 \u0647\u0648 \u0641\u0642\u062f \u0631\u0639\u0627\u0647\u0627 \u0644\u0623\u0647\u0644 \u0645\u0643\u0629 \u0648\u0647\u0648 \u063a\u0644\u0627\u0645 \u0648\u0623\u062e\u0630 \u062d\u0642\u064e\u0651\u0647 \u0639\u0644\u0649 \u0631\u0639\u064a\u0647\u060c \u0641\u0641\u064a \u0627\u0644\u062d\u062f\u064a\u062b \u0627\u0644\u0635\u062d\u064a\u062d \u0642\u0627\u0644 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa: \xab\u0645\u0627 \u0628\u0639\u062b\u064e \u0627\u0644\u0644\u0647 \u0646\u0628\u064a\u064b\u0651\u0627 \u0625\u0644\u0627 \u0631\u0639\u0649 \u0627\u0644\u063a\u0646\u0645\xbb\u060c \u0641\u0642\u0627\u0644 \u0623\u0635\u062d\u0627\u0628\u064f\u0647: \u0648\u0623\u0646\u062a\u061f \u0642\u0627\u0644: \xab\u0646\u0639\u0645\u060c \u0643\u0646\u062a\u064f \u0623\u0631\u0639\u0627\u0647\u0627 \u0639\u0644\u0649 \u0642\u064e\u0631\u0627\u0631\u064a\u0637 \u0644\u0623\u0647\u0644 \u0645\u0643\u0629\xbb.","\u0625\u0646 \u0631\u0639\u064a\u064e \u0627\u0644\u063a\u0646\u0645 \u0643\u0627\u0646 \u064a\u064f\u062a\u064a\u062d \u0644\u0644\u0646\u0628\u064a \ufdfa \u0627\u0644\u0647\u062f\u0648\u0621\u064e \u0627\u0644\u0630\u064a \u062a\u062a\u0637\u0644\u064e\u0651\u0628\u0647 \u0646\u0641\u0633\u064f\u0647 \u0627\u0644\u0643\u0631\u064a\u0645\u0629\u060c \u0648\u064a\u064f\u062a\u064a\u062d \u0644\u0647 \u0627\u0644\u0645\u062a\u0639\u0629\u064e \u0628\u062c\u0645\u0627\u0644 \u0627\u0644\u0635\u062d\u0631\u0627\u0621\u060c \u0648\u0627\u0644\u062a\u0637\u0644\u064f\u0651\u0639\u064e \u0625\u0644\u0649 \u0645\u0638\u0627\u0647\u0631 \u062c\u0644\u0627\u0644 \u0627\u0644\u0644\u0647 \u0641\u064a \u0639\u0638\u0645\u0629 \u0627\u0644\u062e\u0644\u0642\u060c \u0648\u0645\u0646\u0627\u062c\u0627\u0629\u064e \u0627\u0644\u0648\u062c\u0648\u062f \u0641\u064a \u0647\u062f\u0623\u0629 \u0627\u0644\u0644\u064a\u0644 \u0648\u0638\u0644\u0627\u0644 \u0627\u0644\u0642\u0645\u0631 \u0648\u0646\u0633\u0645\u0627\u062a \u0627\u0644\u0623\u0634\u062c\u0627\u0631\u060c \u0648\u064a\u064f\u062a\u064a\u062d \u0644\u0647 \u0644\u0648\u0646\u0627\u064b \u0645\u0646 \u0627\u0644\u062a\u0631\u0628\u064a\u0629 \u0627\u0644\u0646\u0641\u0633\u064a\u0629 \u0639\u0644\u0649 \u0627\u0644\u0635\u0628\u0631 \u0648\u0627\u0644\u062d\u0650\u0644\u0645\u060c \u0648\u0627\u0644\u0631\u062d\u0645\u0629\u060c \u0648\u0627\u0644\u0639\u0646\u0627\u064a\u0629 \u0628\u0627\u0644\u0636\u0639\u064a\u0641 \u062d\u062a\u0649 \u064a\u064e\u0642\u0648\u0649\u060c \u0648\u0643\u0628\u062d\u0650 \u0642\u064f\u0648\u0649 \u0627\u0644\u0642\u0648\u064a \u062d\u062a\u0649 \u064a\u064e\u0633\u062a\u0645\u0633\u0643 \u0644\u0644\u0636\u0639\u064a\u0641 \u0648\u064a\u0633\u064a\u0631 \u0628\u0633\u064a\u0631\u0647\u060c \u0648\u0637\u0644\u0628\u0650 \u0645\u0634\u0627\u0631\u0639 \u0627\u0644\u062e\u0635\u0628 \u0648\u0627\u0644\u0631\u0650\u0651\u064a\u0651 \u0648\u062a\u062c\u0646\u064f\u0651\u0628 \u0627\u0644\u0647\u064e\u0644\u064e\u0643\u0629 \u0648\u0645\u0648\u0627\u0642\u0639 \u0627\u0644\u062e\u0648\u0641\u060c \u0648\u0647\u0648 \u0645\u0627 \u0644\u0627 \u062a\u064f\u062a\u064a\u062d\u0647 \u062d\u064a\u0627\u0629\u064c \u0623\u062e\u0631\u0649 \u0628\u0639\u064a\u062f\u0629 \u0639\u0646 \u062c\u0648\u0650\u0651 \u0627\u0644\u0635\u062d\u0631\u0627\u0621 \u0648\u0647\u062f\u0648\u0626\u0647\u0627 \u0648\u0633\u064a\u0627\u0633\u0629 \u0647\u0630\u0627 \u0627\u0644\u062d\u064a\u0648\u0627\u0646 \u0627\u0644\u0623\u0644\u064a\u0641 \u0627\u0644\u0636\u0639\u064a\u0641\u060c \u0648\u0631\u0639\u0627\u064a\u062a\u064f\u0647 \u0644\u0644\u063a\u0646\u0645 \u062a\u064f\u0630\u0643\u0650\u0651\u0631\u0646\u0627 \u0628\u0623\u062d\u0627\u062f\u064a\u062b\u0647 \ufdfa \u0627\u0644\u062a\u064a \u062a\u0648\u062c\u0650\u0651\u0647 \u0627\u0644\u0645\u0633\u0644\u0645\u064a\u0646 \u0625\u0644\u0649 \u0627\u0644\u0625\u062d\u0633\u0627\u0646 \u0625\u0644\u0649 \u0627\u0644\u062d\u064a\u0648\u0627\u0646\u0627\u062a\u060c \u0648\u0643\u0627\u0646 \u0631\u0639\u064a\u064f \u0627\u0644\u063a\u0646\u0645 \u0644\u0647 \ufdfa \u062f\u064f\u0631\u0628\u0629\u064b \u0648\u0645\u0650\u0631\u0627\u0646\u0627\u064b \u0639\u0644\u0649 \u0633\u064a\u0627\u0633\u0629 \u0627\u0644\u0623\u0645\u0645."],t.s)
