B.aSH=s(["\u0627\u0644\u0627\u0633\u062a\u062c\u0627\u0628\u0629 \u0627\u0644\u0643\u0627\u0645\u0644\u0629 \u0644\u0644\u0648\u062d\u064a: \u0644\u0642\u062f \u0643\u0627\u0646 \u0627\u0644\u0635\u062d\u0627\u0628\u0629 \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647\u0645 \u0623\u0639\u0638\u0645\u064e \u0627\u0644\u0646\u0627\u0633 \u0627\u0646\u062a\u0641\u0627\u0639\u0627\u064b \u0628\u0627\u0644\u062f\u0644\u064a\u0644 \u0648\u0627\u0644\u0648\u062d\u064a \u0648\u062a\u0633\u0644\u064a\u0645\u0627\u064b \u0644\u0647\u060c \u0644\u0623\u0633\u0628\u0627\u0628 \u0639\u062f\u064a\u062f\u0629\u061b \u0641\u0642\u0644\u0648\u0628\u0647\u0645 \u0643\u0627\u0646\u062a \u0646\u0642\u064a\u0629\u064b \u062e\u0627\u0644\u064a\u0629\u064b \u0645\u0646 \u0643\u0644 \u0645\u064a\u0644 \u0623\u0648 \u0647\u0648\u0649 \u063a\u064a\u0631 \u0645\u0627 \u062c\u0627\u0621\u062a \u0628\u0647 \u0627\u0644\u0646\u0635\u0648\u0635\u060c \u0645\u0633\u062a\u0639\u062f\u0629\u064b \u062a\u0645\u0627\u0645 \u0627\u0644\u0627\u0633\u062a\u0639\u062f\u0627\u062f \u0644\u0642\u0628\u0648\u0644 \u0645\u0627 \u062c\u0627\u0621 \u0639\u0646 \u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647 \u0648\u0627\u0644\u0627\u0646\u0642\u064a\u0627\u062f \u0644\u0647 \u0627\u0646\u0642\u064a\u0627\u062f\u0627\u064b \u0645\u0637\u0644\u0642\u0627\u064b \u062f\u0648\u0646 \u062d\u0631\u062c \u0648\u0644\u0627 \u062a\u0631\u062f\u062f\u060c \u0648\u0643\u0627\u0646\u0648\u0627 \u064a\u0639\u0627\u0635\u0631\u0648\u0646 \u0648\u0642\u062a \u0627\u0644\u062a\u0634\u0631\u064a\u0639 \u0648\u0646\u0632\u0648\u0644 \u0627\u0644\u0648\u062d\u064a\u060c \u0648\u064a\u0635\u0627\u062d\u0628\u0648\u0646 \u0627\u0644\u0631\u0633\u0648\u0644 \ufdfa \u0645\u0628\u0627\u0634\u0631\u0629\u064b\u060c \u0641\u0643\u0627\u0646\u0648\u0627 \u0623\u0639\u0644\u0645\u064e \u0627\u0644\u0646\u0627\u0633 \u0628\u0645\u0644\u0627\u0628\u0633\u0627\u062a \u0627\u0644\u0623\u062d\u0648\u0627\u0644 \u0627\u0644\u062a\u064a \u0646\u0632\u0644\u062a \u0641\u064a\u0647\u0627 \u0627\u0644\u0646\u0635\u0648\u0635\u060c \u0648\u0627\u0644\u0639\u0644\u0645\u064f \u0628\u0645\u0644\u0627\u0628\u0633\u0627\u062a \u0627\u0644\u0648\u0627\u0642\u0639\u0629 \u0645\u0646 \u0623\u0639\u0638\u0645 \u0623\u0633\u0628\u0627\u0628 \u0641\u0642\u0647\u0647\u0627 \u0648\u0625\u062f\u0631\u0627\u0643 \u0645\u063a\u0632\u0627\u0647\u0627\u060c \u0648\u0643\u0627\u0646\u062a \u0627\u0644\u0646\u0635\u0648\u0635 \u0642\u0631\u0622\u0646\u0627\u064b \u0648\u0633\u0646\u0629\u064b \u062a\u0623\u062a\u064a \u0641\u064a \u0643\u062b\u064a\u0631 \u0645\u0646 \u0627\u0644\u0623\u062d\u064a\u0627\u0646 \u0645\u0639\u0627\u0644\u062c\u0629\u064b \u0644\u0623\u062d\u062f\u0627\u062b \u062a\u062a\u0639\u0644\u0642 \u0628\u0647\u0645 \u0628\u0635\u0648\u0631\u0629 \u0641\u0631\u062f\u064a\u0629 \u0623\u0648 \u062c\u0645\u0627\u0639\u064a\u0629\u060c \u0641\u062a\u062e\u0627\u0637\u0628\u0647\u0645 \u062e\u0637\u0627\u0628\u0627\u064b \u0645\u0628\u0627\u0634\u0631\u0627\u064b \u0648\u062a\u0624\u062b\u0631 \u0641\u064a\u0647\u0645 \u0623\u0639\u0645\u0642 \u0627\u0644\u062a\u0623\u062b\u064a\u0631\u060c \u0644\u0623\u0646\u0647\u0627 \u062a\u0639\u0642\u0651\u0628 \u0639\u0644\u0649 \u0627\u0644\u0648\u0627\u0642\u0639\u0629 \u0641\u064a \u062d\u064a\u0646\u0647\u0627 \u062d\u064a\u0646 \u062a\u0643\u0648\u0646 \u0627\u0644\u0646\u0641\u0648\u0633 \u0645\u0634\u062d\u0648\u0646\u0629\u064b \u0645\u062a\u0647\u064a\u0626\u0629\u064b \u0644\u062a\u0644\u0642\u0651\u064a \u0627\u0644\u0623\u0645\u0631 \u0648\u0627\u0644\u0627\u0633\u062a\u062c\u0627\u0628\u0629 \u0644\u0647\u060c \u062d\u062a\u0649 \u0643\u0627\u0646\u0648\u0627 \u0625\u0630\u0627 \u0633\u0645\u0639\u0648\u0627 \u0623\u062d\u062f\u0627\u064b \u064a\u0642\u0648\u0644: \u0642\u0627\u0644 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa\u060c \u0627\u0628\u062a\u062f\u0631\u062a\u0647 \u0623\u0628\u0635\u0627\u0631\u0647\u0645\u060c \u0643\u0645\u0627 \u064a\u0642\u0648\u0644 \u0627\u0628\u0646 \u0639\u0628\u0627\u0633 \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647.","\u0627\u0644\u062a\u0623\u062b\u0631 \u0627\u0644\u0648\u062c\u062f\u0627\u0646\u064a \u0627\u0644\u0639\u0645\u064a\u0642 \u0628\u0627\u0644\u0648\u062d\u064a \u0648\u0627\u0644\u0625\u064a\u0645\u0627\u0646: \u0644\u0645 \u064a\u0643\u0646 \u0627\u0644\u0635\u062d\u0627\u0628\u0629\u064f \u064a\u062a\u0639\u0627\u0645\u0644\u0648\u0646 \u0645\u0639 \u0627\u0644\u0639\u0644\u0645 \u0627\u0644\u0635\u062d\u064a\u062d \u0643\u062d\u0642\u0627\u0626\u0642\u064e \u0645\u062c\u0631\u062f\u0629 \u064a\u062a\u0639\u0627\u0645\u0644 \u0645\u0639\u0647\u0627 \u0627\u0644\u0639\u0642\u0644 \u0648\u062d\u062f\u0647 \u0628\u0645\u0639\u0632\u0644 \u0639\u0646 \u0627\u0644\u0642\u0644\u0628 \u0648\u0627\u0644\u062c\u0648\u0627\u0631\u062d\u060c \u0641\u0642\u062f \u0623\u0648\u0631\u062b\u064e\u0647\u0645 \u0627\u0644\u0639\u0644\u0645\u064f \u0628\u0627\u0644\u0644\u0647 \u0648\u0623\u0633\u0645\u0627\u0626\u0647 \u0648\u0635\u0641\u0627\u062a\u0647 \u0648\u0623\u0641\u0639\u0627\u0644\u0647 \u0645\u062d\u0628\u062a\u064e\u0647 \u0648\u0627\u0644\u062a\u0623\u0644\u0651\u0647\u064e \u0625\u0644\u064a\u0647\u060c \u0648\u0627\u0644\u0634\u0648\u0642\u064e \u0625\u0644\u0649 \u0644\u0642\u0627\u0626\u0647 \u0648\u0627\u0644\u062a\u0645\u062a\u0639\u064e \u0628\u0627\u0644\u0646\u0638\u0631 \u0625\u0644\u0649 \u0648\u062c\u0647\u0647 \u0627\u0644\u0643\u0631\u064a\u0645 \u0641\u064a \u062c\u0646\u0629 \u0639\u062f\u0646\u060c \u0648\u0623\u0648\u0631\u062b\u0647\u0645 \u062a\u0639\u0638\u064a\u0645\u064e\u0647 \u0648\u0627\u0644\u062e\u0648\u0641\u064e \u0645\u0646\u0647 \u0648\u0627\u0644\u062d\u0630\u0631\u064e \u0645\u0646 \u0628\u0623\u0633\u0647 \u0648\u0639\u0642\u0627\u0628\u0647 \u0648\u0628\u0637\u0634\u0647 \u0648\u0646\u0642\u0645\u062a\u0647\u060c \u0648\u0623\u0648\u0631\u062b\u0647\u0645 \u0631\u062c\u0627\u0621\u064e \u0645\u0627 \u0639\u0646\u062f\u0647 \u0648\u0627\u0644\u0637\u0645\u0639\u064e \u0641\u064a \u062c\u0646\u062a\u0647 \u0648\u0631\u0636\u0648\u0627\u0646\u0647 \u0648\u062d\u0633\u0646\u064e \u0627\u0644\u0638\u0646 \u0628\u0647\u060c \u0641\u0627\u0643\u062a\u0645\u0644\u062a \u0644\u062f\u064a\u0647\u0645 \u0628\u0630\u0644\u0643 \u0622\u062b\u0627\u0631 \u0627\u0644\u0639\u0644\u0645 \u0628\u0627\u0644\u0644\u0647 \u0648\u0627\u0644\u0625\u064a\u0645\u0627\u0646 \u0628\u0647\u060c \u0648\u0647\u0630\u0647 \u0627\u0644\u0645\u0639\u0627\u0646\u064a \u0627\u0644\u0648\u062c\u062f\u0627\u0646\u064a\u0629 \u0647\u064a \u0627\u0644\u0645\u0642\u0635\u0648\u062f \u0627\u0644\u0623\u0639\u0638\u0645 \u0641\u064a \u062a\u062d\u0635\u064a\u0644 \u0627\u0644\u0639\u0644\u0645\u060c \u0648\u0625\u0630\u0627 \u0641\u064f\u0642\u062f\u062a \u0644\u0645 \u064a\u0646\u0641\u0639 \u0645\u0639\u0647\u0627 \u0639\u0644\u0645 \u0628\u0644 \u0643\u0627\u0646 \u0636\u0631\u0631\u0627\u064b \u0641\u064a \u0627\u0644\u0639\u0627\u062c\u0644 \u0648\u0627\u0644\u0622\u062c\u0644.","\u0648\u0643\u0627\u0646 \u0627\u0644\u0635\u062d\u0627\u0628\u0629 \u0641\u0631\u0633\u0627\u0646\u0627\u064b \u0628\u0627\u0644\u0646\u0647\u0627\u0631 \u0631\u0647\u0628\u0627\u0646\u0627\u064b \u0628\u0627\u0644\u0644\u064a\u0644\u060c \u0644\u0627 \u064a\u0645\u0646\u0639\u0647\u0645 \u0639\u0644\u0645\u0647\u0645 \u0648\u0625\u064a\u0645\u0627\u0646\u0647\u0645 \u0648\u062e\u0634\u0648\u0639\u0647\u0645 \u0644\u0644\u0647 \u0645\u0646 \u0627\u0644\u0642\u064a\u0627\u0645 \u0628\u0634\u0624\u0648\u0646\u0647\u0645 \u0627\u0644\u062f\u0646\u064a\u0648\u064a\u0629 \u0645\u0646 \u0628\u064a\u0639 \u0648\u0634\u0631\u0627\u0621 \u0648\u062d\u0631\u062b \u0648\u0646\u0643\u0627\u062d \u0648\u0642\u064a\u0627\u0645 \u0639\u0644\u0649 \u0627\u0644\u0623\u0647\u0644 \u0648\u0627\u0644\u0623\u0648\u0644\u0627\u062f \u0648\u063a\u064a\u0631\u0647\u0645 \u0641\u064a\u0645\u0627 \u064a\u062d\u062a\u0627\u062c\u0648\u0646.","\u0644\u0642\u062f \u0643\u0627\u0646 \u0628\u0646\u0627\u0621 \u0627\u0644\u062c\u0645\u0627\u0639\u0629 \u0627\u0644\u0645\u0624\u0645\u0646\u0629 \u0641\u064a \u0627\u0644\u0641\u062a\u0631\u0629 \u0627\u0644\u0645\u0643\u064a\u0629 \u064a\u062a\u0645 \u0628\u0643\u0644 \u0647\u062f\u0648\u0621 \u0648\u062a\u062f\u0631\u062c \u0648\u0633\u0631\u064a\u0629\u060c \u0648\u0643\u0627\u0646 \u0634\u0639\u0627\u0631 \u0647\u0630\u0647 \u0627\u0644\u0645\u0631\u062d\u0644\u0629 \u062a\u0648\u062c\u064a\u0647 \u0627\u0644\u0645\u0648\u0644\u0649 \u0639\u0632 \u0648\u062c\u0644 \u0627\u0644\u0645\u062a\u0645\u062b\u0644 \u0641\u064a \u0642\u0648\u0644\u0647 \u062a\u0639\u0627\u0644\u0649: \ufd3f\u0648\u064e\u0627\u0635\u0628\u0650\u0631 \u0646\u064e\u0641\u0633\u064e\u0643\u064e \u0645\u064e\u0639\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064e\u062f\u0639\u064f\u0648\u0646\u064e \u0631\u064e\u0628\u0651\u064e\u0647\u064f\u0645 \u0628\u0650\u0627\u0644\u063a\u064e\u062f\u064e\u0627\u0629\u0650 \u0648\u064e\u0627\u0644\u0639\u064e\u0634\u0650\u064a\u0651\u0650 \u064a\u064f\u0631\u0650\u064a\u062f\u064f\u0648\u0646\u064e \u0648\u064e\u062c\u0647\u064e\u0647\u064f \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0639\u062f\u064f \u0639\u064e\u064a\u0646\u064e\u0627\u0643\u064e \u0639\u064e\u0646\u0647\u064f\u0645 \u062a\u064f\u0631\u0650\u064a\u062f\u064f \u0632\u0650\u064a\u0646\u064e\u0629\u064e \u0627\u0644\u062d\u064e\u064a\u064e\u0627\u0629\u0650 \u0627\u0644\u062f\u0651\u064f\u0646\u064a\u064e\u0627 \u0648\u064e\u0644\u064e\u0627 \u062a\u064f\u0637\u0650\u0639 \u0645\u064e\u0646 \u0623\u064e\u063a\u0641\u064e\u0644\u0646\u064e\u0627 \u0642\u064e\u0644\u0628\u064e\u0647\u064f \u0639\u064e\u0646 \u0630\u0650\u0643\u0631\u0650\u0646\u064e\u0627 \u0648\u064e\u0627\u062a\u0651\u064e\u0628\u064e\u0639\u064e \u0647\u064e\u0648\u064e\u0627\u0647\u064f \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0623\u064e\u0645\u0631\u064f\u0647\u064f \u0641\u064f\u0631\u064f\u0637\u064b\u0627\ufd3e - \u0633\u0648\u0631\u0629 \u0627\u0644\u0643\u0647\u0641\u060c \u0641\u0627\u0644\u0622\u064a\u0629 \u0627\u0644\u0643\u0631\u064a\u0645\u0629 \u062a\u0623\u0645\u0631 \u0627\u0644\u0646\u0628\u064a \ufdfa \u0628\u0623\u0646 \u064a\u0635\u0628\u0631 \u0639\u0644\u0649 \u062a\u0642\u0635\u064a\u0631 \u0627\u0644\u0645\u0633\u062a\u062c\u064a\u0628\u064a\u0646 \u0644\u062f\u0639\u0648\u062a\u0647 \u0648\u0623\u062e\u0637\u0627\u0626\u0647\u0645\u060c \u0648\u0639\u0644\u0649 \u0643\u062b\u0631\u0629 \u062a\u0633\u0627\u0624\u0644\u0627\u062a\u0647\u0645 \u0648\u0625\u0646 \u0643\u0627\u0646\u062a \u062e\u0627\u0637\u0626\u0629\u060c \u0648\u0639\u0644\u0649 \u062a\u0631\u062f\u062f\u0647\u0645 \u0641\u064a \u0642\u0628\u0648\u0644 \u0627\u0644\u062a\u0648\u062c\u064a\u0647\u0627\u062a\u060c \u0648\u0623\u0646 \u064a\u062c\u062a\u0647\u062f \u0641\u064a \u062a\u0635\u0628\u064a\u0631\u0647\u0645 \u0639\u0644\u0649 \u0641\u062a\u0646\u0629 \u0623\u0639\u062f\u0627\u0621 \u0627\u0644\u062f\u0639\u0648\u0629\u060c \u0648\u0623\u0646 \u064a\u0648\u0636\u062d \u0644\u0647\u0645 \u0637\u0628\u064a\u0639\u0629 \u0637\u0631\u064a\u0642 \u0627\u0644\u062f\u0639\u0648\u0629 \u0648\u0645\u0627 \u0641\u064a\u0647 \u0645\u0646 \u0645\u0634\u0642\u0629\u060c \u0648\u0623\u0644\u0627 \u064a\u064f\u063a\u064e\u0631\u064e\u0651 \u0628\u0647 \u0645\u064f\u063a\u064e\u0631\u0650\u0651\u0631\u064c \u0644\u064a\u064f\u0628\u0639\u062f\u0647 \u0639\u0646\u0647\u0645\u060c \u0648\u0623\u0644\u0627 \u064a\u064e\u0633\u0645\u0639 \u0641\u064a\u0647\u0645 \u0645\u064f\u0646\u062a\u064e\u0642\u0650\u0635\u0627\u064b\u060c \u0648\u0644\u0627 \u064a\u0637\u064a\u0639 \u0641\u064a\u0647\u0645 \u0645\u064f\u062a\u064e\u0643\u064e\u0628\u0650\u0651\u0631\u0627\u064b \u0623\u063a\u0641\u0644 \u0627\u0644\u0644\u0647 \u0642\u0644\u0628\u0647 \u0639\u0646 \u062d\u0642\u064a\u0642\u0629 \u0627\u0644\u0623\u0645\u0648\u0631 \u0648\u062c\u0648\u0647\u0631\u0647\u0627.","\u062a\u0635\u0641 \u062a\u0644\u0643 \u0627\u0644\u0622\u064a\u0627\u062a \u0627\u0644\u0643\u0631\u064a\u0645\u0629 \u0645\u0646 \u0633\u0648\u0631\u0629 \u0627\u0644\u0643\u0647\u0641 \u0628\u0639\u0636 \u0635\u0641\u0627\u062a \u0627\u0644\u062c\u0645\u0627\u0639\u0629 \u0627\u0644\u0645\u0633\u0644\u0645\u0629 \u0627\u0644\u0623\u0648\u0644\u0649\u060c \u0648\u0645\u0646 \u0623\u0647\u0645\u0647\u0627:","\u0627\u0644\u0635\u0628\u0631: \u0648\u064a\u0638\u0647\u0631 \u0641\u064a \u0642\u0648\u0644\u0647 \u062a\u0639\u0627\u0644\u0649: \ufd3f\u0648\u064e\u0627\u0635\u0628\u0650\u0631 \u0646\u064e\u0641\u0633\u064e\u0643\u064e\ufd3e\u060c \u0648\u0643\u0644\u0645\u0629 \u0627\u0644\u0635\u0628\u0631 \u062a\u062a\u0631\u062f\u062f \u0641\u064a \u0627\u0644\u0642\u0631\u0622\u0646 \u0627\u0644\u0643\u0631\u064a\u0645 \u0648\u0641\u064a \u0623\u062d\u0627\u062f\u064a\u062b \u0627\u0644\u0646\u0628\u064a \ufdfa \u0648\u064a\u0648\u0635\u064a \u0627\u0644\u0646\u0627\u0633 \u0628\u0647\u0627 \u0628\u0639\u0636\u0647\u0645 \u0628\u0639\u0636\u0627\u064b\u060c \u0648\u062a\u0628\u0644\u063a \u0623\u0647\u0645\u064a\u062a\u0647\u0627 \u0623\u0646 \u062a\u0635\u064a\u0631 \u0635\u0641\u0629\u064b \u0645\u0646 \u0623\u0631\u0628\u0639 \u0644\u0644\u0641\u0626\u0629 \u0627\u0644\u0646\u0627\u062c\u064a\u0629 \u0645\u0646 \u0627\u0644\u062e\u0633\u0631\u0627\u0646\u060c \u0642\u0627\u0644 \u062a\u0639\u0627\u0644\u0649: \ufd3f\u0648\u064e\u0627\u0644\u0639\u064e\u0635\u0631\u0650 \u06dd \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0625\u0650\u0646\u0633\u064e\u0627\u0646\u064e \u0644\u064e\u0641\u0650\u064a \u062e\u064f\u0633\u0631\u064d \u06dd \u0625\u0650\u0644\u0651\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627 \u0627\u0644\u0635\u0651\u064e\u0627\u0644\u0650\u062d\u064e\u0627\u062a\u0650 \u0648\u064e\u062a\u064e\u0648\u064e\u0627\u0635\u064e\u0648\u0627 \u0628\u0650\u0627\u0644\u062d\u064e\u0642\u0651\u0650 \u0648\u064e\u062a\u064e\u0648\u064e\u0627\u0635\u064e\u0648\u0627 \u0628\u0650\u0627\u0644\u0635\u0651\u064e\u0628\u0631\u0650\ufd3e - \u0633\u0648\u0631\u0629 \u0627\u0644\u0639\u0635\u0631\u060c \u0641\u062d\u0643\u0645 \u0627\u0644\u0645\u0648\u0644\u0649 \u0639\u0632 \u0648\u062c\u0644 \u0639\u0644\u0649 \u062c\u0645\u064a\u0639 \u0627\u0644\u0646\u0627\u0633 \u0628\u0627\u0644\u062e\u0633\u0631\u0627\u0646 \u0625\u0644\u0627 \u0645\u0646 \u0623\u062a\u0649 \u0628\u0647\u0630\u0647 \u0627\u0644\u0623\u0645\u0648\u0631 \u0627\u0644\u0623\u0631\u0628\u0639\u0629: \u0627\u0644\u0625\u064a\u0645\u0627\u0646 \u0628\u0627\u0644\u0644\u0647\u060c \u0648\u0627\u0644\u0639\u0645\u0644 \u0627\u0644\u0635\u0627\u0644\u062d\u060c \u0648\u0627\u0644\u062a\u0648\u0627\u0635\u064a \u0628\u0627\u0644\u062d\u0642\u060c \u0648\u0627\u0644\u062a\u0648\u0627\u0635\u064a \u0628\u0627\u0644\u0635\u0628\u0631\u060c \u0644\u0623\u0646 \u0646\u062c\u0627\u0629 \u0627\u0644\u0625\u0646\u0633\u0627\u0646 \u0644\u0627 \u062a\u0643\u0648\u0646 \u0625\u0644\u0627 \u0625\u0630\u0627 \u0623\u0643\u0645\u0644 \u0646\u0641\u0633\u0647 \u0628\u0627\u0644\u0625\u064a\u0645\u0627\u0646 \u0648\u0627\u0644\u0639\u0645\u0644 \u0627\u0644\u0635\u0627\u0644\u062d\u060c \u0648\u0623\u0643\u0645\u0644 \u063a\u064a\u0631\u0647 \u0628\u0627\u0644\u0646\u0635\u062d \u0648\u0627\u0644\u0625\u0631\u0634\u0627\u062f\u060c \u0641\u064a\u062c\u0645\u0639 \u0628\u064a\u0646 \u062d\u0642 \u0627\u0644\u0644\u0647 \u0648\u062d\u0642 \u0627\u0644\u0639\u0628\u0627\u062f\u060c \u0648\u0627\u0644\u062a\u0648\u0627\u0635\u064a \u0628\u0627\u0644\u0635\u0628\u0631 \u0636\u0631\u0648\u0631\u0629 \u0643\u0630\u0644\u0643\u060c \u0641\u0627\u0644\u0642\u064a\u0627\u0645 \u0639\u0644\u0649 \u0627\u0644\u0625\u064a\u0645\u0627\u0646 \u0648\u0627\u0644\u0639\u0645\u0644 \u0627\u0644\u0635\u0627\u0644\u062d \u0648\u062d\u0631\u0627\u0633\u0629 \u0627\u0644\u062d\u0642 \u0648\u0627\u0644\u0639\u062f\u0644 \u0645\u0646 \u0623\u0639\u0633\u0631 \u0645\u0627 \u064a\u0648\u0627\u062c\u0647 \u0627\u0644\u0641\u0631\u062f \u0648\u0627\u0644\u062c\u0645\u0627\u0639\u0629\u060c \u0648\u0644\u0627 \u0628\u062f \u0645\u0646 \u0627\u0644\u0635\u0628\u0631 \u0639\u0644\u0649 \u062c\u0647\u0627\u062f \u0627\u0644\u0646\u0641\u0633 \u0648\u062c\u0647\u0627\u062f \u0627\u0644\u063a\u064a\u0631\u060c \u0648\u0627\u0644\u0635\u0628\u0631 \u0639\u0644\u0649 \u0627\u0644\u0623\u0630\u0649 \u0648\u0627\u0644\u0645\u0634\u0642\u0629\u060c \u0648\u0627\u0644\u0635\u0628\u0631 \u0639\u0644\u0649 \u062a\u064e\u0628\u064e\u062c\u064f\u0651\u062d \u0627\u0644\u0628\u0627\u0637\u0644\u060c \u0648\u0627\u0644\u0635\u0628\u0631 \u0639\u0644\u0649 \u0637\u0648\u0644 \u0627\u0644\u0637\u0631\u064a\u0642 \u0648\u0628\u0637\u0621 \u0627\u0644\u0645\u0631\u0627\u062d\u0644\u060c \u0648\u0627\u0646\u0637\u0645\u0627\u0633 \u0627\u0644\u0645\u0639\u0627\u0644\u0645 \u0648\u0628\u0639\u062f \u0627\u0644\u0646\u0647\u0627\u064a\u0629.","\u0643\u062b\u0631\u0629 \u0627\u0644\u062f\u0639\u0627\u0621 \u0648\u0627\u0644\u0625\u0644\u062d\u0627\u062d \u0639\u0644\u0649 \u0627\u0644\u0644\u0647: \u0648\u064a\u0638\u0647\u0631 \u0641\u064a \u0642\u0648\u0644\u0647 \u062a\u0639\u0627\u0644\u0649: \ufd3f\u064a\u064e\u062f\u0639\u064f\u0648\u0646\u064e \u0631\u064e\u0628\u0651\u064e\u0647\u064f\u0645 \u0628\u0650\u0627\u0644\u063a\u064e\u062f\u064e\u0627\u0629\u0650 \u0648\u064e\u0627\u0644\u0639\u064e\u0634\u0650\u064a\u0651\u0650\ufd3e\u060c \u0641\u0627\u0644\u062f\u0639\u0627\u0621 \u0628\u0627\u0628 \u0639\u0638\u064a\u0645 \u0625\u0630\u0627 \u0641\u064f\u062a\u062d \u0644\u0644\u0639\u0628\u062f \u062a\u062a\u0627\u0628\u0639\u062a \u0639\u0644\u064a\u0647 \u0627\u0644\u062e\u064a\u0631\u0627\u062a \u0648\u0627\u0646\u0647\u0627\u0644\u062a \u0639\u0644\u064a\u0647 \u0627\u0644\u0628\u0631\u0643\u0627\u062a\u060c \u0648\u0644\u0627 \u0628\u062f \u0645\u0646 \u062a\u0631\u0628\u064a\u0629 \u0627\u0644\u0623\u0641\u0631\u0627\u062f \u0627\u0644\u0630\u064a\u0646 \u064a\u064f\u0639\u064e\u062f\u064f\u0651\u0648\u0646 \u0644\u062d\u0645\u0644 \u0627\u0644\u0631\u0633\u0627\u0644\u0629 \u0648\u0623\u062f\u0627\u0621 \u0627\u0644\u0623\u0645\u0627\u0646\u0629 \u0639\u0644\u0649 \u062d\u0633\u0646 \u0627\u0644\u0635\u0644\u0629 \u0628\u0627\u0644\u0644\u0647 \u0648\u0643\u062b\u0631\u0629 \u0627\u0644\u062f\u0639\u0627\u0621\u060c \u0644\u0623\u0646 \u0630\u0644\u0643 \u0645\u0646 \u0623\u0639\u0638\u0645 \u0639\u0648\u0627\u0645\u0644 \u0627\u0644\u0646\u0635\u0631 \u0648\u0623\u0642\u0648\u0627\u0647\u0627.","\u0627\u0644\u0625\u062e\u0644\u0627\u0635: \u0648\u064a\u0638\u0647\u0631 \u0641\u064a \u0642\u0648\u0644\u0647 \u062a\u0639\u0627\u0644\u0649: \ufd3f\u064a\u064f\u0631\u0650\u064a\u062f\u064f\u0648\u0646\u064e \u0648\u064e\u062c\u0647\u064e\u0647\u064f\ufd3e\u060c \u0648\u0644\u0627 \u0628\u062f \u0639\u0646\u062f \u0625\u0639\u062f\u0627\u062f \u0627\u0644\u0623\u0641\u0631\u0627\u062f \u0625\u0639\u062f\u0627\u062f\u0627\u064b \u0631\u0628\u0627\u0646\u064a\u0627\u064b \u0623\u0646 \u064a\u062a\u0631\u0628\u0649 \u0627\u0644\u0645\u0633\u0644\u0645 \u0639\u0644\u0649 \u0623\u0646 \u062a\u0643\u0648\u0646 \u0623\u0642\u0648\u0627\u0644\u0647 \u0648\u0623\u0639\u0645\u0627\u0644\u0647 \u0648\u062c\u0647\u0627\u062f\u0647 \u0643\u0644\u0647 \u0644\u0648\u062c\u0647 \u0627\u0644\u0644\u0647 \u0648\u0627\u0628\u062a\u063a\u0627\u0621 \u0645\u0631\u0636\u0627\u062a\u0647 \u0648\u062d\u0633\u0646 \u0645\u062b\u0648\u0628\u062a\u0647\u060c \u0645\u0646 \u063a\u064a\u0631 \u0646\u0638\u0631 \u0625\u0644\u0649 \u0645\u064e\u063a\u0646\u064e\u0645 \u0623\u0648 \u062c\u0627\u0647 \u0623\u0648 \u0644\u0642\u0628 \u0623\u0648 \u062a\u0642\u062f\u0645 \u0623\u0648 \u062a\u0623\u062e\u0631\u060c \u062d\u062a\u0649 \u064a\u0635\u0628\u062d \u062c\u0646\u062f\u064a\u0627\u064b \u0645\u0646 \u0623\u062c\u0644 \u0627\u0644\u0639\u0642\u064a\u062f\u0629 \u0648\u0627\u0644\u0645\u0646\u0647\u062c \u0627\u0644\u0631\u0628\u0627\u0646\u064a\u060c \u0648\u0644\u0633\u0627\u0646 \u062d\u0627\u0644\u0647 \u0642\u0648\u0644\u0647 \u062a\u0639\u0627\u0644\u0649: \ufd3f\u0642\u064f\u0644 \u0625\u0650\u0646\u0651\u064e \u0635\u064e\u0644\u064e\u0627\u062a\u0650\u064a \u0648\u064e\u0646\u064f\u0633\u064f\u0643\u0650\u064a \u0648\u064e\u0645\u064e\u062d\u064a\u064e\u0627\u064a\u064e \u0648\u064e\u0645\u064e\u0645\u064e\u0627\u062a\u0650\u064a \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0631\u064e\u0628\u0651\u0650 \u0627\u0644\u0639\u064e\u0627\u0644\u064e\u0645\u0650\u064a\u0646\u064e \u06dd \u0644\u064e\u0627 \u0634\u064e\u0631\u0650\u064a\u0643\u064e \u0644\u064e\u0647\u064f \u0648\u064e\u0628\u0650\u0630\u064e\u0644\u0650\u0643\u064e \u0623\u064f\u0645\u0650\u0631\u062a\u064f \u0648\u064e\u0623\u064e\u0646\u064e\u0627 \u0623\u064e\u0648\u0651\u064e\u0644\u064f \u0627\u0644\u0645\u064f\u0633\u0644\u0650\u0645\u0650\u064a\u0646\u064e\ufd3e - \u0633\u0648\u0631\u0629 \u0627\u0644\u0623\u0646\u0639\u0627\u0645\u060c \u0648\u0627\u0644\u0625\u062e\u0644\u0627\u0635 \u0631\u0643\u0646 \u0645\u0646 \u0623\u0631\u0643\u0627\u0646 \u0642\u0628\u0648\u0644 \u0627\u0644\u0639\u0645\u0644\u060c \u0648\u0645\u0639\u0644\u0648\u0645 \u0623\u0646 \u0627\u0644\u0639\u0645\u0644 \u0639\u0646\u062f \u0627\u0644\u0644\u0647 \u0644\u0627 \u064a\u064f\u0642\u0628\u0644 \u0625\u0644\u0627 \u0628\u0627\u0644\u0625\u062e\u0644\u0627\u0635 \u0648\u062a\u0635\u062d\u064a\u062d \u0627\u0644\u0646\u064a\u0629 \u0648\u0645\u0648\u0627\u0641\u0642\u0629 \u0627\u0644\u0633\u0646\u0629 \u0648\u0627\u0644\u0634\u0631\u0639.","\u0627\u0644\u062b\u0628\u0627\u062a: \u0648\u064a\u0638\u0647\u0631 \u0641\u064a \u0642\u0648\u0644\u0647 \u062a\u0639\u0627\u0644\u0649: \ufd3f\u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0639\u062f\u064f \u0639\u064e\u064a\u0646\u064e\u0627\u0643\u064e \u0639\u064e\u0646\u0647\u064f\u0645 \u062a\u064f\u0631\u0650\u064a\u062f\u064f \u0632\u0650\u064a\u0646\u064e\u0629\u064e \u0627\u0644\u062d\u064e\u064a\u064e\u0627\u0629\u0650 \u0627\u0644\u062f\u0651\u064f\u0646\u064a\u064e\u0627\ufd3e - \u0633\u0648\u0631\u0629 \u0627\u0644\u0643\u0647\u0641\u060c \u0648\u0647\u0630\u0627 \u0627\u0644\u062b\u0628\u0627\u062a \u0641\u0631\u0639 \u0639\u0646 \u062b\u0628\u0627\u062a \u0623\u0639\u0645 \u064a\u0646\u0628\u063a\u064a \u0623\u0646 \u064a\u062a\u0633\u0645 \u0628\u0647 \u0627\u0644\u062f\u0627\u0639\u064a\u0629 \u0627\u0644\u0631\u0628\u0627\u0646\u064a\u060c \u0642\u0627\u0644 \u062a\u0639\u0627\u0644\u0649: \ufd3f\u0645\u0651\u0650\u0646\u064e \u0627\u0644\u0645\u064f\u0624\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u0631\u0650\u062c\u064e\u0627\u0644\u064c \u0635\u064e\u062f\u064e\u0642\u064f\u0648\u0627 \u0645\u064e\u0627 \u0639\u064e\u0627\u0647\u064e\u062f\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0639\u064e\u0644\u064e\u064a\u0647\u0650 \u0641\u064e\u0645\u0650\u0646\u0647\u064f\u0645 \u0645\u0651\u064e\u0646 \u0642\u064e\u0636\u064e\u0649 \u0646\u064e\u062d\u0628\u064e\u0647\u064f \u0648\u064e\u0645\u0650\u0646\u0647\u064f\u0645 \u0645\u0651\u064e\u0646 \u064a\u064e\u0646\u062a\u064e\u0638\u0650\u0631\u064f \u0648\u064e\u0645\u064e\u0627 \u0628\u064e\u062f\u0651\u064e\u0644\u064f\u0648\u0627 \u062a\u064e\u0628\u062f\u0650\u064a\u0644\u064b\u0627\ufd3e - \u0633\u0648\u0631\u0629 \u0627\u0644\u0623\u062d\u0632\u0627\u0628\u060c \u0641\u0641\u064a \u0627\u0644\u0622\u064a\u0629 \u062b\u0644\u0627\u062b \u0635\u0641\u0627\u062a: \u0625\u064a\u0645\u0627\u0646 \u0648\u0631\u062c\u0648\u0644\u0629 \u0648\u0635\u062f\u0642\u060c \u0648\u0647\u0630\u0647 \u0627\u0644\u0639\u0646\u0627\u0635\u0631 \u0645\u0647\u0645\u0629 \u0644\u0644\u062b\u0628\u0627\u062a \u0639\u0644\u0649 \u0627\u0644\u0645\u0646\u0647\u062c \u0627\u0644\u062d\u0642\u060c \u0644\u0623\u0646 \u0627\u0644\u0625\u064a\u0645\u0627\u0646 \u064a\u064e\u0628\u0639\u062b \u0639\u0644\u0649 \u0627\u0644\u062a\u0645\u0633\u0643 \u0628\u0627\u0644\u0642\u064a\u0645 \u0627\u0644\u0631\u0641\u064a\u0639\u0629 \u0648\u0627\u0644\u062a\u0634\u0628\u062b \u0628\u0647\u0627\u060c \u0648\u064a\u064e\u0628\u0639\u062b \u0639\u0644\u0649 \u0627\u0644\u062a\u0636\u062d\u064a\u0629 \u0628\u0627\u0644\u0646\u0641\u0633 \u0644\u064a\u0628\u0642\u0649 \u0627\u0644\u0645\u0628\u062f\u0623\u060c \u0648\u0627\u0644\u0631\u062c\u0648\u0644\u0629 \u0645\u064f\u062d\u064e\u0631\u0650\u0651\u0643\u0629\u064c \u0644\u0644\u0646\u0641\u0633 \u0646\u062d\u0648 \u0627\u0644\u0647\u062f\u0641 \u063a\u064a\u0631 \u0645\u064f\u0628\u0627\u0644\u064a\u0629 \u0628\u0627\u0644\u0635\u063a\u0627\u0626\u0631\u060c \u062f\u0627\u0641\u0639\u0629\u064c \u062f\u0627\u0626\u0645\u0627\u064b \u0646\u062d\u0648 \u0627\u0644\u0645\u0628\u062f\u0623 \u0627\u0644\u0631\u0641\u064a\u0639\u060c \u0648\u0627\u0644\u0635\u062f\u0642 \u064a\u062d\u0648\u0644 \u062f\u0648\u0646 \u0627\u0644\u062a\u062d\u0648\u0644 \u0623\u0648 \u0627\u0644\u062a\u0628\u062f\u064a\u0644\u060c \u0648\u064a\u0648\u0631\u062b \u0647\u0630\u0627 \u0643\u0644\u0647 \u0627\u0644\u062b\u0628\u0627\u062a\u064e \u0627\u0644\u0630\u064a \u0644\u0627 \u064a\u062a\u0644\u0648\u0646 \u0645\u0639\u0647 \u0627\u0644\u0625\u0646\u0633\u0627\u0646 \u0648\u0625\u0646 \u0631\u0623\u0649 \u0634\u0639\u0627\u0639 \u0627\u0644\u0633\u064a\u0641 \u0639\u0644\u0649 \u0631\u0642\u0628\u062a\u0647 \u0623\u0648 \u062d\u0628\u0644 \u0627\u0644\u0645\u0634\u0646\u0642\u0629 \u064a\u0646\u062a\u0638\u0631\u0647 \u0623\u0648 \u0631\u0623\u0649 \u0627\u0644\u062f\u0646\u064a\u0627 \u064a\u0635\u064a\u0628\u0647\u0627 \u0623\u0648 \u0627\u0645\u0631\u0623\u0629 \u064a\u0646\u0643\u062d\u0647\u0627\u060c \u0648\u0644\u0627 \u0634\u0643 \u0623\u0646 \u0627\u0644\u0644\u0628\u0646\u0627\u062a \u0627\u0644\u062a\u064a \u062a\u064f\u0639\u064e\u062f \u0644\u062d\u0645\u0644 \u0627\u0644\u062f\u0639\u0648\u0629 \u0648\u0625\u0642\u0627\u0645\u0629 \u0627\u0644\u062f\u0648\u0644\u0629 \u0648\u0635\u0646\u0627\u0639\u0629 \u0627\u0644\u062d\u0636\u0627\u0631\u0629 \u062a\u062d\u062a\u0627\u062c \u0625\u0644\u0649 \u0647\u0630\u0627 \u0627\u0644\u062b\u0628\u0627\u062a \u0627\u0644\u0630\u064a \u064a\u064f\u0639\u064a\u0646 \u0639\u0644\u0649 \u062a\u062d\u0642\u064a\u0642 \u0627\u0644\u0623\u0647\u062f\u0627\u0641 \u0627\u0644\u0633\u0627\u0645\u064a\u0629 \u0648\u0627\u0644\u063a\u0627\u064a\u0627\u062a \u0627\u0644\u062c\u0645\u064a\u0644\u0629 \u0648\u0627\u0644\u0642\u064a\u0645 \u0627\u0644\u0631\u0641\u064a\u0639\u0629."],t.s)
