B.aGT=s(["\u0643\u0627\u0646 \u0645\u0646\u0647\u062c \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0641\u064a \u0645\u0639\u0627\u0645\u0644\u062a\u0647 \u0644\u0644\u0646\u0627\u0633 \u062d\u0643\u064a\u0645\u064b\u0627\u060c \u0641\u0643\u0627\u0646 \u064a\u0639\u0627\u0645\u0644 \u0627\u0644\u0623\u0643\u0627\u0628\u0631 \u0648\u0632\u0639\u0645\u0627\u0621 \u0627\u0644\u0642\u0628\u0627\u0626\u0644 \u0628\u0644\u0637\u0641 \u0648\u062a\u0631\u0641\u0642\u060c \u0648\u0643\u0630\u0644\u0643 \u0627\u0644\u0635\u0628\u064a\u0627\u0646 \u0627\u0644\u0635\u063a\u0627\u0631\u060c \u0648\u0647\u0630\u0627 \u0627\u0628\u0646 \u0645\u0633\u0639\u0648\u062f \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647 \u064a\u064f\u062d\u062f\u0650\u0651\u062b\u0646\u0627 \u0639\u0646 \u0644\u0642\u0627\u0626\u0647 \u0627\u0644\u0644\u0637\u064a\u0641 \u0628\u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa: \u0643\u0646\u062a \u063a\u0644\u0627\u0645\u064b\u0627 \u064a\u0627\u0641\u0639\u064b\u0627 \u0623\u0631\u0639\u0649 \u063a\u0646\u0645\u064b\u0627 \u0644\u0639\u0642\u0628\u0629 \u0628\u0646 \u0623\u0628\u064a \u0645\u064f\u0639\u064e\u064a\u0637\u060c \u0641\u0645\u0631\u064e\u0651 \u0628\u064a \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0648\u0623\u0628\u0648 \u0628\u0643\u0631\u060c \u0641\u0642\u0627\u0644: \xab\u064a\u0627 \u063a\u0644\u0627\u0645 \u0647\u0644 \u0645\u0646 \u0644\u0628\u0646\u061f\xbb \u0642\u0644\u062a: \u0646\u0639\u0645\u060c \u0648\u0644\u0643\u0646\u064a \u0645\u064f\u0624\u062a\u064e\u0645\u064e\u0646\u060c \u0642\u0627\u0644: \xab\u0641\u0647\u0644 \u0645\u0646 \u0634\u0627\u0629 \u0644\u0645 \u064a\u064e\u0646\u0632\u064f \u0639\u0644\u064a\u0647\u0627 \u0641\u062d\u0644\u061f\xbb \u0641\u0623\u062a\u064a\u062a\u0647 \u0628\u0634\u0627\u0629\u060c \u0641\u0645\u0633\u062d \u0636\u064e\u0631\u0639\u0647\u0627 \u0641\u0646\u0632\u0644 \u0644\u0628\u0646\u060c \u0641\u062d\u0644\u0628\u0647 \u0641\u064a \u0625\u0646\u0627\u0621 \u0641\u0634\u0631\u0628 \u0648\u0633\u0642\u0649 \u0623\u0628\u0627 \u0628\u0643\u0631\u060c \u062b\u0645 \u0642\u0627\u0644 \u0644\u0644\u0636\u064e\u0651\u0631\u0639: \xab\u0627\u0642\u0644\u064f\u0635\xbb\u060c \u0641\u0642\u064e\u0644\u064e\u0635\u060c \u0642\u0627\u0644: \u062b\u0645 \u0623\u062a\u064a\u062a\u0647 \u0628\u0639\u062f \u0647\u0630\u0627 \u0641\u0642\u0644\u062a: \u064a\u0627 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \u0639\u0644\u0645\u0646\u064a \u0645\u0646 \u0647\u0630\u0627 \u0627\u0644\u0642\u0648\u0644\u060c \u0642\u0627\u0644: \u0641\u0645\u0633\u062d \u0631\u0623\u0633\u064a \u0648\u0642\u0627\u0644: \xab\u064a\u0631\u062d\u0645\u0643 \u0627\u0644\u0644\u0647 \u0641\u0625\u0646\u0643 \u063a\u064f\u0644\u064a\u0645 \u0645\u064f\u0639\u064e\u0644\u064e\u0651\u0645\xbb.","\u0648\u0647\u0643\u0630\u0627 \u0643\u0627\u0646 \u0645\u0641\u062a\u0627\u062d \u0625\u0633\u0644\u0627\u0645\u0647 \u0643\u0644\u0645\u062a\u064a\u0646 \u0639\u0638\u064a\u0645\u062a\u064a\u0646: \u0627\u0644\u0623\u0648\u0644\u0649 \u0642\u0627\u0644\u0647\u0627 \u0639\u0646 \u0646\u0641\u0633\u0647 \xab\u0625\u0646\u064a \u0645\u064f\u0624\u062a\u064e\u0645\u064e\u0646\xbb\u060c \u0648\u0627\u0644\u062b\u0627\u0646\u064a\u0629 \u0643\u0627\u0646\u062a \u0645\u0646 \u0627\u0644\u0635\u0627\u062f\u0642 \u0627\u0644\u0645\u0635\u062f\u0648\u0642: \xab\u0625\u0646\u0643 \u063a\u064f\u0644\u064a\u0645 \u0645\u064f\u0639\u064e\u0644\u064e\u0651\u0645\xbb\u060c \u0648\u0644\u0642\u062f \u0643\u0627\u0646 \u0644\u0647\u0627\u062a\u064a\u0646 \u0627\u0644\u0643\u0644\u0645\u062a\u064a\u0646 \u062f\u0648\u0631\u064c \u0639\u0638\u064a\u0645 \u0641\u064a \u062d\u064a\u0627\u062a\u0647\u060c \u0641\u0623\u0635\u0628\u062d \u0641\u064a\u0645\u0627 \u0628\u0639\u062f \u0645\u0646 \u0623\u0639\u064a\u0627\u0646 \u0639\u0644\u0645\u0627\u0621 \u0627\u0644\u0635\u062d\u0627\u0628\u0629 \u0631\u0636\u0648\u0627\u0646 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647\u0645\u060c \u0648\u062f\u062e\u0644 \u0639\u0628\u062f \u0627\u0644\u0644\u0647 \u0641\u064a \u0631\u0643\u0628 \u0627\u0644\u0625\u064a\u0645\u0627\u0646 \u0648\u0647\u0648 \u064a\u064e\u0645\u062e\u0631 \u0628\u062d\u0627\u0631 \u0627\u0644\u0634\u0631\u0643 \u0641\u064a \u0642\u0644\u0639\u0629 \u0627\u0644\u0623\u0635\u0646\u0627\u0645\u060c \u0641\u0643\u0627\u0646 \u0648\u0627\u062d\u062f\u064b\u0627 \u0645\u0646 \u0623\u0648\u0644\u0626\u0643 \u0627\u0644\u0633\u0627\u0628\u0642\u064a\u0646 \u0627\u0644\u0630\u064a\u0646 \u0645\u062f\u062d\u0647\u0645 \u0627\u0644\u0644\u0647 \u0641\u064a \u0642\u0631\u0622\u0646\u0647 \u0627\u0644\u0639\u0638\u064a\u0645\u060c \u0642\u0627\u0644 \u0639\u0646\u0647 \u0627\u0628\u0646 \u062d\u062c\u0631: \xab\u0623\u062d\u062f \u0627\u0644\u0633\u0627\u0628\u0642\u064a\u0646 \u0627\u0644\u0623\u0648\u0644\u064a\u0646\u060c \u0623\u0633\u0644\u0645 \u0642\u062f\u064a\u0645\u064b\u0627\u060c \u0648\u0647\u0627\u062c\u0631 \u0627\u0644\u0647\u062c\u0631\u062a\u064a\u0646\u060c \u0648\u0634\u0647\u062f \u0628\u062f\u0631\u064b\u0627 \u0648\u0627\u0644\u0645\u0634\u0627\u0647\u062f \u0628\u0639\u062f\u0647\u0627\u060c \u0648\u0644\u0627\u0632\u0645 \u0627\u0644\u0646\u0628\u064a \ufdfa \u0648\u0643\u0627\u0646 \u0635\u0627\u062d\u0628 \u0646\u0639\u0644\u064a\u0647\xbb."],t.s)
