B.aSz=s(["\u0628\u0627\u0644\u0631\u063a\u0645 \u0645\u0646 \u0623\u0646 \u0627\u0628\u0646 \u0645\u0633\u0639\u0648\u062f \u0644\u064a\u0633 \u0644\u0647 \u0639\u0634\u064a\u0631\u0629 \u062a\u062d\u0645\u064a\u0647\u060c \u0648\u0643\u0627\u0646 \u0636\u0626\u064a\u0644 \u0627\u0644\u062c\u0633\u0645 \u062f\u0642\u064a\u0642 \u0627\u0644\u0633\u0627\u0642\u064a\u0646\u060c \u0641\u0625\u0646 \u0630\u0644\u0643 \u0644\u0645 \u064a\u064e\u062d\u064f\u0644 \u062f\u0648\u0646 \u0638\u0647\u0648\u0631 \u0634\u062c\u0627\u0639\u062a\u0647 \u0648\u0642\u0648\u0629 \u0646\u0641\u0633\u0647 \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647\u060c \u0648\u0644\u0647 \u0645\u0648\u0627\u0642\u0641 \u0631\u0627\u0626\u0639\u0629 \u0641\u064a \u0630\u0644\u0643\u060c \u0645\u0646\u0647\u0627 \u0630\u0644\u0643 \u0627\u0644\u0645\u0634\u0647\u062f \u0627\u0644\u0645\u062b\u064a\u0631 \u0641\u064a \u0645\u0643\u0629 \u0625\u0628\u0627\u0646 \u0627\u0644\u062f\u0639\u0648\u0629 \u0648\u0634\u062f\u0629 \u0648\u0637\u0623\u0629 \u0642\u0631\u064a\u0634 \u0639\u0644\u064a\u0647\u0627\u060c \u0625\u0630 \u0648\u0642\u0641 \u0639\u0644\u0649 \u0645\u064e\u0644\u064e\u0626\u0647\u0645 \u0648\u062c\u0647\u0631 \u0628\u0627\u0644\u0642\u0631\u0622\u0646\u060c \u0641\u0642\u0631\u064e\u0639 \u0628\u0647 \u0623\u0633\u0645\u0627\u0639\u0647\u0645 \u0627\u0644\u0645\u064f\u0642\u0641\u064e\u0644\u0629 \u0648\u0642\u0644\u0648\u0628\u0647\u0645 \u0627\u0644\u0645\u064f\u063a\u0644\u064e\u0651\u0641\u0629\u060c \u0641\u0643\u0627\u0646 \u0623\u0648\u0644 \u0645\u0646 \u062c\u0647\u0631 \u0628\u0627\u0644\u0642\u0631\u0622\u0646 \u0628\u0639\u062f \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0628\u0645\u0643\u0629.","\u0648\u0642\u0635\u0629 \u0630\u0644\u0643 \u0623\u0646 \u0623\u0635\u062d\u0627\u0628 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \u0627\u062c\u062a\u0645\u0639\u0648\u0627 \u064a\u0648\u0645\u064b\u0627 \u0641\u0642\u0627\u0644\u0648\u0627: \u0648\u0627\u0644\u0644\u0647 \u0645\u0627 \u0633\u0645\u0639\u062a \u0642\u0631\u064a\u0634 \u0647\u0630\u0627 \u0627\u0644\u0642\u0631\u0622\u0646 \u064a\u064f\u062c\u0647\u064e\u0631 \u0644\u0647\u0627 \u0628\u0647 \u0642\u0637\u060c \u0641\u0645\u0646 \u0631\u062c\u0644 \u064a\u064f\u0633\u0645\u0639\u0647\u0645\u061f \u0641\u0642\u0627\u0644 \u0639\u0628\u062f \u0627\u0644\u0644\u0647 \u0628\u0646 \u0645\u0633\u0639\u0648\u062f: \u0623\u0646\u0627\u060c \u0642\u0627\u0644\u0648\u0627: \u0625\u0646\u0627 \u0646\u062e\u0634\u0627\u0647\u0645 \u0639\u0644\u064a\u0643\u060c \u0625\u0646\u0645\u0627 \u0646\u0631\u064a\u062f \u0631\u062c\u0644\u0627\u064b \u0644\u0647 \u0639\u0634\u064a\u0631\u0629 \u064a\u0645\u0646\u0639\u0648\u0646\u0647 \u0645\u0646 \u0627\u0644\u0642\u0648\u0645 \u0625\u0646 \u0623\u0631\u0627\u062f\u0648\u0647\u060c \u0642\u0627\u0644: \u062f\u0639\u0648\u0646\u064a \u0641\u0625\u0646 \u0627\u0644\u0644\u0647 \u0633\u064a\u0645\u0646\u0639\u0646\u064a.","\u0641\u063a\u062f\u0627 \u0627\u0628\u0646 \u0645\u0633\u0639\u0648\u062f \u062d\u062a\u0649 \u0623\u062a\u0649 \u0627\u0644\u0645\u0642\u0627\u0645 \u0641\u064a \u0627\u0644\u0636\u062d\u0649 \u0648\u0642\u0631\u064a\u0634 \u0641\u064a \u0623\u0646\u062f\u064a\u062a\u0647\u0627\u060c \u062d\u062a\u0649 \u0642\u0627\u0645 \u0639\u0646\u062f \u0627\u0644\u0645\u0642\u0627\u0645 \u062b\u0645 \u0642\u0631\u0623: \ufd3f\u0627\u0644\u0631\u0651\u064e\u062d\u0645\u064e\u0670\u0646\u064f \u06dd \u0639\u064e\u0644\u0651\u064e\u0645\u064e \u0627\u0644\u0642\u064f\u0631\u0622\u0646\u064e \u06dd \u062e\u064e\u0644\u064e\u0642\u064e \u0627\u0644\u0625\u0650\u0646\u0633\u064e\u0627\u0646\u064e \u06dd \u0639\u064e\u0644\u0651\u064e\u0645\u064e\u0647\u064f \u0627\u0644\u0628\u064e\u064a\u064e\u0627\u0646\u064e\ufd3e - \u0633\u0648\u0631\u0629 \u0627\u0644\u0631\u062d\u0645\u0646\u060c \u0631\u0627\u0641\u0639\u064b\u0627 \u0628\u0647\u0627 \u0635\u0648\u062a\u0647\u060c \u062b\u0645 \u0627\u0633\u062a\u0642\u0628\u0644\u0647\u0627 \u064a\u0642\u0631\u0624\u0647\u0627\u060c \u0641\u062a\u0623\u0645\u0644\u0648\u0647 \u0648\u062c\u0639\u0644\u0648\u0627 \u064a\u0642\u0648\u0644\u0648\u0646: \u0645\u0627\u0630\u0627 \u0642\u0627\u0644 \u0627\u0628\u0646 \u0623\u0645\u0651 \u0639\u0628\u062f\u061f \u062b\u0645 \u0642\u0627\u0644\u0648\u0627: \u0625\u0646\u0647 \u0644\u064a\u062a\u0644\u0648 \u0628\u0639\u0636 \u0645\u0627 \u062c\u0627\u0621 \u0628\u0647 \u0645\u062d\u0645\u062f\u060c \u0641\u0642\u0627\u0645\u0648\u0627 \u0625\u0644\u064a\u0647 \u0641\u062c\u0639\u0644\u0648\u0627 \u064a\u0636\u0631\u0628\u0648\u0646\u0647 \u0641\u064a \u0648\u062c\u0647\u0647\u060c \u0648\u062c\u0639\u0644 \u064a\u0642\u0631\u0623 \u062d\u062a\u0649 \u0628\u0644\u063a \u0645\u0646\u0647\u0627 \u0645\u0627 \u0634\u0627\u0621 \u0627\u0644\u0644\u0647 \u0623\u0646 \u064a\u0628\u0644\u063a\u060c \u062b\u0645 \u0627\u0646\u0635\u0631\u0641 \u0625\u0644\u0649 \u0623\u0635\u062d\u0627\u0628\u0647 \u0648\u0642\u062f \u0623\u064e\u062b\u064e\u0651\u0631\u0648\u0627 \u0641\u064a \u0648\u062c\u0647\u0647\u060c \u0641\u0642\u0627\u0644\u0648\u0627 \u0644\u0647: \u0647\u0630\u0627 \u0627\u0644\u0630\u064a \u062e\u0634\u064a\u0646\u0627 \u0639\u0644\u064a\u0643\u060c \u0641\u0642\u0627\u0644: \u0645\u0627 \u0643\u0627\u0646 \u0623\u0639\u062f\u0627\u0621 \u0627\u0644\u0644\u0647 \u0623\u0647\u0648\u0646 \u0639\u0644\u064a\u064e\u0651 \u0645\u0646\u0647\u0645 \u0627\u0644\u0622\u0646\u060c \u0648\u0644\u0626\u0646 \u0634\u0626\u062a\u0645 \u0644\u0623\u064f\u063a\u0627\u062f\u064a\u0646\u064e\u0651\u0647\u0645 \u0628\u0645\u062b\u0644\u0647\u0627\u060c \u0642\u0627\u0644\u0648\u0627: \u0644\u0627\u060c \u062d\u0633\u0628\u0643\u060c \u0642\u062f \u0623\u0633\u0645\u0639\u062a\u0647\u0645 \u0645\u0627 \u064a\u0643\u0631\u0647\u0648\u0646.","\u0648\u0628\u0647\u0630\u0627 \u0643\u0627\u0646 \u0639\u0628\u062f \u0627\u0644\u0644\u0647 \u0628\u0646 \u0645\u0633\u0639\u0648\u062f \u0623\u0648\u0644 \u0645\u0646 \u062c\u0647\u0631 \u0628\u0627\u0644\u0642\u0631\u0622\u0646 \u0628\u0645\u0643\u0629 \u0628\u0639\u062f \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa\u060c \u0648\u0643\u0627\u0646 \u0639\u0645\u0644\u0647 \u062a\u062d\u062f\u064a\u064b\u0627 \u0639\u0645\u0644\u064a\u064b\u0627 \u0644\u0642\u0631\u064a\u0634 \u0627\u0644\u062a\u064a \u0645\u0627 \u0643\u0627\u0646\u062a \u0644\u062a\u062a\u062d\u0645\u0644 \u0645\u062b\u0644 \u0647\u0630\u0627 \u0627\u0644\u0645\u0648\u0642\u0641\u060c \u0648\u062a\u0638\u0647\u0631 \u062c\u0631\u0623\u062a\u0647 \u0639\u0644\u064a\u0647\u0645 \u0628\u0639\u062f \u0647\u0630\u0647 \u0627\u0644\u062a\u062c\u0631\u0628\u0629 \u0639\u0644\u0649 \u0627\u0644\u0631\u063a\u0645 \u0645\u0645\u0627 \u0623\u0635\u0627\u0628\u0647 \u0645\u0646 \u0623\u0630\u0649."],t.s)
