B.aAd=s(["\u062a\u0648\u0641\u064a\u062a \u0627\u0644\u0633\u064a\u062f\u0629\u064f \u062e\u062f\u064a\u062c\u0629\u064f \u0623\u0645\u064f\u0651 \u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646 \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647\u0627 \u0642\u0628\u0644 \u0627\u0644\u0647\u062c\u0631\u0629 \u0625\u0644\u0649 \u0627\u0644\u0645\u062f\u064a\u0646\u0629 \u0628\u062b\u0644\u0627\u062b \u0633\u0646\u064a\u0646\u060c \u0641\u064a \u0646\u0641\u0633 \u0639\u0627\u0645 \u0648\u0641\u0627\u0629 \u0623\u0628\u064a \u0637\u0627\u0644\u0628\u060c \u0641\u062a\u0636\u0627\u0639\u0641 \u0627\u0644\u0623\u0633\u0649 \u0648\u0627\u0644\u062d\u0632\u0646\u064f \u0639\u0644\u0649 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0628\u0641\u0642\u062f \u0647\u0630\u064a\u0646 \u0627\u0644\u062d\u0628\u064a\u0628\u064a\u0646 \u0627\u0644\u0644\u0630\u064a\u0646 \u0643\u0627\u0646\u0627 \u062f\u0639\u0627\u0645\u062a\u064e\u064a\u0646 \u0645\u0646 \u062f\u0639\u0627\u0626\u0645 \u0627\u0644\u062f\u0639\u0648\u0629 \u0641\u064a \u0623\u0632\u0645\u0627\u062a\u0647\u0627\u061b \u0643\u0627\u0646 \u0623\u0628\u0648 \u0637\u0627\u0644\u0628 \u0627\u0644\u0633\u0646\u062f\u064e \u0627\u0644\u062e\u0627\u0631\u062c\u064a\u064e\u0651 \u0627\u0644\u0630\u064a \u064a\u062f\u0641\u0639 \u0639\u0646\u0647 \u0627\u0644\u0642\u0648\u0645\u064e\u060c \u0648\u0643\u0627\u0646\u062a \u062e\u062f\u064a\u062c\u0629\u064f \u0627\u0644\u0633\u0646\u062f\u064e \u0627\u0644\u062f\u0627\u062e\u0644\u064a\u064e\u0651 \u0627\u0644\u0630\u064a \u064a\u064f\u062e\u0641\u0650\u0651\u0641 \u0639\u0646\u0647 \u0627\u0644\u0623\u0632\u0645\u0627\u062a\u0650 \u0648\u0627\u0644\u0645\u062d\u0646\u060c \u0641\u062a\u062c\u0631\u064e\u0651\u0623 \u0643\u0641\u0627\u0631\u064f \u0642\u0631\u064a\u0634 \u0639\u0644\u0649 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0648\u0646\u0627\u0644\u0648\u0627 \u0645\u0646\u0647 \u0645\u0627 \u0644\u0645 \u064a\u0643\u0648\u0646\u0648\u0627 \u064a\u0637\u0645\u0639\u0648\u0646 \u0628\u0647 \u0641\u064a \u062d\u064a\u0627\u0629 \u0623\u0628\u064a \u0637\u0627\u0644\u0628.","\u0648\u0627\u0628\u062a\u062f\u0623\u062a \u0628\u0630\u0644\u0643 \u0645\u0631\u062d\u0644\u0629 \u0639\u0635\u064a\u0628\u0629 \u0641\u064a \u062d\u064a\u0627\u0629 \u0627\u0644\u0631\u0633\u0648\u0644 \ufdfa \u0648\u0627\u062c\u064e\u0647 \u0641\u064a\u0647\u0627 \u0643\u062b\u064a\u0631\u0627\u064b \u0645\u0646 \u0627\u0644\u0645\u0634\u0643\u0644\u0627\u062a \u0648\u0627\u0644\u0645\u0635\u0627\u0639\u0628 \u0648\u0627\u0644\u0645\u062d\u0646 \u0648\u0627\u0644\u0641\u062a\u0646\u060c \u062d\u064a\u0646 \u0623\u0635\u0628\u062d \u0641\u064a \u0627\u0644\u0633\u0627\u062d\u0629 \u0648\u062d\u064a\u062f\u0627\u064b \u0644\u0627 \u0646\u0627\u0635\u0631 \u0644\u0647 \u0625\u0644\u0627 \u0627\u0644\u0644\u0647 \u0633\u0628\u062d\u0627\u0646\u0647 \u0648\u062a\u0639\u0627\u0644\u0649\u060c \u0648\u0645\u0639 \u0647\u0630\u0627 \u0645\u0636\u0649 \u0641\u064a \u062a\u0628\u0644\u064a\u063a \u0631\u0633\u0627\u0644\u0629 \u0631\u0628\u0647 \u0625\u0644\u0649 \u0627\u0644\u0646\u0627\u0633 \u0643\u0627\u0641\u0629 \u0639\u0644\u0649 \u0645\u0627 \u064a\u0644\u0642\u0649 \u0645\u0646 \u0627\u0644\u062e\u0644\u0627\u0641 \u0648\u0627\u0644\u0623\u0630\u0649 \u0627\u0644\u0634\u062f\u064a\u062f\u060c \u0627\u0644\u0630\u064a \u0623\u0641\u0627\u0636\u062a \u0643\u062a\u0628\u064f \u0627\u0644\u062d\u062f\u064a\u062b \u0648\u0643\u062a\u0628\u064f \u0627\u0644\u0633\u064a\u0631 \u0628\u0623\u0633\u0627\u0646\u064a\u062f\u0647\u0627 \u0627\u0644\u0635\u062d\u064a\u062d\u0629 \u0627\u0644\u062b\u0627\u0628\u062a\u0629 \u0641\u064a \u0627\u0644\u062d\u062f\u064a\u062b \u0639\u0646\u0647\u060c \u0648\u062a\u062d\u0645\u064e\u0651\u0644 \ufdfa \u0645\u0646 \u0630\u0644\u0643 \u0645\u0627 \u062a\u064e\u0646\u0648\u0621 \u0627\u0644\u062c\u0628\u0627\u0644\u064f \u0628\u062d\u0645\u0644\u0647\u060c \u0648\u0644\u0645\u0627 \u062a\u0643\u0627\u0644\u0628\u062a \u0627\u0644\u0641\u062a\u0646\u064f \u0648\u0627\u0644\u0645\u062d\u0646\u064f \u0639\u0644\u0649 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0641\u064a \u0628\u0644\u062f\u0647 \u0627\u0644\u0630\u064a \u0646\u064e\u0628\u064e\u062a \u0641\u064a\u0647 \u0648\u0628\u064a\u0646 \u0642\u0648\u0645\u0647 \u0627\u0644\u0630\u064a\u0646 \u064a\u0639\u0631\u0641\u0648\u0646 \u0639\u0646\u0647 \u0643\u0644\u064e\u0651 \u0635\u063a\u064a\u0631\u0629 \u0648\u0643\u0628\u064a\u0631\u0629\u060c \u0639\u064e\u0632\u064e\u0645 \ufdfa \u0639\u0644\u0649 \u0623\u0646 \u064a\u0646\u062a\u0642\u0644 \u0625\u0644\u0649 \u0628\u0644\u062f\u064d \u063a\u064a\u0631 \u0628\u0644\u062f\u0647 \u0648\u0642\u0648\u0645\u064d \u063a\u064a\u0631 \u0642\u0648\u0645\u0647\u060c \u064a\u0639\u0631\u0636 \u0639\u0644\u064a\u0647\u0645 \u062f\u0639\u0648\u062a\u064e\u0647 \u0648\u064a\u0644\u062a\u0645\u0633 \u0645\u0646\u0647\u0645 \u0646\u0635\u0631\u062a\u064e\u0647\u0645 \u0631\u062c\u0627\u0621\u064e \u0623\u0646 \u064a\u0642\u0628\u0644\u0648\u0627 \u0645\u0646\u0647 \u0645\u0627 \u062c\u0627\u0621\u0647\u0645 \u0628\u0647 \u0645\u0646 \u0627\u0644\u0644\u0647 \u0639\u0632 \u0648\u062c\u0644\u060c \u0641\u062e\u0631\u062c \u0625\u0644\u0649 \u0627\u0644\u0637\u0627\u0626\u0641 \u0648\u0647\u064a \u0645\u0646 \u0623\u0642\u0631\u0628 \u0627\u0644\u0628\u0644\u0627\u062f \u0625\u0644\u0649 \u0645\u0643\u0629."],t.s)
