B.aEL=s(["\u0643\u0627\u0646 \u0631\u0633\u0648\u0644\u064f \u0627\u0644\u0644\u0647 \ufdfa \u0644\u0627 \u064a\u0633\u0645\u0639\u064f \u0628\u0642\u0627\u062f\u0645\u064d \u064a\u0642\u062f\u0645\u064f \u0645\u0643\u0629\u064e \u0645\u0646 \u0627\u0644\u0639\u0631\u0628 \u0644\u0647 \u0627\u0633\u0645\u064c \u0648\u0634\u0631\u0641\u064c \u0625\u0644\u0627 \u062a\u0635\u062f\u064e\u0651\u0649 \u0644\u0647 \u0648\u062f\u0639\u0627\u0647 \u0625\u0644\u0649 \u0627\u0644\u0644\u0647 \u0648\u0639\u064e\u0631\u064e\u0636\u064e \u0639\u0644\u064a\u0647 \u0645\u0627 \u062c\u0627\u0621 \u0628\u0647 \u0645\u0646 \u0627\u0644\u0647\u064f\u062f\u0649 \u0648\u0627\u0644\u062d\u0642\u060c \u0648\u0643\u0627\u0646 \u0645\u0646 \u0628\u064a\u0646 \u0645\u0646 \u0644\u0642\u064a\u064e\u0647\u0645 \u0631\u062c\u0644\u0627\u0646 \u0645\u0646 \u064a\u062b\u0631\u0628 \u0644\u0645 \u064a\u064f\u0643\u062a\u0628 \u0644\u062f\u0639\u0648\u062a\u0647\u0645\u0627 \u0623\u0646 \u062a\u064f\u062b\u0645\u0631 \u062b\u0645\u0627\u0631\u064e\u0647\u0627 \u0643\u0627\u0645\u0644\u0629\u064b \u0628\u0639\u062f\u064f\u060c \u0641\u0642\u064e\u062f\u0650\u0645\u064e \u0633\u064f\u0648\u064e\u064a\u062f\u064f \u0628\u0646\u064f \u0627\u0644\u0635\u0627\u0645\u062a -\u0623\u062e\u0648 \u0628\u0646\u064a \u0639\u0645\u0631\u0648 \u0628\u0646 \u0639\u0648\u0641- \u0645\u0643\u0629\u064e \u062d\u0627\u062c\u064b\u0651\u0627 \u0623\u0648 \u0645\u064f\u0639\u062a\u0645\u0650\u0631\u064b\u0627\u060c \u0648\u0643\u0627\u0646 \u0642\u0648\u0645\u064f\u0647 \u064a\u064f\u0633\u0645\u064f\u0651\u0648\u0646\u0647 \u0641\u064a\u0647\u0645 \u0627\u0644\u0643\u0627\u0645\u0644 \u0644\u062c\u064e\u0644\u064e\u062f\u0650\u0647 \u0648\u0634\u0650\u0639\u0631\u0647 \u0648\u0634\u0631\u0641\u0647 \u0648\u0646\u0633\u0628\u0647\u060c \u0641\u0642\u0635\u062f\u064e\u0647 \u0631\u0633\u0648\u0644\u064f \u0627\u0644\u0644\u0647 \ufdfa \u062d\u064a\u0646 \u0633\u0645\u0639 \u0628\u0647 \u0641\u062f\u0639\u0627\u0647 \u0625\u0644\u0649 \u0627\u0644\u0644\u0647 \u0648\u0627\u0644\u0625\u0633\u0644\u0627\u0645\u060c \u0641\u0642\u0627\u0644 \u0644\u0647 \u0633\u0648\u064a\u062f: \u0641\u0644\u0639\u0644\u064e\u0651 \u0627\u0644\u0630\u064a \u0645\u0639\u0643 \u0645\u062b\u0644\u064f \u0627\u0644\u0630\u064a \u0645\u0639\u064a\u061f \u0641\u0642\u0627\u0644 \u0644\u0647 \u0631\u0633\u0648\u0644\u064f \u0627\u0644\u0644\u0647 \ufdfa: \xab\u0648\u0645\u0627 \u0627\u0644\u0630\u064a \u0645\u0639\u0643\u061f\xbb\u060c \u0642\u0627\u0644: \u0645\u064e\u062c\u064e\u0644\u064e\u0651\u0629\u064f \u0644\u0642\u0645\u0627\u0646 -\u0627\u0644\u0635\u062d\u064a\u0641\u0629 \u0648\u062a\u064f\u0637\u0644\u064e\u0642 \u0639\u0644\u0649 \u0627\u0644\u062d\u0643\u0645\u0629- \u0623\u064a \u062d\u0643\u0645\u0629 \u0644\u0642\u0645\u0627\u0646\u060c \u0641\u0642\u0627\u0644 \u0644\u0647 \u0631\u0633\u0648\u0644\u064f \u0627\u0644\u0644\u0647 \ufdfa: \xab\u0627\u0639\u0631\u0650\u0636\u0647\u0627 \u0639\u0644\u064a\u064e\u0651\xbb\u060c \u0641\u0639\u064e\u0631\u064e\u0636\u064e\u0647\u0627 \u0639\u0644\u064a\u0647\u060c \u0641\u0642\u0627\u0644: \xab\u0625\u0646 \u0647\u0630\u0627 \u0627\u0644\u0643\u0644\u0627\u0645\u064e \u062d\u0633\u0646\u060c \u0648\u0627\u0644\u0630\u064a \u0645\u0639\u064a \u0623\u0641\u0636\u0644\u064f \u0645\u0646 \u0647\u0630\u0627\u060c \u0642\u0631\u0622\u0646\u064c \u0623\u0646\u0632\u0644\u0647 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u064e\u0651\u060c \u0647\u0648 \u0647\u064f\u062f\u0649\u064b \u0648\u0646\u0648\u0631\xbb\u060c \u0641\u062a\u0644\u0627 \u0639\u0644\u064a\u0647 \u0631\u0633\u0648\u0644\u064f \u0627\u0644\u0644\u0647 \ufdfa \u0627\u0644\u0642\u0631\u0622\u0646\u064e \u0648\u062f\u0639\u0627\u0647 \u0625\u0644\u0649 \u0627\u0644\u0625\u0633\u0644\u0627\u0645\u060c \u0641\u0644\u0645 \u064a\u064e\u0628\u0639\u064f\u062f \u0645\u0646\u0647\u060c \u0648\u0642\u0627\u0644: \u0625\u0646 \u0647\u0630\u0627 \u0627\u0644\u0642\u0648\u0644\u064e \u0644\u064e\u062d\u0633\u064e\u0646\u060c \u062b\u0645 \u0627\u0646\u0635\u0631\u0641\u064e \u0639\u0646\u0647 \u0641\u0642\u064e\u062f\u0650\u0645\u064e \u0627\u0644\u0645\u062f\u064a\u0646\u0629\u064e \u0639\u0644\u0649 \u0642\u0648\u0645\u0647\u060c \u0641\u0644\u0645 \u064a\u064e\u0644\u0628\u064e\u062b \u0623\u0646 \u0642\u062a\u0644\u0647 \u0627\u0644\u062e\u0632\u0631\u062c\u060c \u0648\u0642\u062f \u0643\u0627\u0646 \u0631\u062c\u0627\u0644\u064c \u0645\u0646 \u0642\u0648\u0645\u0647 \u064a\u0642\u0648\u0644\u0648\u0646: \u0625\u0646\u0627 \u0644\u0646\u0631\u0627\u0647 \u0642\u064f\u062a\u0650\u0644\u064e \u0648\u0647\u0648 \u0645\u0633\u0644\u0645\u060c \u0648\u0643\u0627\u0646 \u0642\u062a\u0644\u064f\u0647 \u064a\u0648\u0645\u064e \u0628\u064f\u0639\u0627\u062b\u060c \u0648\u0639\u0644\u0649 \u0623\u064a\u064e\u0651\u0629 \u062d\u0627\u0644 \u0644\u0627 \u062a\u0648\u062c\u062f \u062f\u0644\u0627\u0626\u0644\u064f \u0639\u0644\u0649 \u0642\u064a\u0627\u0645 \u0633\u064f\u0648\u064e\u064a\u062f \u0628\u0646 \u0627\u0644\u0635\u0627\u0645\u062a \u0628\u0627\u0644\u062f\u0639\u0648\u0629 \u0625\u0644\u0649 \u0627\u0644\u0625\u0633\u0644\u0627\u0645 \u0648\u0633\u0637 \u0642\u0648\u0645\u0647.","\u0648\u0643\u0630\u0644\u0643 \u0643\u0627\u0646 \u0627\u0644\u0623\u0645\u0631\u064f \u0645\u0639 \u0625\u064a\u0627\u0633 \u0628\u0646 \u0645\u0639\u0627\u0630\u060c \u0641\u0644\u0645\u064e\u0651\u0627 \u0642\u064e\u062f\u0650\u0645\u064e \u0623\u0628\u0648 \u0627\u0644\u062d\u064e\u064a\u0633\u064e\u0631 \u0628\u0646 \u0631\u0627\u0641\u0639 \u0645\u0643\u0629\u064e \u0648\u0645\u0639\u0647 \u0641\u062a\u064a\u0627\u0646\u064c \u0645\u0646 \u0628\u0646\u064a \u0639\u0628\u062f \u0627\u0644\u0623\u0634\u0647\u0644\u060c \u0641\u064a\u0647\u0645 \u0625\u064a\u0627\u0633\u064f \u0628\u0646\u064f \u0645\u064f\u0639\u0627\u0630\u060c \u064a\u0644\u062a\u0645\u0633\u0648\u0646 \u0627\u0644\u062d\u0644\u0641\u064e \u0645\u0646 \u0642\u0631\u064a\u0634 \u0639\u0644\u0649 \u0642\u0648\u0645\u0647\u0645 \u0645\u0646 \u0627\u0644\u062e\u0632\u0631\u062c\u060c \u0633\u0645\u0639 \u0628\u0647\u0645 \u0631\u0633\u0648\u0644\u064f \u0627\u0644\u0644\u0647 \ufdfa \u0641\u0623\u062a\u0627\u0647\u0645 \u0648\u062c\u0644\u0633 \u0625\u0644\u064a\u0647\u0645\u060c \u0641\u0642\u0627\u0644: \xab\u0647\u0644 \u0644\u0643\u0645 \u0641\u064a \u062e\u064a\u0631\u064d \u0645\u0645\u0627 \u062c\u0626\u062a\u0645 \u0644\u0647\u061f\xbb\u060c \u0642\u0627\u0644\u0648\u0627: \u0648\u0645\u0627 \u0630\u0627\u0643\u061f \u0642\u0627\u0644: \xab\u0623\u0646\u0627 \u0631\u0633\u0648\u0644\u064f \u0627\u0644\u0644\u0647 \u0625\u0644\u0649 \u0627\u0644\u0639\u0628\u0627\u062f\u060c \u0623\u062f\u0639\u0648\u0647\u0645 \u0625\u0644\u0649 \u0623\u0646 \u064a\u0639\u0628\u062f\u0648\u0627 \u0627\u0644\u0644\u0647 \u0648\u0644\u0627 \u064a\u064f\u0634\u0631\u0643\u0648\u0627 \u0628\u0647 \u0634\u064a\u0626\u064b\u0627\u060c \u0648\u0623\u064f\u0646\u0632\u0650\u0644\u064e \u0639\u0644\u064a\u064e\u0651 \u0627\u0644\u0643\u062a\u0627\u0628\xbb\u060c \u062b\u0645 \u0630\u064e\u0643\u064e\u0631\u064e \u0644\u0647\u0645 \u0627\u0644\u0625\u0633\u0644\u0627\u0645\u064e \u0648\u062a\u0644\u0627 \u0639\u0644\u064a\u0647\u0645 \u0627\u0644\u0642\u0631\u0622\u0646\u060c \u0641\u0642\u0627\u0644 \u0625\u064a\u0627\u0633\u064f \u0628\u0646\u064f \u0645\u064f\u0639\u0627\u0630 \u0648\u0643\u0627\u0646 \u063a\u0644\u0627\u0645\u064b\u0627 \u062d\u064e\u062f\u064e\u062b\u064b\u0627: \u0647\u0630\u0627 \u0648\u0627\u0644\u0644\u0647\u0650 \u062e\u064a\u0631\u064c \u0645\u0645\u0627 \u062c\u0626\u062a\u0645 \u0644\u0647\u060c \u0641\u0623\u062e\u0630\u064e \u0623\u0628\u0648 \u0627\u0644\u062d\u064e\u064a\u0633\u064e\u0631 \u0643\u0641\u064b\u0651\u0627 \u0645\u0646 \u062a\u0631\u0627\u0628 \u0641\u0636\u064e\u0631\u064e\u0628\u064e \u0628\u0647 \u0648\u062c\u0647\u064e\u0647 \u0648\u0642\u0627\u0644: \u062f\u064e\u0639\u0646\u0627 \u0645\u0646\u0643\u060c \u0641\u0644\u064e\u0639\u064e\u0645\u0631\u064a \u0644\u0642\u062f \u062c\u0626\u0646\u0627 \u0644\u063a\u064a\u0631 \u0647\u0630\u0627\u060c \u0641\u0635\u064e\u0645\u064e\u062a\u064e \u0625\u064a\u0627\u0633\u060c \u0648\u0642\u0627\u0645\u064e \u0631\u0633\u0648\u0644\u064f \u0627\u0644\u0644\u0647 \ufdfa \u0639\u0646\u0647\u0645 \u0648\u0627\u0646\u0635\u0631\u0641\u0648\u0627 \u0625\u0644\u0649 \u0627\u0644\u0645\u062f\u064a\u0646\u0629\u060c \u0648\u0643\u0627\u0646\u062a \u0648\u0642\u0639\u0629\u064f \u0628\u064f\u0639\u0627\u062b \u0628\u064a\u0646 \u0627\u0644\u0623\u0648\u0633 \u0648\u0627\u0644\u062e\u0632\u0631\u062c\u060c \u062b\u0645 \u0644\u0645 \u064a\u064e\u0644\u0628\u064e\u062b \u0625\u064a\u0627\u0633\u064f \u0628\u0646\u064f \u0645\u064f\u0639\u0627\u0630 \u0623\u0646 \u0647\u0644\u0643\u060c \u0648\u0642\u062f \u0631\u064f\u0648\u0650\u064a\u064e \u0639\u0645\u064e\u0651\u0646 \u062d\u064e\u0636\u064e\u0631\u064e\u0647 \u0645\u0646 \u0642\u0648\u0645\u0647 \u0623\u0646\u0647 \u0645\u0627 \u0632\u0627\u0644 \u064a\u064f\u0647\u064e\u0644\u0650\u0651\u0644\u064f \u0627\u0644\u0644\u0647\u064e \u0648\u064a\u064f\u0643\u0628\u0650\u0651\u0631\u0647 \u0648\u064a\u062d\u0645\u062f\u0647 \u0648\u064a\u064f\u0633\u0628\u0650\u0651\u062d\u0647 \u062d\u062a\u0649 \u0645\u0627\u062a\u060c \u0641\u0645\u0627 \u0643\u0627\u0646\u0648\u0627 \u064a\u064e\u0634\u064f\u0643\u064f\u0651\u0648\u0646 \u0623\u0646\u0647 \u0645\u0627\u062a \u0645\u0633\u0644\u0645\u064b\u0627\u060c \u0644\u0642\u062f \u0643\u0627\u0646 \u0627\u0633\u062a\u0634\u0639\u0631\u064e \u0627\u0644\u0625\u0633\u0644\u0627\u0645\u064e \u0641\u064a \u0630\u0644\u0643 \u0627\u0644\u0645\u062c\u0644\u0633 \u062d\u064a\u0646 \u0633\u0645\u0639 \u0645\u0646 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0645\u0627 \u0633\u0645\u0639."],t.s)
