B.aLw=s(["\u0648\u0628\u0639\u062b \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0645\u0639 \u0627\u0644\u0645\u0628\u0627\u064a\u0650\u0639\u064a\u0646 \u0645\u0635\u0639\u0628\u064e \u0628\u0646 \u0639\u0645\u064a\u0631 \u064a\u064f\u0639\u0644\u0650\u0651\u0645\u0647\u0645 \u0627\u0644\u062f\u064a\u0646 \u0648\u064a\u064f\u0642\u0631\u0626\u0647\u0645 \u0627\u0644\u0642\u0631\u0622\u0646\u060c \u0641\u0643\u0627\u0646 \u064a\u064f\u0633\u0645\u064e\u0651\u0649 \u0641\u064a \u0627\u0644\u0645\u062f\u064a\u0646\u0629 \u0628\u0627\u0644\u0645\u064f\u0642\u0631\u0626\u060c \u0648\u0643\u0627\u0646 \u064a\u0624\u0645\u0651\u0647\u0645 \u0641\u064a \u0627\u0644\u0635\u0644\u0627\u0629\u060c \u0648\u0627\u062e\u062a\u0627\u0631\u0647 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0639\u0646 \u0639\u0644\u0645\u064d \u0628\u0634\u062e\u0635\u064a\u062a\u0647 \u0645\u0646 \u062c\u0647\u0629\u060c \u0648\u0639\u0644\u0645\u064d \u0628\u0627\u0644\u0648\u0636\u0639 \u0627\u0644\u0642\u0627\u0626\u0645 \u0641\u064a \u0627\u0644\u0645\u062f\u064a\u0646\u0629 \u0645\u0646 \u062c\u0647\u0629 \u0623\u062e\u0631\u0649\u061b \u0625\u0630 \u0643\u0627\u0646 \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647\u060c \u0625\u0644\u0649 \u062c\u0627\u0646\u0628 \u062d\u0641\u0638\u0647 \u0644\u0645\u0627 \u0646\u0632\u0644 \u0645\u0646 \u0627\u0644\u0642\u0631\u0622\u0646\u060c \u064a\u0645\u0644\u0643 \u0645\u0646 \u0627\u0644\u0644\u0628\u0627\u0642\u0629 \u0648\u0627\u0644\u0647\u062f\u0648\u0621 \u0648\u062d\u0633\u0646 \u0627\u0644\u062e\u0644\u0642 \u0648\u0627\u0644\u062d\u0643\u0645\u0629 \u0642\u062f\u0631\u0627\u064b \u0643\u0628\u064a\u0631\u0627\u064b\u060c \u0641\u0636\u0644\u0627\u064b \u0639\u0646 \u0642\u0648\u0629 \u0625\u064a\u0645\u0627\u0646\u0647 \u0648\u0634\u062f\u0629 \u062d\u0645\u0627\u0633\u0647 \u0644\u0644\u062f\u064a\u0646.","\u0648\u0646\u0632\u0644 \u0645\u0635\u0639\u0628\u064c \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647 \u0641\u064a \u064a\u062b\u0631\u0628 \u0639\u0644\u0649 \u0623\u0633\u0639\u062f \u0628\u0646 \u0632\u0631\u0627\u0631\u0629 \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647\u060c \u0648\u0646\u0634\u0637 \u0627\u0644\u0645\u0633\u0644\u0645\u0648\u0646 \u0641\u064a \u0627\u0644\u062f\u0639\u0648\u0629 \u0625\u0644\u0649 \u0627\u0644\u0644\u0647 \u064a\u0642\u0648\u062f \u062a\u0644\u0643 \u0627\u0644\u062d\u0631\u0643\u0629\u064e \u0627\u0644\u062f\u0639\u0648\u064a\u0629 \u0627\u0644\u0631\u0627\u0626\u062f\u0629 \u0645\u0635\u0639\u0628\u064c \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647\u060c \u0648\u0642\u062f \u0627\u0646\u062a\u0647\u062c \u0645\u0646\u0647\u062c \u0627\u0644\u0642\u0631\u0622\u0646 \u0627\u0644\u0643\u0631\u064a\u0645 \u0641\u064a \u062f\u0639\u0648\u062a\u0647 \u0627\u0644\u0630\u064a \u062a\u0639\u0644\u0651\u0645\u0647 \u0645\u0646 \u0625\u0645\u0627\u0645\u0647 \ufdfa\u060c \u0645\u064f\u062c\u0633\u0650\u0651\u062f\u0627\u064b \u0642\u0648\u0644\u064e\u0647 \u062a\u0639\u0627\u0644\u0649: \ufd3f\u0627\u062f\u0639\u064f \u0625\u0650\u0644\u064e\u0649\u0670 \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u0628\u0650\u0627\u0644\u062d\u0650\u0643\u0645\u064e\u0629\u0650 \u0648\u064e\u0627\u0644\u0645\u064e\u0648\u0639\u0650\u0638\u064e\u0629\u0650 \u0627\u0644\u062d\u064e\u0633\u064e\u0646\u064e\u0629\u0650 \u0648\u064e\u062c\u064e\u0627\u062f\u0650\u0644\u0647\u064f\u0645 \u0628\u0650\u0627\u0644\u0651\u064e\u062a\u0650\u064a \u0647\u0650\u064a\u064e \u0623\u064e\u062d\u0633\u064e\u0646\u064f \u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u064e\u0643\u064e \u0647\u064f\u0648\u064e \u0623\u064e\u0639\u0644\u064e\u0645\u064f \u0628\u0650\u0645\u064e\u0646 \u0636\u064e\u0644\u0651\u064e \u0639\u064e\u0646 \u0633\u064e\u0628\u0650\u064a\u0644\u0650\u0647\u0650 \u0648\u064e\u0647\u064f\u0648\u064e \u0623\u064e\u0639\u0644\u064e\u0645\u064f \u0628\u0650\u0627\u0644\u0645\u064f\u0647\u062a\u064e\u062f\u0650\u064a\u0646\u064e\ufd3e - \u0633\u0648\u0631\u0629 \u0627\u0644\u0646\u062d\u0644.","\u0648\u0644\u0645 \u062a\u0645\u0636 \u0623\u0634\u0647\u0631\u064c \u062d\u062a\u0649 \u062a\u0645\u0643\u0651\u0646 \u0645\u0646 \u0646\u0634\u0631 \u0627\u0644\u0625\u0633\u0644\u0627\u0645 \u0641\u064a \u0633\u0627\u0626\u0631 \u0628\u064a\u0648\u062a\u0627\u062a \u0627\u0644\u0645\u062f\u064a\u0646\u0629\u060c \u0648\u0643\u064e\u0633\u064e\u0628 \u0644\u0644\u0625\u0633\u0644\u0627\u0645 \u0623\u0646\u0635\u0627\u0631\u0627\u064b \u0645\u0646 \u0643\u0628\u0627\u0631 \u0632\u0639\u0645\u0627\u0621 \u0627\u0644\u0645\u062f\u064a\u0646\u0629 \u0643\u0633\u0639\u062f \u0628\u0646 \u0645\u0639\u0627\u0630 \u0648\u0623\u064f\u0633\u064a\u062f \u0628\u0646 \u062d\u064f\u0636\u064e\u064a\u0631\u060c \u0641\u0623\u0633\u0644\u0645 \u0628\u0625\u0633\u0644\u0627\u0645\u0647\u0645\u0627 \u062e\u0644\u0642\u064c \u0643\u062b\u064a\u0631 \u0645\u0646 \u0642\u0648\u0645\u0647\u0645\u060c \u0648\u0647\u0643\u0630\u0627 \u0646\u062c\u062d\u062a \u0633\u0641\u0627\u0631\u0629\u064f \u0645\u0635\u0639\u0628 \u0628\u0646 \u0639\u0645\u064a\u0631 \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647 \u0641\u064a \u0634\u0631\u062d \u062a\u0639\u0627\u0644\u064a\u0645 \u0627\u0644\u062f\u064a\u0646 \u0627\u0644\u062c\u062f\u064a\u062f \u0648\u062a\u0639\u0644\u064a\u0645 \u0627\u0644\u0642\u0631\u0622\u0646 \u0648\u062a\u0641\u0633\u064a\u0631\u0647\u060c \u0648\u0641\u064a \u062a\u0642\u0648\u064a\u0629 \u0627\u0644\u0631\u0648\u0627\u0628\u0637 \u0627\u0644\u0623\u062e\u0648\u064a\u0629 \u0628\u064a\u0646 \u0623\u0641\u0631\u0627\u062f \u0627\u0644\u0642\u0628\u0627\u0626\u0644 \u0627\u0644\u0645\u0624\u0645\u0646\u0629\u060c \u0648\u0628\u064a\u0646 \u0627\u0644\u0646\u0628\u064a \ufdfa \u0648\u0635\u062d\u0628\u0647 \u0628\u0645\u0643\u0629 \u0627\u0644\u0645\u0643\u0631\u0645\u0629\u060c \u0644\u0625\u064a\u062c\u0627\u062f \u0627\u0644\u0642\u0627\u0639\u062f\u0629 \u0627\u0644\u0623\u0645\u064a\u0646\u0629 \u0644\u0627\u0646\u0637\u0644\u0627\u0642 \u0627\u0644\u062f\u0639\u0648\u0629."],t.s)
